insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('aux-ayto-mad:8-edc4a43826','aux-ayto-mad',8,'La autorización de pruebas deportivas corresponde al Ayuntamiento de Madrid cuando discurran:','["Íntegra y exclusivamente por el casco urbano, exceptuadas las travesías que no sean vías urbanas", "Por el casco urbano y por las carreteras de la Comunidad de Madrid colindantes", "Por cualquier vía del término municipal, incluidas las interurbanas y las travesías"]'::jsonb,0,'Art. 40 d) Ley 22/2006','Le corresponde autorizar las pruebas deportivas que discurran íntegra y exclusivamente por el casco urbano, salvo travesías que no sean vías urbanas. Si solo pasan en parte por el término municipal, emite un informe preceptivo.',null),
('aux-ayto-mad:8-38ee61df08','aux-ayto-mad',8,'Cuando una prueba deportiva discurra solo en parte de su recorrido por el término municipal de Madrid, el Ayuntamiento:','["Autoriza la prueba en todo caso, por pasar por su término", "No tiene ninguna intervención", "Emite un informe preceptivo para su autorización"]'::jsonb,2,'Art. 40 d) Ley 22/2006','En ese caso corresponde al Ayuntamiento el informe, que será preceptivo, para la autorización de la prueba deportiva.',null),
('aux-ayto-mad:8-5d95b16b66','aux-ayto-mad',8,'Según la Ley 22/2006, la competencia del Ayuntamiento de Madrid en materia de seguridad vial incluye:','["La expedición de los permisos de conducción a los residentes", "La matriculación de los vehículos de los residentes en el municipio", "La instrucción de atestados en caso de accidentes de circulación"]'::jsonb,2,'Art. 40 Ley 22/2006','Le corresponde la policía administrativa preventiva de la seguridad vial en las vías urbanas, incluida la instrucción de atestados en caso de accidentes de circulación.',null),
('aux-ayto-mad:8-973b4a0584','aux-ayto-mad',8,'El Ayuntamiento de Madrid puede acordar la inmovilización de un vehículo por incumplimiento de las normas de estacionamiento:','["Hasta que se pague la multa correspondiente", "Durante un plazo máximo de veinticuatro horas", "Hasta la identificación del conductor"]'::jsonb,2,'Art. 41.1.ª a) Ley 22/2006','El art. 41.1.ª a) permite la inmovilización por incumplimiento de las normas de estacionamiento, incluidas las que lo limitan en el tiempo, hasta la identificación del conductor.',null),
('aux-ayto-mad:8-6fe2550ca6','aux-ayto-mad',8,'¿Cuál de los siguientes es un supuesto de retirada de vehículos previsto en la Ley 22/2006?','["Circulación sin cobertura del seguro obligatorio de responsabilidad civil", "Estacionamiento indebido en las zonas de estacionamiento restringido", "Superación de los niveles máximos de emisión de ruidos"]'::jsonb,1,'Art. 41.2.ª c) Ley 22/2006','El estacionamiento indebido en zonas de estacionamiento restringido es supuesto de retirada (art. 41.2.ª c). La falta de seguro y el exceso de emisiones son supuestos de inmovilización (art. 41.1.ª).',null),
('aux-ayto-mad:8-594455385d','aux-ayto-mad',8,'¿Cuál de los siguientes es un supuesto de inmovilización (y no de retirada) de vehículos en la Ley de Capitalidad?','["Ofrecer en venta el propio vehículo estacionado en la vía pública", "Que el vehículo obstaculice o dificulte la circulación", "Circulación sin cobertura del preceptivo seguro"]'::jsonb,2,'Art. 41.1.ª d) Ley 22/2006','La circulación sin seguro es supuesto de inmovilización (art. 41.1.ª d). Obstaculizar la circulación y ofrecer el vehículo en venta en la vía pública son supuestos de retirada (art. 41.2.ª).',null),
('aux-ayto-mad:8-aa3ff2d435','aux-ayto-mad',8,'Según la Ley 22/2006, los gastos derivados de la inmovilización o retirada de un vehículo:','["Son por cuenta del titular, y su abono o garantía es requisito previo para levantar la medida", "Son por cuenta del Ayuntamiento cuando el vehículo se retira de forma remota", "Se reparten entre el titular y el conductor a partes iguales"]'::jsonb,0,'Art. 41 Ley 22/2006','Los gastos son por cuenta del titular, y su abono o la garantía de su pago es requisito previo para el alzamiento de la medida.',null),
('aux-ayto-mad:8-0ec6b9211e','aux-ayto-mad',8,'La comprobación del supuesto que legitima la retirada de un vehículo y la orden de retirada, según la Ley 22/2006:','["Requieren siempre la presencia física de un agente de la policía municipal", "Pueden efectuarse de forma remota, mediante fotografías, filmación digital u otros medios tecnológicos", "Solo pueden hacerse por un agente de movilidad tras levantar acta"]'::jsonb,1,'Art. 41.2.ª Ley 22/2006','El art. 41.2.ª permite comprobar el supuesto y ordenar la retirada de forma remota, a través de fotografías, filmación digital y otros medios tecnológicos.',null),
('aux-ayto-mad:8-9a89b3f50e','aux-ayto-mad',8,'El Ayuntamiento de Madrid podrá nombrar personal auxiliar de la policía municipal para:','["Instruir los atestados por accidentes de circulación", "Controlar la adecuada utilización de las paradas de estacionamiento en la vía pública y denunciar las conductas contrarias a sus normas", "Ordenar y dirigir el tráfico en las intersecciones"]'::jsonb,1,'Art. 44.1 Ley 22/2006','El personal auxiliar controla la utilización de las paradas de estacionamiento y denuncia las conductas contrarias a sus normas; sus denuncias sirven como elemento probatorio (art. 44.2).',null),
('aux-ayto-mad:8-b6322d2bc1','aux-ayto-mad',8,'Los funcionarios del cuerpo que el Pleno puede crear para ordenar, señalizar y dirigir el tráfico en el casco urbano de Madrid:','["Dependen funcionalmente de la Dirección General de Tráfico", "No se integran en las Fuerzas y Cuerpos de Seguridad y son agentes de la autoridad subordinados a la Policía Local", "Se integran en las Fuerzas y Cuerpos de Seguridad como policía local de movilidad"]'::jsonb,1,'Art. 45 Ley 22/2006','Estos funcionarios no se integran en las Fuerzas y Cuerpos de Seguridad y tienen la consideración de agentes de la autoridad subordinados a los miembros de la Policía Local.',null),
('aux-ayto-mad:8-101464fdce','aux-ayto-mad',8,'En el embargo de bienes por sanciones de tráfico, la Ley 22/2006 permite embargar el vehículo del responsable:','["Solo cuando se hayan embargado sin éxito sus sueldos y salarios", "Inmediatamente después del dinero en efectivo o en cuentas abiertas en entidades de depósito", "Antes que cualquier otro bien, incluido el dinero en efectivo"]'::jsonb,1,'Art. 46 Ley 22/2006','Se exceptúa el orden general de embargo: inmediatamente después del dinero en efectivo o en cuentas, se puede embargar el vehículo del responsable de la infracción.',null),
('aux-ayto-mad:8-148590c4b8','aux-ayto-mad',8,'Mediante ordenanza, el Ayuntamiento de Madrid puede imponer la obligación de exhibir en el vehículo un adhesivo justificativo del pago o la exención del:','["Impuesto sobre Vehículos de Tracción Mecánica", "Impuesto sobre Bienes Inmuebles", "Impuesto sobre Actividades Económicas de los titulares de vehículos comerciales"]'::jsonb,0,'Art. 43.2 Ley 22/2006','El art. 43.2 permite exigir un adhesivo justificativo del pago o exención del Impuesto sobre Vehículos de Tracción Mecánica a los vehículos obligados a pagarlo en Madrid.',null),
('aux-ayto-mad:8-5359fb1453','aux-ayto-mad',8,'Según la Ley de Capitalidad, cuando se desafecten inmuebles del Estado en Madrid destinados a un servicio público, podrán enajenarse de forma preferente al Ayuntamiento:','["Por subasta pública en la que el Ayuntamiento tiene derecho de tanteo", "Mediante convenio, siempre que se destinen a usos dotacionales públicos o a vivienda pública", "De forma gratuita y por ministerio de la ley, sin necesidad de convenio"]'::jsonb,1,'Art. 47 Ley 22/2006','Puede procederse mediante convenio a su enajenación preferente al Ayuntamiento (o a sus entidades de vivienda y, en su caso, a la Comunidad de Madrid) si se destinan a usos dotacionales públicos o a vivienda protegida o pública en alquiler.',null),
('aux-ayto-mad:8-5d42407e63','aux-ayto-mad',8,'El régimen de capitalidad de la Villa de Madrid regulado en el título I de la Ley 22/2006 tiene como objeto, entre otras materias:','["La gestión del patrimonio histórico de la Corona en la ciudad y de sus reales sitios", "La coordinación en la organización y celebración de actos oficiales de carácter estatal", "La financiación de los servicios de transporte metropolitano"]'::jsonb,1,'Art. 4 b) Ley 22/2006','El régimen de capitalidad comprende la seguridad en acontecimientos nacionales o internacionales, la coordinación de actos oficiales estatales, la protección en reuniones y manifestaciones de dimensión estatal, el régimen protocolario y otras materias que afecten a las tres administraciones.',null),
('aux-ayto-mad:8-ecb21d8803','aux-ayto-mad',8,'La Comisión Interadministrativa de Capitalidad está formada por:','["Igual número de miembros del Estado y de la Comunidad de Madrid y un representante del Ayuntamiento", "Mayoría de miembros del Estado, que la preside", "Igual número de miembros de las tres administraciones"]'::jsonb,2,'Art. 5.2 Ley 22/2006','La Comisión está formada por igual número de miembros de las tres administraciones (Estado, Comunidad de Madrid y Ayuntamiento).',null),
('aux-ayto-mad:8-e09c322817','aux-ayto-mad',8,'La presidencia de la Comisión Interadministrativa de Capitalidad corresponde:','["A la Presidencia de la Comunidad de Madrid", "Al Estado", "Al Alcalde de Madrid"]'::jsonb,1,'Art. 6.1 Ley 22/2006','Según el art. 6.1, la presidencia de la Comisión Interadministrativa de Capitalidad corresponde al Estado.',null),
('aux-ayto-mad:8-f7dce37fa1','aux-ayto-mad',8,'El Reglamento de la Comisión Interadministrativa de Capitalidad se aprueba:','["Por mayoría absoluta de sus miembros", "Por unanimidad de sus miembros", "Por real decreto del Consejo de Ministros"]'::jsonb,1,'Art. 6.2 Ley 22/2006','Su composición y funcionamiento se determinan en su Reglamento, que se aprueba por unanimidad de sus miembros.',null),
('aux-ayto-mad:8-9b6e993c4d','aux-ayto-mad',8,'La Comisión Interadministrativa de Capitalidad es, según la Ley 22/2006:','["Un órgano de cooperación para la mejor articulación del régimen de capitalidad", "Un órgano consultivo del Pleno del Ayuntamiento en materia de protocolo", "Un órgano de control de la legalidad de los acuerdos municipales"]'::jsonb,0,'Art. 5.1 Ley 22/2006','Se crea como órgano de cooperación para la mejor articulación del régimen de capitalidad, respetando los ámbitos competenciales de cada administración.',null),
('aux-ayto-mad:8-d05a8fc0bf','aux-ayto-mad',8,'Según el artículo 2 de la Ley 22/2006, para la efectividad de su autonomía la Ley atribuye al Ayuntamiento de Madrid competencias en materia de:','["Infraestructuras, movilidad, seguridad ciudadana y régimen jurídico y procedimiento", "Hacienda autonómica, justicia y empleo", "Educación, sanidad, vivienda y servicios sociales de atención primaria"]'::jsonb,0,'Art. 2.3 Ley 22/2006','El art. 2.3 cita las competencias en infraestructuras, movilidad, seguridad ciudadana y régimen jurídico y procedimiento.',null),
('aux-ayto-mad:8-ad1fa3b361','aux-ayto-mad',8,'En las materias no reguladas en la Ley 22/2006 se aplica a la ciudad de Madrid, en primer lugar:','["Los reglamentos orgánicos aprobados por el Pleno", "La legislación estatal básica en materia de gobierno y administración local y, en su caso, la autonómica de desarrollo", "El Texto articulado de la Ley especial para el Municipio de Madrid de 1963, en lo no derogado"]'::jsonb,1,'Art. 1.2 Ley 22/2006','Se aplica la legislación estatal básica de régimen local y, en su caso, la autonómica de desarrollo, y la restante legislación del Estado y de la Comunidad según la distribución de competencias. El texto de 1963 quedó sin efecto (disposición derogatoria).',null),
('aux-ayto-mad:8-5658bdc485','aux-ayto-mad',8,'La Ley 22/2006 dejó sin efecto los artículos no derogados del Texto articulado de la Ley especial para el Municipio de Madrid aprobado en:','["1963", "1955", "1985"]'::jsonb,0,'Disposición derogatoria única Ley 22/2006','La disposición derogatoria deja sin efecto los artículos del Texto articulado de la Ley especial para el Municipio de Madrid, aprobado por Decreto 1674/1963, de 11 de julio.',null),
('aux-ayto-mad:8-4fd216c7a3','aux-ayto-mad',8,'Según la Ley 22/2006, todas las instalaciones de las redes de servicios públicos de suministros y de interés general que discurran por el término municipal:','["Deben ser subterráneas, salvo urgencia o impracticabilidad técnica o económica", "Pueden ser aéreas si así lo decide la empresa suministradora", "Deben ser subterráneas solo en el distrito Centro y en los conjuntos históricos protegidos"]'::jsonb,0,'Disposición adicional tercera Ley 22/2006','Deben ser subterráneas; solo en caso de urgencia o de impracticabilidad técnica o económica puede autorizarse su instalación en superficie o aérea.',null),
('aux-ayto-mad:8-0794be4a5d','aux-ayto-mad',8,'Las tarjetas de estacionamiento para personas con discapacidad emitidas por el Ayuntamiento conforme al modelo europeo tienen validez:','["En todo el territorio estatal", "En la Comunidad de Madrid y en los municipios con convenio", "Solo en el término municipal de Madrid"]'::jsonb,0,'Disposición adicional quinta Ley 22/2006','Según la disposición adicional quinta, tienen validez en todo el territorio estatal, con independencia del municipio de procedencia del titular.',null),
('aux-ayto-mad:8-a0afabb234','aux-ayto-mad',8,'Según la Ley 22/2006, la legislación sectorial:','["Puede atribuir nuevas competencias al Pleno, pero no a la Junta de Gobierno", "Prevalece sobre esta Ley en la atribución de competencias a los órganos municipales", "No podrá alterar la distribución interna de competencias que hace esta Ley entre el Pleno, el Alcalde y la Junta de Gobierno"]'::jsonb,2,'Disposición adicional segunda Ley 22/2006','La legislación sectorial no puede alterar la distribución interna de competencias entre Pleno, Alcalde y Junta de Gobierno.',null),
('aux-ayto-mad:8-e31e277f22','aux-ayto-mad',8,'La Ley 22/2006, de Capitalidad y de Régimen Especial de Madrid, entró en vigor:','["Al día siguiente de su publicación en el BOE", "A los veinte días de su publicación en el BOE", "A los tres meses de su publicación en el BOE"]'::jsonb,1,'Disposición final segunda Ley 22/2006','Según su disposición final segunda, entró en vigor a los veinte días de su publicación en el «Boletín Oficial del Estado».',null),
('aux-ayto-mad:8-c97ff66a71','aux-ayto-mad',8,'El Ayuntamiento de Madrid regulará los distintos usos de las vías y espacios públicos urbanos con la finalidad de armonizarlos y hacerlos compatibles con:','["La seguridad vial, la movilidad y fluidez del tráfico, la protección del medio ambiente y de los espacios públicos y privados", "Las directrices de tráfico que fije cada año la Dirección General de Tráfico", "Solo la circulación de vehículos de motor, que tiene preferencia sobre los demás usos de la vía"]'::jsonb,0,'Art. 39.1 Ley 22/2006','Se trata de armonizar los usos peatonal, de circulación, de estacionamiento, deportivo y lúdico con la seguridad vial, la movilidad, el medio ambiente y la integridad de los espacios públicos y privados.',null),
('aux-ayto-mad:8-7829d80092','aux-ayto-mad',8,'Las denuncias realizadas por el personal auxiliar de la policía municipal en materia de estacionamiento:','["Carecen de valor probatorio si no las ratifica un agente de la policía municipal", "Tienen presunción de veracidad sin necesidad de ninguna otra prueba", "Se utilizan como elemento probatorio y al expediente se incorpora una imagen del vehículo"]'::jsonb,2,'Art. 44.2 Ley 22/2006','Se utilizan como elemento probatorio para acreditar los hechos, y al expediente se incorpora una imagen del vehículo (fotografía, filmación digital u otros medios).',null),
('aux-ayto-mad:8-5246c972e9','aux-ayto-mad',8,'Los órganos municipales que imponen sanciones de circulación pueden solicitar a otras Administraciones la ejecución de sus órdenes de embargo:','["Previa autorización judicial del juzgado de lo contencioso-administrativo competente", "De acuerdo con el principio de colaboración interadministrativa y los oportunos convenios", "Solo si el deudor reside fuera de la Comunidad de Madrid"]'::jsonb,1,'Art. 42 Ley 22/2006','El art. 42 lo permite de acuerdo con el principio de colaboración interadministrativa y los oportunos convenios.',null),
('aux-ayto-mad:9-38fe2c9443','aux-ayto-mad',9,'Según la Ley 22/2006, el órgano deliberante de representación política del Ayuntamiento de Madrid es:','["El Pleno", "La Junta de Portavoces", "La Junta de Gobierno"]'::jsonb,0,'Art. 7 a) Ley 22/2006','El art. 7 distingue el órgano deliberante de representación política (el Pleno) de los ejecutivos de dirección política y administrativa.',null),
('aux-ayto-mad:9-593e8ef50e','aux-ayto-mad',9,'¿Cuál de los siguientes NO es un órgano ejecutivo de dirección política y administrativa del Ayuntamiento de Madrid según la Ley 22/2006?','["Los Tenientes de Alcalde", "El Pleno", "Los miembros no electos de la Junta de Gobierno"]'::jsonb,1,'Art. 7 Ley 22/2006','Son ejecutivos el Alcalde, la Junta de Gobierno, los Tenientes de Alcalde, los Concejales con responsabilidades de gobierno, los miembros no electos de la Junta de Gobierno y los que fije el Reglamento orgánico. El Pleno es el órgano deliberante.',null),
('aux-ayto-mad:9-6bd80f3152','aux-ayto-mad',9,'La responsabilidad penal del Alcalde, los Tenientes de Alcalde y los Concejales del Ayuntamiento de Madrid será exigible conforme a lo que disponga:','["La Ley de Enjuiciamiento Criminal en exclusiva", "La Ley Orgánica del Poder Judicial", "El Reglamento Orgánico del Pleno"]'::jsonb,1,'Art. 8 Ley 22/2006','Según el art. 8 (fuero), su responsabilidad penal y la civil por el ejercicio de sus cargos es exigible conforme a la Ley Orgánica del Poder Judicial.',null),
('aux-ayto-mad:9-067f39357a','aux-ayto-mad',9,'Según la Ley 22/2006, el Pleno del Ayuntamiento de Madrid está formado por:','["El Alcalde, los Concejales y los Concejales Presidentes de Distrito con voz pero sin voto", "Los Concejales y los miembros no electos de la Junta de Gobierno", "El Alcalde y los Concejales"]'::jsonb,2,'Art. 9.1 Ley 22/2006','El Pleno está formado por el Alcalde y los Concejales, sin perjuicio de que los miembros no electos de la Junta de Gobierno asistan e intervengan en sus deliberaciones.',null),
('aux-ayto-mad:9-8b95fface0','aux-ayto-mad',9,'Las sesiones del Pleno del Ayuntamiento de Madrid son públicas, pero podrán ser secretos el debate y votación de los asuntos que puedan afectar al derecho del artículo 18.1 de la Constitución cuando así se acuerde por:','["Mayoría absoluta", "Unanimidad", "Mayoría simple"]'::jsonb,0,'Art. 9.2 Ley 22/2006','Pueden ser secretos el debate y votación de asuntos que afecten al honor, la intimidad personal y familiar y la propia imagen (art. 18.1 CE) cuando así se acuerde por mayoría absoluta.',null),
('aux-ayto-mad:9-9325a675b7','aux-ayto-mad',9,'Las Comisiones del Pleno del Ayuntamiento de Madrid están formadas por:','["Un Concejal por cada grupo político, con voto ponderado según su representación", "Los Concejales que designe el Alcalde entre los miembros de la Junta de Gobierno", "Los Concejales que designen los grupos políticos en proporción a su representación en el Pleno"]'::jsonb,2,'Art. 9.2 Ley 22/2006','El Pleno puede funcionar en Comisiones formadas por los Concejales que designen los grupos políticos en proporción a su representación en el Pleno.',null),
('aux-ayto-mad:9-e9f654f257','aux-ayto-mad',9,'Según la Ley 22/2006, quien convoca y preside las sesiones del Pleno es:','["El Alcalde, salvo que se haya elegido un Presidente del Pleno", "El Presidente del Pleno, que es siempre un Concejal distinto del Alcalde", "El Secretario General del Pleno"]'::jsonb,0,'Art. 10.1 Ley 22/2006','El Alcalde convoca y preside las sesiones del Pleno, aunque puede promover que el Pleno elija entre los Concejales un Presidente y un Vicepresidente.',null),
('aux-ayto-mad:9-7f23b00d36','aux-ayto-mad',9,'El Presidente del Pleno del Ayuntamiento de Madrid, cuando se designe, es elegido:','["Por el Pleno entre los Concejales, a iniciativa del Alcalde y al inicio del mandato", "Por el Alcalde entre los miembros de la Junta de Gobierno", "Por la Junta de Portavoces entre los Concejales de más edad"]'::jsonb,0,'Art. 10.2 Ley 22/2006','A iniciativa del Alcalde, el Pleno puede elegir entre los Concejales a su Presidente y Vicepresidente al inicio del mandato.',null),
('aux-ayto-mad:9-c9d27819b4','aux-ayto-mad',9,'En la elección del Presidente del Pleno, si ningún Concejal obtiene la mayoría absoluta en primera votación:','["Resulta elegido el Concejal de mayor edad entre los que hayan obtenido votos", "Se repite la votación hasta que alguno alcance la mayoría absoluta", "Se repite entre los dos más votados y resulta elegido el que obtenga más votos"]'::jsonb,2,'Art. 10.2 Ley 22/2006','Se repite entre los dos Concejales más votados y resulta elegido el que obtenga más votos. En caso de empate, el candidato de la lista con más votos en las elecciones municipales.',null),
('aux-ayto-mad:9-a6614d12ef','aux-ayto-mad',9,'En caso de empate en la segunda votación para elegir al Presidente del Pleno resulta elegido:','["El candidato de la lista que hubiese obtenido mayor número de votos en las elecciones municipales", "El Concejal de mayor edad de los dos candidatos empatados", "El candidato que proponga el Alcalde"]'::jsonb,0,'Art. 10.2 Ley 22/2006','El art. 10.2 resuelve el empate a favor del candidato de la lista que obtuvo más votos en las elecciones municipales.',null),
('aux-ayto-mad:9-8d795787d8','aux-ayto-mad',9,'Los cargos de Presidente y Vicepresidente del Pleno del Ayuntamiento de Madrid se mantienen:','["Hasta la finalización del mandato", "Mientras cuenten con la confianza del Alcalde", "Durante dos años, renovables"]'::jsonb,0,'Art. 10.2 Ley 22/2006','Según el art. 10.2, dichos cargos se mantendrán hasta la finalización del mandato.',null),
('aux-ayto-mad:9-4a87e89ce4','aux-ayto-mad',9,'¿Cuál de las siguientes funciones corresponde al Presidente del Pleno según la Ley 22/2006?','["Interpretar las normas de funcionamiento del Pleno y dirigir y mantener el orden de los debates", "Dictar bandos", "Nombrar y cesar a los miembros de la Junta de Gobierno y a los Tenientes de Alcalde"]'::jsonb,0,'Art. 10.3 Ley 22/2006','El Presidente del Pleno asegura la buena marcha de sus trabajos, interpreta sus normas de funcionamiento, convoca y preside las sesiones y dirige y mantiene el orden de los debates.',null),
('aux-ayto-mad:9-dcff1f0c72','aux-ayto-mad',9,'Según la Ley 22/2006, la votación de la moción de censura al Alcalde en el Pleno será:','["Secreta, mediante papeleta depositada en urna", "Pública, a mano alzada", "Pública y mediante llamamiento nominal en todo caso"]'::jsonb,2,'Art. 11.1 b) Ley 22/2006','La votación de la moción de censura y de la cuestión de confianza es pública y se realiza mediante llamamiento nominal en todo caso, y se rige por la legislación electoral general.',null),
('aux-ayto-mad:9-954d4b2d69','aux-ayto-mad',9,'¿Cuál de las siguientes atribuciones corresponde al Pleno del Ayuntamiento de Madrid?','["La aprobación del proyecto de presupuesto", "La concesión de licencias urbanísticas y de actividad", "La determinación de los recursos propios de carácter tributario"]'::jsonb,2,'Art. 11.1 g) Ley 22/2006','La determinación de los recursos propios tributarios es atribución del Pleno. La aprobación del proyecto de presupuesto y la concesión de licencias corresponden a la Junta de Gobierno (art. 17).',null),
('aux-ayto-mad:9-60387637f6','aux-ayto-mad',9,'Según la Ley 22/2006, tienen en todo caso naturaleza orgánica los reglamentos que regulen:','["Los precios públicos de los servicios municipales", "El tráfico, la circulación de vehículos y el estacionamiento regulado", "La división de la ciudad en distritos y la determinación y regulación de sus órganos"]'::jsonb,2,'Art. 11.1 c) Ley 22/2006','Tienen naturaleza orgánica, entre otras, la regulación del Pleno, la de los órganos de participación ciudadana, la división en distritos y sus órganos, la organización política y administrativa y la del Tribunal Económico-Administrativo Municipal.',null),
('aux-ayto-mad:9-5e504352f2','aux-ayto-mad',9,'¿Cuál de las siguientes materias NO figura entre las que tienen en todo caso naturaleza orgánica según el artículo 11 de la Ley 22/2006?','["La regulación de los tributos municipales", "La regulación de los órganos y procedimientos de participación ciudadana", "La regulación del Tribunal Económico-Administrativo Municipal de Madrid"]'::jsonb,0,'Art. 11.1 c) Ley 22/2006','Los tributos no están en la lista de materias orgánicas. Sí lo están el Tribunal Económico-Administrativo Municipal y la participación ciudadana.',null),
('aux-ayto-mad:9-6e1760234b','aux-ayto-mad',9,'La aprobación de la cuenta general del ejercicio corresponde, en el Ayuntamiento de Madrid:','["Al Pleno", "A la Junta de Gobierno", "Al Alcalde"]'::jsonb,0,'Art. 11.1 h) Ley 22/2006','El Pleno aprueba los presupuestos, autoriza gastos en las materias de su competencia y aprueba la cuenta general del ejercicio.',null),
('aux-ayto-mad:9-5e960f6585','aux-ayto-mad',9,'La aprobación de los estatutos de las fundaciones municipales corresponde, en el Ayuntamiento de Madrid:','["Al Pleno", "Al Alcalde mediante decreto", "A la Junta de Gobierno"]'::jsonb,0,'Art. 11.1 l) Ley 22/2006','Corresponde al Pleno aprobar los estatutos de organismos autónomos, entidades públicas empresariales y sociedades mercantiles, y también los de las fundaciones. La Junta de Gobierno aprueba solo los proyectos (art. 17.1 a).',null),
('aux-ayto-mad:9-eee710feee','aux-ayto-mad',9,'Establecer el régimen retributivo de los miembros del Pleno, del Alcalde y de los miembros de la Junta de Gobierno corresponde:','["Al Alcalde, dando cuenta al Pleno", "Al Pleno", "A la Junta de Gobierno"]'::jsonb,1,'Art. 11.1 ñ) Ley 22/2006','Es atribución del Pleno, que además no puede delegarla (art. 11.3).',null),
('aux-ayto-mad:9-ab54a1c835','aux-ayto-mad',9,'La creación de escalas, subescalas y clases de funcionarios en el Ayuntamiento de Madrid corresponde:','["Al Pleno", "A la Junta de Gobierno", "Al Alcalde"]'::jsonb,0,'Art. 11.1 p) Ley 22/2006','Corresponde al Pleno crear escalas, subescalas y clases de funcionarios y atribuirles la condición de agente de la autoridad.',null),
('aux-ayto-mad:9-dc48e90028','aux-ayto-mad',9,'Según el artículo 11.2 de la Ley 22/2006, requiere mayoría absoluta del número legal de miembros del Pleno:','["La aprobación de las ordenanzas fiscales", "La aprobación y modificación de los reglamentos de naturaleza orgánica", "La aprobación de los presupuestos generales del Ayuntamiento"]'::jsonb,1,'Art. 11.2 Ley 22/2006','Requieren mayoría absoluta los acuerdos de los párrafos c) (reglamentos orgánicos), e) (término municipal y símbolos), f) (organizaciones supramunicipales) y k) (transferencias y delegaciones), y los de planeamiento general. Los demás, mayoría simple.',null),
('aux-ayto-mad:9-6bdf5ec655','aux-ayto-mad',9,'Salvo los supuestos del artículo 11.2 de la Ley 22/2006, los acuerdos del Pleno del Ayuntamiento de Madrid se adoptan por:','["Mayoría simple de votos", "Mayoría de dos tercios", "Mayoría absoluta del número legal de miembros"]'::jsonb,0,'Art. 11.2 Ley 22/2006','Los acuerdos no incluidos en el art. 11.2 se adoptan por mayoría simple de votos.',null),
('aux-ayto-mad:9-1cc16de139','aux-ayto-mad',9,'La adopción o modificación de la bandera, enseña o escudo de la ciudad de Madrid requiere:','["Mayoría simple del Pleno", "Mayoría absoluta del número legal de miembros del Pleno", "Mayoría de dos tercios del Pleno"]'::jsonb,1,'Art. 11.2 Ley 22/2006','El párrafo e) del art. 11.1 (término municipal, bandera, enseña o escudo) es de los que exige mayoría absoluta según el art. 11.2.',null),
('aux-ayto-mad:9-e4805560fb','aux-ayto-mad',9,'Las delegaciones del Pleno del Ayuntamiento de Madrid solo pueden realizarse:','["En sus Comisiones", "En la Junta de Gobierno", "En el Alcalde y en la Junta de Gobierno"]'::jsonb,0,'Art. 11.3 Ley 22/2006','Según el art. 11.3, las delegaciones del Pleno sólo podrán realizarse en sus Comisiones.',null),
('aux-ayto-mad:9-948c6e556a','aux-ayto-mad',9,'¿Cuál de las siguientes atribuciones del Pleno SÍ puede delegarse en sus Comisiones?','["La aprobación de los reglamentos orgánicos y de sus modificaciones", "La aprobación de los presupuestos", "El ejercicio de acciones judiciales y administrativas en las materias de su competencia"]'::jsonb,2,'Art. 11.3 Ley 22/2006','No son delegables los párrafos a), b), c), e), f), g), h), j), k), m), ñ) y p). El ejercicio de acciones judiciales (párrafo n) no está en esa lista, por lo que puede delegarse en las Comisiones.',null),
('aux-ayto-mad:9-6c54aad628','aux-ayto-mad',9,'Según la Ley 22/2006, el dictamen de las normas municipales con carácter previo a su aprobación por el Pleno corresponde a:','["La Asesoría Jurídica", "La Junta de Gobierno", "Las Comisiones del Pleno"]'::jsonb,2,'Art. 12 b) Ley 22/2006','El art. 12 atribuye a las Comisiones el estudio e informe de los asuntos del Pleno, el dictamen de las normas municipales, el seguimiento de la gestión del Alcalde y las funciones que el Pleno les delegue.',null),
('aux-ayto-mad:9-2891ed359a','aux-ayto-mad',9,'La redacción y custodia de las actas del Pleno corresponde a:','["El Concejal Secretario de la Junta de Gobierno", "El Presidente del Pleno", "El Secretario General del Pleno"]'::jsonb,2,'Art. 13.1 a) Ley 22/2006','Corresponde al Secretario General del Pleno la redacción y custodia de las actas y su supervisión y autorización, con el visto bueno del Presidente del Pleno.',null),
('aux-ayto-mad:9-01906a86fd','aux-ayto-mad',9,'El Secretario General del Pleno prestará asesoramiento legal al Pleno y a las Comisiones cuando lo solicite el Alcalde, el Presidente o:','["La cuarta parte, al menos, de los Concejales", "La tercera parte, al menos, de los Concejales", "Cualquier grupo político"]'::jsonb,0,'Art. 13.1 e) Ley 22/2006','Según el art. 13.1 e), el asesoramiento legal procede cuando lo solicite el Alcalde, el Presidente, en su caso, o la cuarta parte, al menos, de los Concejales.',null),
('aux-ayto-mad:9-2a8be6398e','aux-ayto-mad',9,'Las funciones del Secretario General del Pleno quedan reservadas a:','["Funcionarios de Administración local con habilitación de carácter nacional", "Letrados del Ayuntamiento de Madrid", "Funcionarios del subgrupo A1 de cualquier Administración pública"]'::jsonb,0,'Art. 13.1 Ley 22/2006','Están reservadas a funcionarios de Administración local con habilitación de carácter nacional, y su nombramiento corresponde al Presidente del Pleno.',null),
('aux-ayto-mad:9-a4072acf3c','aux-ayto-mad',9,'El nombramiento del Secretario General del Pleno del Ayuntamiento de Madrid corresponde:','["Al Presidente del Pleno", "Al Pleno por mayoría absoluta", "A la Junta de Gobierno"]'::jsonb,0,'Art. 13.1 Ley 22/2006','Su nombramiento corresponde al Presidente del Pleno, por los sistemas previstos en las disposiciones legales aplicables.',null),
('aux-ayto-mad:9-1ab7dc8575','aux-ayto-mad',9,'La Secretaría de las Comisiones del Pleno corresponde al Secretario General del Pleno, quien:','["Podrá delegarla en un Concejal", "No podrá delegarla en ningún caso", "Podrá delegarla en un funcionario"]'::jsonb,2,'Art. 13.2 Ley 22/2006','El art. 13.2 permite que el Secretario General del Pleno delegue la Secretaría de las Comisiones en un funcionario.',null),
('aux-ayto-mad:9-6c63d054de','aux-ayto-mad',9,'Según la Ley 22/2006, la llevanza y custodia del registro de intereses de los miembros del Pleno corresponde:','["Al Secretario General del Pleno", "Al Interventor General", "Al Secretario de la Junta de Gobierno"]'::jsonb,0,'Art. 13.1 f) Ley 22/2006','El art. 13.1 f) atribuye al Secretario General del Pleno la llevanza y custodia del registro de intereses de los miembros del Pleno y de los miembros no electos de la Junta de Gobierno.',null),
('aux-ayto-mad:9-a6f2f661f4','aux-ayto-mad',9,'Según la Ley 22/2006, el Alcalde responde ante el Pleno:','["Por los actos de los órganos directivos que no haya delegado", "Por su gestión política", "Solo por la ejecución del presupuesto"]'::jsonb,1,'Art. 14.1 Ley 22/2006','El Alcalde impulsa la política municipal, dirige la acción de los restantes órganos ejecutivos, ejerce la superior dirección de la Administración y responde ante el Pleno por su gestión política.',null),
('aux-ayto-mad:9-f61da38dd0','aux-ayto-mad',9,'Decidir los empates con voto de calidad en todos los órganos municipales colegiados en los que participe corresponde a:','["El Alcalde", "El Teniente de Alcalde de mayor rango", "El Presidente del Pleno"]'::jsonb,0,'Art. 14.3 c) Ley 22/2006','Es atribución del Alcalde (art. 14.3 c) y, además, indelegable (art. 14.4).',null),
('aux-ayto-mad:9-c663865df2','aux-ayto-mad',9,'Según la Ley 22/2006, el nombramiento del personal funcionario, laboral y eventual al servicio del Ayuntamiento de Madrid corresponde:','["Al Pleno", "Al Alcalde", "A la Junta de Gobierno"]'::jsonb,1,'Art. 14.3 ñ) Ley 22/2006','El art. 14.3 ñ) atribuye al Alcalde el nombramiento del personal funcionario, laboral y eventual. La separación del servicio de los funcionarios corresponde a la Junta de Gobierno (art. 17.1 m).',null),
('aux-ayto-mad:9-53e12022d1','aux-ayto-mad',9,'La ordenación de pagos en el Ayuntamiento de Madrid corresponde, según la Ley 22/2006:','["A la Junta de Gobierno", "Al Alcalde", "A la Tesorería"]'::jsonb,1,'Art. 14.3 n) Ley 22/2006','La ordenación de pagos es una atribución del Alcalde (art. 14.3 n), que puede delegar.',null),
('aux-ayto-mad:9-72405995ca','aux-ayto-mad',9,'La firma de convenios corresponde, según la Ley 22/2006:','["Al Pleno", "Al Alcalde", "A la Asesoría Jurídica"]'::jsonb,1,'Art. 14.3 k) Ley 22/2006','El art. 14.3 k) atribuye al Alcalde la firma de convenios.',null),
('aux-ayto-mad:9-27fe12855d','aux-ayto-mad',9,'Cuando el Alcalde adopte medidas en casos de extraordinaria y urgente necesidad deberá:','["Someterlas a ratificación de la Junta de Gobierno en diez días", "Comunicarlas a la Delegación del Gobierno", "Dar cuenta inmediata al Pleno"]'::jsonb,2,'Art. 14.3 f) Ley 22/2006','El Alcalde adopta las medidas necesarias en casos de extraordinaria y urgente necesidad, dando cuenta inmediata al Pleno. Esta atribución es indelegable.',null),
('aux-ayto-mad:9-48816f2d6c','aux-ayto-mad',9,'En caso de urgencia, el Alcalde puede ejercer acciones judiciales en materias de competencia del Pleno:','["Solo si lo autoriza la Asesoría Jurídica", "Dando cuenta al Pleno en la primera sesión que celebre para su ratificación", "Previa autorización de la Junta de Portavoces del Pleno"]'::jsonb,1,'Art. 14.3 i) Ley 22/2006','El art. 14.3 i) lo permite en caso de urgencia, dando cuenta al Pleno en la primera sesión que celebre para su ratificación.',null),
('aux-ayto-mad:9-aeeb3f2caf','aux-ayto-mad',9,'¿Cuál de las siguientes atribuciones del Alcalde es indelegable según la Ley 22/2006?','["Dictar bandos", "La firma de convenios", "La ordenación de pagos"]'::jsonb,0,'Art. 14.4 Ley 22/2006','No son delegables las de los párrafos b), c), d), e) en cuanto a los bandos y f). La firma de convenios y la ordenación de pagos sí pueden delegarse.',null),
('aux-ayto-mad:9-e42f363a40','aux-ayto-mad',9,'Las atribuciones del Alcalde de determinar el programa de acción política municipal y de acordar el número y denominación de las áreas solo son delegables en:','["La Junta de Gobierno", "Los Tenientes de Alcalde", "Los Concejales Presidentes de Distrito"]'::jsonb,0,'Art. 14.4 Ley 22/2006','Según el art. 14.4, las atribuciones de los párrafos a) y h) sólo serán delegables en la Junta de Gobierno.',null),
('aux-ayto-mad:9-fb52e0d7c5','aux-ayto-mad',9,'El Alcalde puede delegar o desconcentrar sus competencias delegables mediante:','["Acuerdo del Pleno", "Decreto", "Bando"]'::jsonb,1,'Art. 14.4 Ley 22/2006','El art. 14.4 dice que el Alcalde podrá delegar o desconcentrar mediante decreto.',null),
('aux-ayto-mad:9-5741ebb953','aux-ayto-mad',9,'Los Tenientes de Alcalde del Ayuntamiento de Madrid se nombran de entre:','["Todos los Concejales del Pleno, sean o no de la Junta de Gobierno", "Los miembros de la Junta de Gobierno, sean o no Concejales", "Los miembros de la Junta de Gobierno que ostenten la condición de Concejal"]'::jsonb,2,'Art. 15 Ley 22/2006','El Alcalde puede nombrarlos de entre los miembros de la Junta de Gobierno que sean Concejales. Le sustituyen por orden de nombramiento en caso de vacante, ausencia o enfermedad.',null),
('aux-ayto-mad:9-48c26b75b0','aux-ayto-mad',9,'Los Tenientes de Alcalde sustituyen al Alcalde en los casos de vacante, ausencia o enfermedad:','["Por orden de antigüedad como Concejales", "Según decida en cada caso la Junta de Gobierno", "Por el orden de su nombramiento"]'::jsonb,2,'Art. 15 Ley 22/2006','Según el art. 15, le sustituyen por el orden de su nombramiento.',null),
('aux-ayto-mad:9-6319927559','aux-ayto-mad',9,'El número de miembros de la Junta de Gobierno del Ayuntamiento de Madrid, además del Alcalde, no podrá exceder de:','["Un tercio del número legal de miembros del Pleno", "Una cuarta parte del número legal de miembros del Pleno", "La mitad del número legal de miembros del Pleno"]'::jsonb,0,'Art. 16.2 Ley 22/2006','El Alcalde nombra y separa libremente a sus miembros, cuyo número no puede exceder de un tercio del número legal de miembros del Pleno, además del Alcalde.',null),
('aux-ayto-mad:9-375f1675f4','aux-ayto-mad',9,'Según la Ley 22/2006, la Junta de Gobierno del Ayuntamiento de Madrid responde políticamente ante el Pleno:','["De forma solidaria, que excluye la responsabilidad individual", "De forma solidaria, sin perjuicio de la responsabilidad directa de cada uno de sus miembros", "Solo de forma individual, por la gestión de cada miembro"]'::jsonb,1,'Art. 16.3 Ley 22/2006','La Junta de Gobierno responde políticamente ante el Pleno de forma solidaria, sin perjuicio de la responsabilidad directa de cada miembro por su gestión.',null),
('aux-ayto-mad:9-66ac17265a','aux-ayto-mad',9,'La Secretaría de la Junta de Gobierno del Ayuntamiento de Madrid corresponde a:','["El Secretario General del Pleno", "Uno de sus miembros, designado por el Alcalde", "Un funcionario con habilitación de carácter nacional"]'::jsonb,1,'Art. 16.4 Ley 22/2006','Corresponde a uno de sus miembros, designado por el Alcalde, que redacta las actas y certifica los acuerdos.',null),
('aux-ayto-mad:9-e9c5c70f54','aux-ayto-mad',9,'Las sesiones de la Junta de Gobierno del Ayuntamiento de Madrid son:','["Secretas, aunque podrán ser públicas por acuerdo de la propia Junta", "Públicas, salvo que el Alcalde acuerde lo contrario por razón del asunto", "Siempre secretas, sin excepción"]'::jsonb,0,'Art. 16.5 Ley 22/2006','Son secretas, pero pueden ser públicas por acuerdo de la propia Junta cuando la naturaleza de los asuntos lo haga procedente.',null),
('aux-ayto-mad:9-a1041cdd88','aux-ayto-mad',9,'A las sesiones de la Junta de Gobierno podrán asistir los concejales que no pertenezcan a ella:','["Nunca, porque las sesiones son secretas", "Siempre, con voz pero sin voto, si lo comunican con antelación", "Cuando sean convocados expresamente por el Alcalde"]'::jsonb,2,'Art. 16.5 Ley 22/2006','Pueden asistir los concejales no pertenecientes a la Junta y los titulares de órganos directivos cuando sean convocados expresamente por el Alcalde.',null),
('aux-ayto-mad:9-ec1eab4074','aux-ayto-mad',9,'¿A quién corresponde la aprobación del proyecto de presupuesto del Ayuntamiento de Madrid?','["Al Pleno", "A la Junta de Gobierno", "Al Alcalde"]'::jsonb,1,'Art. 17.1 c) Ley 22/2006','La Junta de Gobierno aprueba el proyecto de presupuesto (art. 17.1 c), indelegable; el Pleno aprueba el presupuesto (art. 11.1 h).',null),
('aux-ayto-mad:9-9e6af2f682','aux-ayto-mad',9,'El ejercicio de la potestad sancionadora y la concesión de licencias corresponde, en el Ayuntamiento de Madrid:','["Al Pleno", "A la Junta de Gobierno", "Al Alcalde"]'::jsonb,1,'Art. 17.1 k) Ley 22/2006','El art. 17.1 k) atribuye a la Junta de Gobierno el ejercicio de la potestad sancionadora y la concesión de licencias.',null),
('aux-ayto-mad:9-6c99890a2f','aux-ayto-mad',9,'Aprobar la relación de puestos de trabajo y la oferta de empleo público del Ayuntamiento de Madrid corresponde:','["Al Alcalde", "Al Pleno", "A la Junta de Gobierno"]'::jsonb,2,'Art. 17.1 m) Ley 22/2006','El art. 17.1 m) atribuye a la Junta de Gobierno la RPT, las retribuciones, la oferta de empleo público, las bases de las convocatorias y la separación del servicio de los funcionarios, entre otras.',null),
('aux-ayto-mad:9-4f321a12bc','aux-ayto-mad',9,'La aprobación de las modificaciones presupuestarias en el Ayuntamiento de Madrid corresponde a la Junta de Gobierno, salvo:','["Las que superen el 10 % del presupuesto inicial, que corresponden al Pleno por mayoría absoluta", "Las transferencias de crédito entre áreas de gobierno, que corresponden al Alcalde", "La concesión de un crédito extraordinario o un suplemento de crédito, que corresponde al Pleno"]'::jsonb,2,'Art. 17.1 g) Ley 22/2006','La Junta de Gobierno aprueba todas las modificaciones presupuestarias, salvo el crédito extraordinario o el suplemento de crédito, que corresponden en todo caso al Pleno.',null),
('aux-ayto-mad:9-3fac849e7d','aux-ayto-mad',9,'La designación de los miembros de las mesas de contratación y sus presidentes corresponde, en el Ayuntamiento de Madrid:','["A la Junta de Gobierno", "Al Alcalde", "Al Pleno"]'::jsonb,0,'Art. 17.1 e) Ley 22/2006','La Junta de Gobierno tiene las competencias de gestión en materia de contratos, concesiones y patrimonio, incluida la designación de los miembros de las mesas de contratación.',null),
('aux-ayto-mad:9-25ee8f0a64','aux-ayto-mad',9,'La Junta de Gobierno aprueba los proyectos de ordenanzas y reglamentos, incluidos los orgánicos, con excepción de:','["Las ordenanzas fiscales y los precios públicos", "Los reglamentos de los distritos", "Las normas reguladoras del Pleno y sus Comisiones"]'::jsonb,2,'Art. 17.1 a) Ley 22/2006','Según el art. 17.1 a), la excepción son las normas reguladoras del Pleno y sus Comisiones.',null),
('aux-ayto-mad:9-15f616c8ad','aux-ayto-mad',9,'¿Cuál de las siguientes atribuciones de la Junta de Gobierno es indelegable según la Ley 22/2006?','["La concesión de licencias", "La aprobación del proyecto de presupuesto", "La creación, modificación o supresión de ficheros de datos personales"]'::jsonb,1,'Art. 17.2 Ley 22/2006','No son delegables las de los párrafos a), b), c), d), h) e i): proyectos normativos, planes y directrices, proyecto de presupuesto, planeamiento, organización y estructura, y acciones judiciales.',null),
('aux-ayto-mad:9-d8a3c2e12b','aux-ayto-mad',9,'Para ser titular o miembro de un órgano ejecutivo de dirección política y administrativa del Ayuntamiento de Madrid se requiere en todo caso:','["Tener la condición de funcionario de carrera", "Ser Concejal electo en las últimas elecciones municipales", "Ser mayor de edad, disfrutar del derecho de sufragio activo y pasivo en las elecciones municipales y no estar inhabilitado por sentencia firme"]'::jsonb,2,'Art. 18.1 Ley 22/2006','El art. 18.1 exige ser mayor de edad, disfrutar de los derechos de sufragio activo y pasivo en las elecciones municipales y no estar inhabilitado por sentencia judicial firme.',null),
('aux-ayto-mad:9-29306748e1','aux-ayto-mad',9,'El Alcalde puede nombrar miembros de la Junta de Gobierno que no sean concejales. Sus derechos económicos y prestaciones sociales serán los que establezca:','["La Junta de Gobierno", "El Alcalde en el decreto de nombramiento", "El Pleno"]'::jsonb,2,'Art. 16.2 Ley 22/2006','Según el art. 16.2, sus derechos económicos y prestaciones sociales serán los que establezca el Pleno.',null),
('aux-ayto-mad:9-86ac71e031','aux-ayto-mad',9,'La revisión de oficio de los propios actos y disposiciones de carácter general y la declaración de lesividad de sus actos corresponde, sin posibilidad de delegación:','["Al Pleno", "A la Asesoría Jurídica", "A la Junta de Gobierno"]'::jsonb,0,'Art. 11.1 m) y 11.3 Ley 22/2006','El Pleno revisa de oficio sus propios actos y disposiciones generales y declara la lesividad de sus actos (párrafo m), atribución que no puede delegar. El Alcalde y la Junta de Gobierno hacen lo mismo con sus propios actos.',null),
('aux-ayto-mad:10-5018604bdf','aux-ayto-mad',10,'Según la Ley 22/2006, la Administración del Ayuntamiento de Madrid se organiza y actúa de acuerdo con los principios de:','["Legalidad, autonomía, solidaridad, subsidiariedad y lealtad institucional", "Jerarquía, eficacia, descentralización funcional, desconcentración, coordinación y servicio al ciudadano", "Jerarquía, competencia, unidad de gestión, publicidad, transparencia y participación ciudadana"]'::jsonb,1,'Art. 19.1 Ley 22/2006','El art. 19.1 enumera los principios de jerarquía, eficacia, descentralización funcional, desconcentración, coordinación y servicio al ciudadano, con sometimiento pleno a la Ley y al Derecho.',null),
('aux-ayto-mad:10-376d50a27c','aux-ayto-mad',10,'En sus relaciones con los ciudadanos, la Administración del Ayuntamiento de Madrid actúa de conformidad con los principios de:','["Transparencia y participación", "Jerarquía y desconcentración", "Información, colaboración y coordinación"]'::jsonb,0,'Art. 19.3 Ley 22/2006','En sus relaciones con otras administraciones se rige por la información, colaboración, coordinación y respeto competencial; con los ciudadanos, por la transparencia y la participación.',null),
('aux-ayto-mad:10-de628a381e','aux-ayto-mad',10,'La Administración del Ayuntamiento de Madrid sirve con objetividad a los intereses generales de la ciudad:','["Bajo la superior dirección del Alcalde", "Bajo la superior dirección de la Junta de Gobierno", "Bajo la superior dirección del Pleno"]'::jsonb,0,'Art. 19.2 Ley 22/2006','Según el art. 19.2, actúa bajo la superior dirección del Alcalde.',null),
('aux-ayto-mad:10-7cebee58f0','aux-ayto-mad',10,'El órgano directivo al que corresponde el control interno de la gestión económica y financiera del sector público municipal y la función contable es:','["La Intervención General", "La Tesorería", "El Tribunal Económico-Administrativo Municipal"]'::jsonb,0,'Art. 23.1 Ley 22/2006','La Intervención General ejerce el control interno y la función contable con plena autonomía respecto de las autoridades cuya gestión controle.',null),
('aux-ayto-mad:10-dee22ad1ac','aux-ayto-mad',10,'La Intervención General del Ayuntamiento de Madrid ejerce su función:','["Con plena autonomía respecto de las autoridades y entidades cuya gestión controle", "Bajo la dependencia jerárquica del Alcalde y de la Junta de Gobierno", "Bajo la dependencia del Pleno, al que rinde cuentas cada trimestre"]'::jsonb,0,'Art. 23.1 Ley 22/2006','El art. 23.1 dice que la función se ejercerá con plena autonomía respecto de las autoridades y demás entidades cuya gestión controle.',null),
('aux-ayto-mad:10-df9ab65701','aux-ayto-mad',10,'El nombramiento del titular de la Intervención General del Ayuntamiento de Madrid corresponde a:','["La Junta de Gobierno", "El Alcalde", "El Pleno"]'::jsonb,0,'Art. 23.2 Ley 22/2006','Debe ser un funcionario de Administración local con habilitación de carácter nacional, nombrado por la Junta de Gobierno previa convocatoria pública.',null),
('aux-ayto-mad:10-1435d073b4','aux-ayto-mad',10,'El titular de la Tesorería del Ayuntamiento de Madrid deberá ser:','["Un funcionario del Cuerpo Superior de Inspectores de Hacienda del Estado", "Un funcionario de Administración local con habilitación de carácter nacional", "Cualquier funcionario del Ayuntamiento del subgrupo A1"]'::jsonb,1,'Art. 24.2 Ley 22/2006','Igual que el Interventor General, el Tesorero debe ser funcionario con habilitación de carácter nacional, nombrado por la Junta de Gobierno previa convocatoria pública.',null),
('aux-ayto-mad:10-2f0e8f7942','aux-ayto-mad',10,'La gestión de los recursos y disponibilidades financieras del Ayuntamiento de Madrid corresponde a:','["La Agencia Tributaria Madrid", "La Intervención General", "La Tesorería"]'::jsonb,2,'Art. 24.1 Ley 22/2006','La Tesorería es el órgano directivo que gestiona los recursos y disponibilidades financieras en los términos del Texto Refundido de la Ley Reguladora de las Haciendas Locales.',null),
('aux-ayto-mad:10-fc46022f1f','aux-ayto-mad',10,'La provisión de los puestos de Interventor General y de Tesorero del Ayuntamiento de Madrid requiere en todo caso:','["La aprobación de la Comunidad de Madrid", "El informe favorable del Pleno", "Una previa convocatoria pública"]'::jsonb,2,'Arts. 23.2 y 24.2 Ley 22/2006','La provisión se efectúa por los sistemas del art. 99 de la Ley 7/1985 y requiere, en todo caso, una previa convocatoria pública.',null),
('aux-ayto-mad:10-e779136066','aux-ayto-mad',10,'Conoce y resuelve las reclamaciones sobre la aplicación de los tributos y la imposición de sanciones tributarias del Ayuntamiento de Madrid:','["El Tribunal Económico-Administrativo Municipal de Madrid", "La Agencia Tributaria Madrid", "El Tribunal Económico-Administrativo Regional de Madrid"]'::jsonb,0,'Art. 25.1 a) Ley 22/2006','Corresponde al Tribunal Económico-Administrativo Municipal de Madrid.',null),
('aux-ayto-mad:10-89d5bb8412','aux-ayto-mad',10,'Contra la resolución del Tribunal Económico-Administrativo Municipal de Madrid solo cabe:','["Reclamación ante el Tribunal Económico-Administrativo Central", "Recurso de alzada ante el Pleno", "Recurso contencioso-administrativo"]'::jsonb,2,'Art. 25.2 Ley 22/2006','Su resolución pone fin a la vía administrativa y contra ella solo cabe recurso contencioso-administrativo.',null),
('aux-ayto-mad:10-89995e8cf9','aux-ayto-mad',10,'Antes de la reclamación ante el Tribunal Económico-Administrativo Municipal, el interesado puede presentar:','["Con carácter obligatorio, el recurso de reposición del artículo 14.2 del TRLRHL", "Con carácter potestativo, el recurso de reposición del artículo 14.2 del TRLRHL", "Recurso de alzada ante la Junta de Gobierno"]'::jsonb,1,'Art. 25.3 Ley 22/2006','El recurso de reposición previo es potestativo; contra su resolución cabe reclamación económico-administrativa ante el Tribunal municipal.',null),
('aux-ayto-mad:10-9c98c38b8c','aux-ayto-mad',10,'El Tribunal Económico-Administrativo Municipal de Madrid estará constituido por:','["Cinco miembros", "Un número impar de miembros, con un mínimo de tres", "Un número impar de miembros, con un mínimo de cinco"]'::jsonb,1,'Art. 25.4 Ley 22/2006','Está constituido por un número impar de miembros, con un mínimo de tres, designados por el Pleno.',null),
('aux-ayto-mad:10-9a0dd781a4','aux-ayto-mad',10,'Los miembros del Tribunal Económico-Administrativo Municipal de Madrid son designados por:','["La Junta de Gobierno, entre funcionarios del Ayuntamiento", "El Pleno, por mayoría absoluta de sus miembros, entre personas de reconocida competencia técnica", "El Alcalde, entre personas de reconocida competencia técnica, dando cuenta al Pleno"]'::jsonb,1,'Art. 25.4 Ley 22/2006','Los designa el Pleno, con el voto favorable de la mayoría absoluta de sus miembros, entre personas de reconocida competencia técnica.',null),
('aux-ayto-mad:10-0667e9a216','aux-ayto-mad',10,'¿Cuál de las siguientes es causa de cese de los miembros del Tribunal Económico-Administrativo Municipal de Madrid?','["El fin del mandato de la Corporación que los designó", "La pérdida de confianza del Alcalde", "Ser condenados mediante sentencia firme por delito doloso"]'::jsonb,2,'Art. 25.4 Ley 22/2006','Cesan a petición propia, por acuerdo del Pleno con la misma mayoría que para su nombramiento, por condena firme por delito doloso o por sanción firme por falta disciplinaria muy grave o grave.',null),
('aux-ayto-mad:10-ccdeae5c8a','aux-ayto-mad',10,'El funcionamiento del Tribunal Económico-Administrativo Municipal de Madrid se basará en criterios de:','["Independencia técnica, celeridad y gratuidad", "Contradicción, oralidad y publicidad", "Jerarquía, eficacia y economía"]'::jsonb,0,'Art. 25.5 Ley 22/2006','El art. 25.5 cita los criterios de independencia técnica, celeridad y gratuidad.',null),
('aux-ayto-mad:10-9ac8ca9368','aux-ayto-mad',10,'El expediente disciplinario de un miembro del Tribunal Económico-Administrativo Municipal de Madrid solo puede incoarlo y resolverlo:','["El Presidente del propio Tribunal", "La Junta de Gobierno", "El Pleno"]'::jsonb,2,'Art. 25.4 Ley 22/2006','Según el art. 25.4, solamente el Pleno podrá acordar la incoación y la resolución del correspondiente expediente disciplinario.',null),
('aux-ayto-mad:10-13c28d15a9','aux-ayto-mad',10,'Según la Ley 22/2006, el ente autónomo de gestión tributaria del Ayuntamiento de Madrid:','["Debe crearlo obligatoriamente la Junta de Gobierno", "Lo crea la Comunidad de Madrid mediante ley a propuesta del Ayuntamiento", "Puede crearlo el Pleno para la gestión integral del sistema tributario municipal"]'::jsonb,2,'Art. 26.1 Ley 22/2006','El Pleno podrá crear un ente autónomo de gestión tributaria que ejerza como propias las competencias municipales de gestión tributaria. En Madrid es la Agencia Tributaria Madrid.',null),
('aux-ayto-mad:10-80eae3c61c','aux-ayto-mad',10,'La función de recaudación del ente autónomo de gestión tributaria del Ayuntamiento de Madrid la ejerce:','["Su titular y los funcionarios adscritos al mismo", "La Tesorería municipal en exclusiva", "La Agencia Estatal de Administración Tributaria por convenio"]'::jsonb,0,'Art. 26.3 Ley 22/2006','Según el art. 26.3, la recaudación la ejerce el titular del ente y los funcionarios adscritos al mismo.',null),
('aux-ayto-mad:10-93c7c26067','aux-ayto-mad',10,'La gestión integral del sistema tributario municipal de Madrid se rige por los principios de:','["Legalidad, publicidad y transparencia", "Capacidad económica, progresividad y no confiscatoriedad", "Eficiencia, suficiencia, agilidad y unidad en la gestión"]'::jsonb,2,'Art. 26.1 Ley 22/2006','El art. 26.1 cita los principios de eficiencia, suficiencia, agilidad y unidad en la gestión.',null),
('aux-ayto-mad:10-fb816649e7','aux-ayto-mad',10,'La asistencia jurídica al Alcalde, a la Junta de Gobierno y a los órganos directivos del Ayuntamiento de Madrid corresponde a:','["El Secretario General del Pleno", "Los Abogados del Estado, mediante convenio con el Ministerio de Justicia", "Los Letrados del Ayuntamiento de Madrid integrados en la Asesoría Jurídica"]'::jsonb,2,'Art. 28.1 Ley 22/2006','Comprende el asesoramiento jurídico y la representación y defensa en juicio del Ayuntamiento y de sus organismos autónomos y entidades públicas empresariales.',null),
('aux-ayto-mad:10-8e3536c244','aux-ayto-mad',10,'El titular de la Asesoría Jurídica del Ayuntamiento de Madrid es nombrado y separado por:','["La Junta de Gobierno", "El Pleno", "El Alcalde"]'::jsonb,0,'Art. 28.2 Ley 22/2006','La Asesoría Jurídica es un órgano directivo cuyo titular nombra y separa la Junta de Gobierno.',null),
('aux-ayto-mad:10-88d08e081f','aux-ayto-mad',10,'El titular de la Asesoría Jurídica del Ayuntamiento de Madrid debe ser elegido entre:','["Abogados en ejercicio con más de diez años de experiencia profesional", "Letrados del Ayuntamiento con más de cinco años de servicio", "Funcionarios a los que se exija el título de licenciado en Derecho o funcionarios con habilitación de carácter nacional"]'::jsonb,2,'Art. 28.2 Ley 22/2006','Se elige entre funcionarios del Estado, de las CCAA o de los entes locales a los que se exija la licenciatura en Derecho, o entre funcionarios de Administración local con habilitación de carácter nacional.',null),
('aux-ayto-mad:10-03513857e9','aux-ayto-mad',10,'Los Letrados del Ayuntamiento de Madrid pueden asumir el asesoramiento y la defensa en juicio de las sociedades mercantiles locales:','["En todo caso y de forma gratuita", "Mediante la suscripción del oportuno convenio con compensación económica a la Hacienda municipal", "Nunca, porque solo defienden al Ayuntamiento y a sus organismos autónomos"]'::jsonb,1,'Art. 28.5 Ley 22/2006','El art. 28.5 lo permite mediante convenio en el que se fija la compensación económica a abonar a la Hacienda municipal.',null),
('aux-ayto-mad:10-6c39509885','aux-ayto-mad',10,'Los Abogados del Estado pueden representar, defender y asesorar al Ayuntamiento de Madrid:','["Solo ante el Tribunal Constitucional y previa autorización del Pleno", "En todo caso, cuando lo pida el Alcalde", "Mediante convenio de colaboración, a propuesta o previa audiencia del titular de la Asesoría Jurídica"]'::jsonb,2,'Art. 28.6 Ley 22/2006','El art. 28.6 lo permite mediante convenio, a propuesta o previa audiencia del titular de la Asesoría Jurídica.',null),
('aux-ayto-mad:10-6f2afdefea','aux-ayto-mad',10,'Los Letrados del Ayuntamiento de Madrid pueden asumir la defensa en juicio de las autoridades y empleados municipales cuando:','["El empleado sea demandante, pero no cuando sea demandado o acusado", "Los procedimientos se sigan por actos u omisiones relacionados con el cargo y no exista conflicto de intereses", "Lo solicite el empleado, cualquiera que sea el motivo del procedimiento"]'::jsonb,1,'Art. 29 Ley 22/2006','En los términos que fije el Pleno, pueden defenderlos cualquiera que sea su posición procesal, si el procedimiento se debe a actos u omisiones relacionados con el cargo y no hay conflicto de intereses.',null),
('aux-ayto-mad:10-1489ac7bb3','aux-ayto-mad',10,'Ante los juzgados y tribunales, los Letrados del Ayuntamiento de Madrid tienen los derechos, deberes y prerrogativas establecidos para:','["Los abogados colegiados en ejercicio ante esos juzgados", "Los letrados de las Comunidades Autónomas", "La representación y defensa en juicio de la Administración General del Estado"]'::jsonb,2,'Art. 30.1 Ley 22/2006','Según el art. 30.1, tienen los mismos derechos, deberes y prerrogativas que la asistencia jurídica de la Administración General del Estado.',null),
('aux-ayto-mad:10-fa91efb36a','aux-ayto-mad',10,'Además de los supuestos del artículo 52.2 de la LBRL, ponen fin a la vía administrativa en el Ayuntamiento de Madrid los actos dictados por los órganos municipales cuando ejerzan competencias atribuidas por el Alcalde y la Junta de Gobierno mediante:','["Desconcentración", "Encomienda de gestión", "Delegación"]'::jsonb,0,'Art. 53 Ley 22/2006','El art. 53 añade los actos dictados en ejercicio de competencias atribuidas por el Alcalde y la Junta de Gobierno mediante la técnica de la desconcentración.',null),
('aux-ayto-mad:10-bc4339d686','aux-ayto-mad',10,'Según la Ley 22/2006, la práctica de las notificaciones de los actos del Ayuntamiento de Madrid:','["Podrá encomendarse a personal auxiliar municipal habilitado al efecto", "Solo puede hacerla un agente de la policía municipal", "Corresponde en exclusiva al operador designado para prestar el servicio postal universal"]'::jsonb,0,'Art. 50.1 Ley 22/2006','El art. 50.1 permite encomendarla a personal auxiliar municipal habilitado; sus notificaciones dejan constancia fehaciente de la recepción o el rechazo (art. 50.2).',null),
('aux-ayto-mad:10-307cfca8f1','aux-ayto-mad',10,'Según la Ley 22/2006, el tablón de edictos del Ayuntamiento de Madrid podrá realizarse a través de medios electrónicos, garantizando el libre acceso mediante terminales en:','["Las oficinas de Correos de la ciudad", "Las sedes de los grupos políticos municipales y de las asociaciones vecinales", "Todas las Juntas de Distrito y dependencias municipales"]'::jsonb,2,'Art. 51.2 Ley 22/2006','Debe garantizarse el libre acceso con terminales de acceso al tablón en todas las Juntas de Distrito y dependencias municipales.',null),
('aux-ayto-mad:10-49bea4ba67','aux-ayto-mad',10,'El Alcalde y la Junta de Gobierno pueden imponer multas coercitivas como medio de ejecución forzosa de sus actos de hasta:','["1.500 euros", "3.000 euros", "6.000 euros"]'::jsonb,1,'Art. 52.1 Ley 22/2006','Pueden imponer multas coercitivas de hasta 3.000 euros, actualizables con el IPC, reiteradas por periodos de 15 días.',null),
('aux-ayto-mad:10-c10d3676ec','aux-ayto-mad',10,'Las multas coercitivas del artículo 52 de la Ley 22/2006 pueden reiterarse por cuantos períodos sean suficientes para cumplir lo ordenado, de:','["30 días", "15 días", "10 días"]'::jsonb,1,'Art. 52.1 Ley 22/2006','Según el art. 52.1, se reiteran por cuantos períodos de 15 días sean suficientes para cumplir lo ordenado.',null),
('aux-ayto-mad:10-970349e244','aux-ayto-mad',10,'Según la Ley 22/2006, la multa coercitiva es:','["Incompatible con la sanción por los mismos hechos", "Independiente de las sanciones que puedan imponerse y compatible con ellas", "Una sanción administrativa más grave que la multa ordinaria por infringir la ordenanza"]'::jsonb,1,'Art. 52.2 Ley 22/2006','La multa coercitiva es independiente de las sanciones y compatible con ellas.',null),
('aux-ayto-mad:10-a4e64368e5','aux-ayto-mad',10,'En la imposición de sanciones por incumplir las ordenanzas, la Ley 22/2006 permite sustituir la sanción económica por:','["Una amonestación pública en el Boletín del Ayuntamiento con el nombre del infractor", "El doble de la sanción en días de arresto domiciliario", "Trabajos en beneficio de la comunidad o asistencia obligatoria a cursos de formación, entre otras medidas"]'::jsonb,2,'Art. 52.3 Ley 22/2006','Por resolución motivada puede sustituirse por trabajos en beneficio de la comunidad, cursos de formación, sesiones individualizadas u otras medidas de sensibilización o reparación.',null),
('aux-ayto-mad:10-7de24dfdc4','aux-ayto-mad',10,'Las funciones de fe pública de los actos de los órganos unipersonales del Ayuntamiento de Madrid, salvo las atribuidas a determinados secretarios, las ejercen los titulares de órganos directivos o funcionarios que determine:','["La Junta de Gobierno", "El Pleno", "El Secretario General del Pleno"]'::jsonb,0,'Art. 55 Ley 22/2006','Según el art. 55, las ejercen los titulares de órganos directivos o funcionarios que determine la Junta de Gobierno.',null),
('aux-ayto-mad:10-a772c4a90f','aux-ayto-mad',10,'Según la Ley 22/2006, el Ayuntamiento de Madrid podrá dotarse de un Boletín propio:','["Con formato electrónico o informático", "Solo en formato papel", "Que sustituye la publicación de sus normas en el Boletín Oficial de la Comunidad de Madrid"]'::jsonb,0,'Art. 51.1 Ley 22/2006','Puede dotarse de un Boletín propio electrónico o informático, sin perjuicio de la obligación de publicar en los diarios oficiales correspondientes.',null),
('aux-ayto-mad:10-933ffd5c38','aux-ayto-mad',10,'Corresponde también a los Letrados del Ayuntamiento de Madrid la representación y defensa en juicio:','["Del Pleno, en los términos que se determinen por este", "De los grupos políticos municipales", "De los vecinos que lo soliciten frente a otras administraciones"]'::jsonb,0,'Art. 28.4 Ley 22/2006','El art. 28.4 les atribuye también la representación y defensa en juicio del Pleno, en los términos que este determine.',null),
('aux-ayto-mad:10-607b10e5a6','aux-ayto-mad',10,'Según la Ley 22/2006, la organización de la Administración del Ayuntamiento de Madrid corresponde:','["A la Comunidad de Madrid, mediante ley", "Al Estado, mediante real decreto", "Al propio Ayuntamiento, en el marco de esta Ley"]'::jsonb,2,'Art. 20 Ley 22/2006','El art. 20 dice que la organización de la Administración del Ayuntamiento de Madrid corresponde al mismo en el marco de esta Ley.',null),
('aux-ayto-mad:10-b27bcd30b8','aux-ayto-mad',10,'El ente autónomo de gestión tributaria, cuando se crea, ejerce las competencias municipales de gestión en materia tributaria:','["Por delegación del Alcalde", "Como propias", "Por encomienda de gestión de la Tesorería"]'::jsonb,1,'Art. 26.1 Ley 22/2006','El art. 26.1 dice que es responsable de ejercer como propias las competencias municipales de gestión tributaria.',null),
('aux-ayto-mad:10-6cf8a13637','aux-ayto-mad',10,'El Tribunal Económico-Administrativo Municipal de Madrid también puede, si se lo piden los órganos municipales competentes:','["Aprobar las ordenanzas fiscales", "Dictaminar los proyectos de ordenanzas fiscales", "Liquidar los tributos municipales"]'::jsonb,1,'Art. 25.1 c) Ley 22/2006','El art. 25.1 c) prevé que elabore estudios y propuestas tributarias y dictamine los proyectos de ordenanzas fiscales cuando se lo pidan los órganos competentes.',null),
('aux-ayto-mad:11-16b701a5ec','aux-ayto-mad',11,'¿Cuál de los siguientes es un órgano superior, y no directivo, en los municipios de gran población?','["El interventor general municipal", "El Secretario General del Pleno", "Los miembros de la Junta de Gobierno Local"]'::jsonb,2,'Art. 130.1 LBRL','Son órganos superiores el Alcalde y los miembros de la Junta de Gobierno Local. El Secretario General del Pleno y el interventor general son órganos directivos.',null),
('aux-ayto-mad:11-01bcfdbae6','aux-ayto-mad',11,'El nombramiento de los coordinadores generales y directores generales de los municipios de gran población debe hacerse, como regla general, entre funcionarios de carrera del subgrupo:','["A1", "A1 o A2", "A2"]'::jsonb,0,'Art. 130.3 LBRL','Se nombran entre funcionarios de carrera del subgrupo A1, salvo que el Reglamento Orgánico permita, por las funciones del puesto, que su titular no sea funcionario.',null),
('aux-ayto-mad:11-2285a55da0','aux-ayto-mad',11,'Acordar al inicio del mandato el número, denominación y competencias de las áreas en que se estructura la Administración municipal corresponde:','["Al Alcalde", "Al Pleno", "A la Junta de Gobierno"]'::jsonb,0,'Art. 14.3 h) Ley 22/2006','Es atribución del Alcalde, en el marco de las normas orgánicas aprobadas por el Pleno, y solo es delegable en la Junta de Gobierno (art. 14.4).',null),
('aux-ayto-mad:11-9ec16acb44','aux-ayto-mad',11,'Establecer la organización y estructura de la Administración municipal ejecutiva y nombrar y cesar a los titulares de los órganos directivos corresponde:','["Al Pleno", "Al Alcalde", "A la Junta de Gobierno"]'::jsonb,2,'Art. 17.1 h) Ley 22/2006','Corresponde a la Junta de Gobierno, en el marco de las normas orgánicas del Pleno, y es indelegable (art. 17.2).',null),
('aux-ayto-mad:11-29607027de','aux-ayto-mad',11,'Según la Ley 22/2006, la creación de órganos directivos en el ámbito de la Administración del Ayuntamiento de Madrid corresponde a:','["El Pleno, por mayoría absoluta del número legal de miembros", "La Junta de Gobierno, en el marco del Reglamento orgánico", "El Alcalde, mediante decreto"]'::jsonb,1,'Art. 21.1 Ley 22/2006','El art. 21.1 atribuye a la Junta de Gobierno, en el marco del Reglamento orgánico, la creación de órganos directivos.',null),
('aux-ayto-mad:11-2053f6c7dc','aux-ayto-mad',11,'Los titulares de los órganos directivos del Ayuntamiento de Madrid serán nombrados atendiendo a criterios de:','["Mérito y capacidad mediante concurso de méritos en todo caso", "Confianza política y antigüedad", "Competencia profesional y experiencia"]'::jsonb,2,'Art. 21.2 Ley 22/2006','Se nombran atendiendo a criterios de competencia profesional y experiencia, según lo que determine el Reglamento orgánico.',null),
('aux-ayto-mad:11-8836e0b170','aux-ayto-mad',11,'Los titulares de los órganos directivos del Ayuntamiento de Madrid quedan sometidos al régimen de incompatibilidades de:','["La legislación de régimen local aplicable a los concejales", "La Ley 53/1984, de Incompatibilidades del Personal al Servicio de las Administraciones Públicas", "La Ley 3/2015, reguladora del ejercicio del alto cargo de la Administración General del Estado"]'::jsonb,1,'Art. 21.4 Ley 22/2006','El art. 21.4 los somete a la Ley 53/1984 y a otras normas estatales o autonómicas aplicables. Los miembros de los órganos ejecutivos de gobierno se rigen por las incompatibilidades de los concejales (art. 18.2).',null),
('aux-ayto-mad:11-f7ac770bc6','aux-ayto-mad',11,'En los municipios de gran población, la determinación de los niveles esenciales de la organización municipal (grandes áreas de gobierno, coordinadores generales y direcciones generales) tiene naturaleza:','["Orgánica, y su aprobación corresponde al Pleno", "Reglamentaria ordinaria, y la aprueba la Junta de Gobierno Local", "De simple acto organizativo del Alcalde"]'::jsonb,0,'Art. 123.1 c) LBRL','El art. 123.1 c) incluye entre los reglamentos orgánicos la determinación de los niveles esenciales de la organización municipal, sin perjuicio de que el Alcalde fije el número de cada uno de esos órganos.',null),
('aux-ayto-mad:11-49a0fca8eb','aux-ayto-mad',11,'En los municipios de gran población, los coordinadores generales dependen directamente de:','["El Secretario General del Pleno", "Los miembros de la Junta de Gobierno Local", "Los directores generales"]'::jsonb,1,'Art. 123.1 c) LBRL','El art. 123.1 c) describe a los coordinadores generales como dependientes directamente de los miembros de la Junta de Gobierno Local, con funciones de coordinación de las direcciones generales de su área.',null),
('aux-ayto-mad:11-ce1ec2a1f6','aux-ayto-mad',11,'Según la Ley 7/1985, en los municipios de gran población corresponde al Alcalde, dentro de los niveles esenciales aprobados por el Pleno:','["Crear nuevas áreas de gobierno sin límite", "Aprobar el reglamento orgánico que regula la organización municipal", "Determinar el número de cada uno de los órganos y establecer niveles complementarios inferiores"]'::jsonb,2,'Art. 123.1 c) LBRL','El art. 123.1 c) deja a salvo las atribuciones del Alcalde para determinar el número de cada uno de esos órganos y establecer niveles complementarios inferiores.',null),
('aux-ayto-mad:11-a6a04bb451','aux-ayto-mad',11,'¿Cuál de los siguientes es un órgano directivo en los municipios de gran población según la Ley 7/1985?','["El titular de la asesoría jurídica", "Los miembros de la Junta de Gobierno Local", "El Alcalde"]'::jsonb,0,'Art. 130.1 B) LBRL','Son órganos directivos los coordinadores generales, los directores generales, el titular del órgano de apoyo a la Junta de Gobierno, el titular de la asesoría jurídica, el Secretario general del Pleno, el interventor general y, en su caso, el titular del órgano de gestión tributaria.',null),
('aux-ayto-mad:11-f05f052c93','aux-ayto-mad',11,'Tienen también la consideración de órganos directivos en los municipios de gran población:','["Los Concejales Presidentes de Distrito", "Los titulares de los máximos órganos de dirección de los organismos autónomos y entidades públicas empresariales locales", "Los portavoces de los grupos políticos y los concejales con delegación especial"]'::jsonb,1,'Art. 130.2 LBRL','Así lo establece el art. 130.2.',null),
('aux-ayto-mad:11-9ed139fc52','aux-ayto-mad',11,'En los municipios de gran población, los órganos superiores y directivos quedan sometidos al régimen de incompatibilidades de:','["El Estatuto Básico del Empleado Público", "La Ley 53/1984, de Incompatibilidades del personal al servicio de las Administraciones públicas", "La Ley Orgánica del Régimen Electoral General, como los concejales"]'::jsonb,1,'Art. 130.4 LBRL','Así lo establece el art. 130.4.',null),
('aux-ayto-mad:11-afa02d9b0f','aux-ayto-mad',11,'Según el Reglamento Orgánico del Gobierno y de la Administración del Ayuntamiento de Madrid, ¿cuántas Áreas de Gobierno puede haber como máximo?','["15", "12", "18"]'::jsonb,0,'Art. 40.2 ROGA','El número de Áreas de Gobierno no podrá exceder de 15; su número, denominación y atribuciones los determina el alcalde.',null),
('aux-ayto-mad:11-eb4e2647bc','aux-ayto-mad',11,'¿A quién corresponde determinar el número, la denominación y las atribuciones de las Áreas de Gobierno del Ayuntamiento de Madrid?','["Al Pleno, a propuesta del alcalde", "A la Junta de Gobierno", "Al alcalde"]'::jsonb,2,'Art. 40.2 ROGA','Corresponde al alcalde, al amparo de los arts. 123.1.c) y 124.4.k) de la LBRL, determinar el número, denominación y atribuciones de las Áreas.',null),
('aux-ayto-mad:11-2314e29e77','aux-ayto-mad',11,'¿Qué constituyen las Áreas de Gobierno en la organización municipal de Madrid?','["Los órganos complementarios de la Junta de Gobierno", "Los niveles esenciales de la organización municipal", "Las unidades de gestión desconcentrada de los distritos"]'::jsonb,1,'Art. 40.1 ROGA','Las Áreas de Gobierno constituyen los niveles esenciales de la organización municipal y comprenden uno o varios sectores funcionalmente homogéneos.',null),
('aux-ayto-mad:11-79da005225','aux-ayto-mad',11,'Además de las Direcciones Generales u órganos similares, ¿con qué órgano contará en todo caso cada Área de Gobierno?','["Con un Consejo Sectorial de participación", "Con una Intervención Delegada", "Con una Secretaría General Técnica"]'::jsonb,2,'Art. 41.1 ROGA','Las Áreas de Gobierno, en las que podrá existir uno o más coordinadores generales, contarán con una Secretaría General Técnica y se estructurarán en Direcciones Generales u órganos similares.',null),
('aux-ayto-mad:11-72b347208f','aux-ayto-mad',11,'¿Cuántos coordinadores generales puede haber en un Área de Gobierno?','["Solo uno", "Uno o más", "Como máximo dos"]'::jsonb,1,'Art. 41.1 ROGA','El art. 41.1 prevé que en las Áreas de Gobierno «podrá existir uno o más coordinadores generales»; si hay varios, el acuerdo de organización delimita los sectores de cada uno (art. 46.2).',null),
('aux-ayto-mad:11-c62907c4b6','aux-ayto-mad',11,'¿Cuál es el orden jerárquico de los órganos directivos de las Áreas de Gobierno, de mayor a menor?','["Coordinador general, secretario general técnico y director general", "Secretario general técnico, coordinador general y director general", "Coordinador general, director general y secretario general técnico"]'::jsonb,0,'Art. 42.2 ROGA','Los órganos directivos se ordenan jerárquicamente así: coordinador general, secretario general técnico, director general u órgano asimilado.',null),
('aux-ayto-mad:11-2de01dea89','aux-ayto-mad',11,'¿Quiénes son los jefes superiores de cada Área de Gobierno?','["Los coordinadores generales", "Los concejales de Gobierno y los consejeros-delegados de Gobierno", "Los tenientes de alcalde"]'::jsonb,1,'Art. 42.1 ROGA','Los concejales de Gobierno y consejeros-delegados de Gobierno son los jefes superiores del Área de Gobierno correspondiente.',null),
('aux-ayto-mad:11-eb37c80394','aux-ayto-mad',11,'¿Quién nombra y cesa a los coordinadores generales, secretarios generales técnicos y directores generales del Ayuntamiento de Madrid?','["El concejal de Gobierno del Área", "El alcalde", "La Junta de Gobierno"]'::jsonb,2,'Art. 49.1 ROGA','Los titulares de estos órganos directivos son nombrados y cesados por la Junta de Gobierno; el titular del Área solo propone el nombramiento (art. 44.j).',null),
('aux-ayto-mad:11-e5c3d04f23','aux-ayto-mad',11,'¿Qué puesto directivo no puede proveerse, en ningún caso, con personal que no tenga la condición de funcionario?','["El de secretario general técnico", "El de coordinador general", "El de director general"]'::jsonb,0,'Art. 49.3 ROGA','Los puestos de coordinador general pueden proveerse con personal no funcionario, pero esta excepción no se aplica a los secretarios generales técnicos.',null),
('aux-ayto-mad:11-7f9bdc2ba4','aux-ayto-mad',11,'¿Qué forma revisten las decisiones administrativas que adoptan los órganos directivos del Ayuntamiento de Madrid?','["Decreto", "Resolución", "Acuerdo"]'::jsonb,1,'Art. 50.1 ROGA','Las decisiones de los órganos directivos revisten la forma de resolución; las de los concejales de Gobierno, de Coordinación y delegados, la de decreto (art. 39).',null)
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('aux-ayto-mad:11-3b5ebdbda9','aux-ayto-mad',11,'¿Qué forma revisten las resoluciones administrativas que adoptan los concejales de Gobierno?','["La de acuerdo", "La de decreto", "La de resolución"]'::jsonb,1,'Art. 39.1 ROGA','Las resoluciones de los concejales de Gobierno, de Coordinación y delegados revisten la forma de decreto y se denominan decretos del concejal correspondiente.',null),
('aux-ayto-mad:11-83a679080e','aux-ayto-mad',11,'¿Qué rango tienen los secretarios generales técnicos?','["El de subdirector general", "El de director general", "El de coordinador general"]'::jsonb,1,'Art. 47.1 ROGA','A los secretarios generales técnicos, con rango de director general, les corresponden la gestión de los servicios comunes y las demás funciones del art. 47.',null),
('aux-ayto-mad:11-a1c90591a9','aux-ayto-mad',11,'¿De quién dependen directamente, con carácter general, los secretarios generales técnicos?','["Del alcalde", "Del coordinador general del Área", "Del titular del Área de Gobierno correspondiente"]'::jsonb,2,'Art. 47.3 ROGA','Los secretarios generales técnicos dependen directamente del titular del Área de Gobierno; excepcionalmente pueden depender funcionalmente de un Área de Coordinación o Delegada.',null),
('aux-ayto-mad:11-698f6a6cc9','aux-ayto-mad',11,'¿Cuál de estas funciones corresponde al secretario general técnico de un Área de Gobierno?','["La gestión de los servicios comunes", "La fiscalización interna de los gastos del Área", "El nombramiento de los directores generales"]'::jsonb,0,'Art. 47.1 a) ROGA','Entre sus funciones están la gestión de los servicios comunes, la coordinación en ese ámbito y la asistencia jurídica y técnica al titular del Área.',null),
('aux-ayto-mad:11-4a301b3b88','aux-ayto-mad',11,'¿Bajo la dependencia directa de quién ejercen sus funciones los directores generales?','["De un coordinador general o de un concejal de Coordinación o delegado", "De la Junta de Gobierno, directamente", "Del secretario general técnico del Área"]'::jsonb,0,'Art. 48.1 ROGA','Los directores generales dirigen y gestionan uno o varios ámbitos funcionalmente homogéneos bajo la dependencia directa de un coordinador general o de un concejal de Coordinación o delegado.',null),
('aux-ayto-mad:11-b096cb3581','aux-ayto-mad',11,'¿A quién corresponde la elaboración, seguimiento y control del presupuesto anual que se asigne a una Dirección General?','["Al director general", "Al coordinador general", "Al secretario general técnico"]'::jsonb,0,'Art. 48.2 d) ROGA','Entre las funciones generales de los directores generales figura la elaboración, seguimiento y control del presupuesto anual que se les asigne.',null),
('aux-ayto-mad:11-d6d4732a43','aux-ayto-mad',11,'¿Quién propone a la Junta de Gobierno el nombramiento de los titulares de los órganos directivos de un Área?','["El alcalde", "El concejal de Gobierno o consejero-delegado titular del Área", "El concejal-delegado de la Dirección General"]'::jsonb,1,'Art. 44 j) ROGA','Corresponde a los concejales de Gobierno y consejeros-delegados de Gobierno proponer a la Junta de Gobierno el nombramiento de los titulares de los órganos directivos de su Área.',null),
('aux-ayto-mad:11-e71902b758','aux-ayto-mad',11,'¿A quién corresponde resolver los conflictos entre los órganos directivos dependientes de un Área de Gobierno?','["Al coordinador general", "Al concejal de Gobierno o consejero-delegado de Gobierno del Área", "A la Junta de Gobierno"]'::jsonb,1,'Art. 44 i) ROGA','Resolver los conflictos entre los órganos directivos dependientes de su Área es una de las funciones del art. 44.',null),
('aux-ayto-mad:11-9925687641','aux-ayto-mad',11,'¿Quiénes son los consejeros-delegados de Gobierno?','["Los miembros de la Junta de Gobierno que no son concejales", "Los tenientes de alcalde con Área de Gobierno", "Los concejales que coordinan un ámbito bajo un concejal de Gobierno"]'::jsonb,0,'Art. 36.1 ROGA','Son consejeros-delegados de Gobierno los miembros de la Junta de Gobierno que no ostenten la condición de concejal; tienen las mismas funciones que los concejales de Gobierno.',null),
('aux-ayto-mad:11-733c1e5f80','aux-ayto-mad',11,'¿Qué diferencia a los concejales de Coordinación de los concejales de Gobierno?','["Que no forman parte de la Junta de Gobierno", "Que solo pueden dirigir una Dirección General", "Que los nombra el Pleno"]'::jsonb,0,'Art. 37.1 ROGA','Los concejales de Coordinación no forman parte de la Junta de Gobierno y actúan bajo la superior dirección de un concejal de Gobierno o consejero-delegado.',null),
('aux-ayto-mad:11-929b204d2e','aux-ayto-mad',11,'¿Cuál de estas funciones de los concejales de Gobierno no tienen los concejales de Coordinación ni los concejales-delegados?','["Ejercer la dirección e inspección de su Área", "Resolver los conflictos entre los órganos directivos de su Área", "Elevar al Pleno las propuestas de su Área"]'::jsonb,2,'Art. 45.1 ROGA','Tienen las funciones del art. 44 salvo las letras b), c), d), e) y j): entre ellas, elevar propuestas al Pleno (letra c).',null),
('aux-ayto-mad:11-27a5f4449a','aux-ayto-mad',11,'¿Cómo se denomina el primer teniente de alcalde del Ayuntamiento de Madrid?','["Teniente de alcalde decano", "Alcalde accidental", "Vicealcalde"]'::jsonb,2,'Art. 34.4 ROGA','El primer teniente de alcalde se denomina vicealcalde.',null),
('aux-ayto-mad:11-4d477d041f','aux-ayto-mad',11,'¿Qué tratamiento tienen los tenientes de alcalde del Ayuntamiento de Madrid?','["El de señoría", "El de excelencia", "El de ilustrísima"]'::jsonb,2,'Art. 34.3 ROGA','Los tenientes de alcalde tienen el tratamiento de ilustrísima.',null),
('aux-ayto-mad:11-f22c93c4a8','aux-ayto-mad',11,'¿Entre quiénes nombra el alcalde a los tenientes de alcalde?','["Entre los miembros de la Junta de Gobierno, sean o no concejales", "Entre los concejales que formen parte de la Junta de Gobierno", "Entre todos los concejales del Pleno"]'::jsonb,1,'Art. 34.1 ROGA','El alcalde puede nombrar tenientes de alcalde entre los concejales que formen parte de la Junta de Gobierno; le sustituyen por orden de nombramiento.',null),
('aux-ayto-mad:11-9e12651f13','aux-ayto-mad',11,'¿Qué órgano ejerce la función de control y fiscalización interna de la gestión económico-financiera del Ayuntamiento de Madrid?','["La Tesorería municipal", "El órgano de contabilidad del Área de Hacienda", "La Intervención General"]'::jsonb,2,'Art. 59.1 ROGA','La función interventora, de control financiero y de control de eficacia corresponde a la Intervención General del Ayuntamiento de Madrid.',null),
('aux-ayto-mad:11-49e53bc0be','aux-ayto-mad',11,'¿A qué Área se adscribe orgánicamente la Intervención General del Ayuntamiento de Madrid?','["A la competente en materia de Coordinación Territorial", "A la competente en materia de Hacienda", "A la Alcaldía"]'::jsonb,1,'Art. 59.2 ROGA','La Intervención General actúa con plena autonomía, pero se adscribe orgánicamente al Área competente en materia de Hacienda.',null),
('aux-ayto-mad:11-9c24c53643','aux-ayto-mad',11,'¿Entre quiénes se nombra al tesorero municipal del Ayuntamiento de Madrid?','["Entre funcionarios de Administración Local con habilitación de carácter nacional", "Entre funcionarios de carrera de cualquier Administración con título de licenciado", "Libremente por el alcalde entre profesionales con experiencia"]'::jsonb,0,'Art. 60.1 ROGA','Las funciones de tesorería, excluida la recaudación, las ejerce el tesorero, nombrado entre funcionarios de Administración Local con habilitación de carácter nacional.',null),
('aux-ayto-mad:11-f039fec99b','aux-ayto-mad',11,'¿Qué función queda excluida de las que ejerce el tesorero municipal del Ayuntamiento de Madrid?','["La custodia de fondos", "El pago de las obligaciones", "La recaudación"]'::jsonb,2,'Art. 60.1 ROGA','Las funciones públicas de tesorería se ejercen por el tesorero municipal, excluida la recaudación.',null),
('aux-ayto-mad:11-b3ad1a9f4d','aux-ayto-mad',11,'¿Qué órgano es el encargado de la asistencia jurídica del Ayuntamiento de Madrid y de sus organismos públicos?','["La Asesoría Jurídica", "La Secretaría General Técnica de cada Área", "La Secretaría General del Pleno"]'::jsonb,0,'Art. 51.1 ROGA','La Asesoría Jurídica, en la que se integra el Cuerpo de Letrados, es el órgano encargado de la asistencia jurídica del Ayuntamiento y de sus organismos públicos.',null),
('aux-ayto-mad:11-736e2e5912','aux-ayto-mad',11,'¿Qué órgano aprueba el Proyecto de Presupuesto General del Ayuntamiento de Madrid que elabora el Área competente en Hacienda?','["El Pleno, directamente", "El alcalde", "La Junta de Gobierno"]'::jsonb,2,'Art. 58.2 a) ROGA','Las funciones de presupuestación del Área de Hacienda incluyen la elaboración del Proyecto de Presupuesto General para su aprobación por la Junta de Gobierno.',null),
('aux-ayto-mad:12-3196bef13f','aux-ayto-mad',12,'En los municipios de gran población, la creación de los distritos y la determinación del porcentaje mínimo de recursos presupuestarios que deben gestionar corresponde a:','["El Pleno", "La Junta de Gobierno Local", "El Alcalde"]'::jsonb,0,'Art. 128.2 LBRL','Corresponde al Pleno crear los distritos, regularlos y fijar en norma orgánica el porcentaje mínimo de recursos que gestionarán en su conjunto.',null),
('aux-ayto-mad:12-cd070b641f','aux-ayto-mad',12,'Nombrar y cesar a los Presidentes de los Distritos corresponde:','["Al Pleno", "A la Junta de Gobierno", "Al Alcalde"]'::jsonb,2,'Art. 14.3 d) Ley 22/2006','El Alcalde nombra y cesa a los miembros de la Junta de Gobierno, a los Tenientes de Alcalde y a los Presidentes de los Distritos.',null),
('aux-ayto-mad:12-d9b68cb18c','aux-ayto-mad',12,'Según la Ley 22/2006, la creación de Distritos como divisiones territoriales con órganos de gestión desconcentrada es, para el Pleno:','["Potestativa", "Obligatoria", "Necesaria solo si lo pide el 10 % de los vecinos"]'::jsonb,1,'Art. 22.1 Ley 22/2006','El art. 22.1 dice que el Pleno deberá crear Distritos, para impulsar y desarrollar la participación ciudadana en la gestión de los asuntos municipales.',null),
('aux-ayto-mad:12-67b9814680','aux-ayto-mad',12,'La Presidencia de un Distrito del Ayuntamiento de Madrid corresponderá:','["A un vecino del Distrito elegido por la Junta Municipal", "En todo caso a un Concejal", "A un funcionario con la categoría de director general"]'::jsonb,1,'Art. 22.2 Ley 22/2006','Según el art. 22.2, la Presidencia del Distrito corresponderá en todo caso a un Concejal.',null),
('aux-ayto-mad:12-28be7036be','aux-ayto-mad',12,'Según la Ley 7/1985, los municipios del régimen común podrán establecer órganos territoriales de gestión desconcentrada para:','["Facilitar la participación ciudadana en la gestión de los asuntos locales y mejorarla, sin perjuicio de la unidad de gobierno y gestión del municipio", "Crear entidades locales menores con personalidad jurídica propia y presupuesto independiente", "Sustituir al Pleno en las materias de interés de cada barrio"]'::jsonb,0,'Art. 24.1 LBRL','Así lo establece el art. 24.1. En los municipios de gran población se aplica el régimen de distritos del art. 128 (art. 24.2).',null),
('aux-ayto-mad:12-9a51b5ef1e','aux-ayto-mad',12,'En los municipios de gran población, el régimen de gestión desconcentrada aplicable es:','["El de las entidades locales menores", "El de las juntas vecinales potestativas", "El de los distritos regulado en el artículo 128 de la Ley 7/1985"]'::jsonb,2,'Art. 24.2 LBRL','Según el art. 24.2, en los municipios del art. 121 se aplica el régimen de gestión desconcentrada del art. 128.',null),
('aux-ayto-mad:12-17397787e4','aux-ayto-mad',12,'En los municipios de gran población, la creación de distritos es:','["Obligatoria", "Obligatoria solo en los de más de un millón de habitantes", "Potestativa"]'::jsonb,0,'Art. 128.1 LBRL','El art. 128.1 dice que los ayuntamientos deberán crear distritos, dotados de órganos de gestión desconcentrada.',null),
('aux-ayto-mad:12-1491917f45','aux-ayto-mad',12,'En los municipios de gran población, la regulación de la división del municipio en distritos y de sus órganos tiene naturaleza:','["Orgánica", "De ordenanza fiscal", "De decreto de Alcaldía"]'::jsonb,0,'Art. 123.1 c) LBRL','La división en distritos y la regulación de sus órganos figuran entre las materias de naturaleza orgánica del art. 123.1 c), sin perjuicio de las atribuciones del Alcalde sobre su administración ejecutiva.',null),
('aux-ayto-mad:12-f295bf8831','aux-ayto-mad',12,'¿En cuántos distritos se divide el término municipal de Madrid según el Reglamento Orgánico de los Distritos?','["20", "22", "21"]'::jsonb,2,'Art. 3.1 RO 6/2021','El término municipal de Madrid se divide en 21 distritos, del 01 Centro al 21 Barajas.',null),
('aux-ayto-mad:12-d126180ed5','aux-ayto-mad',12,'¿Qué órgano puede alterar el número, la denominación y los límites territoriales de los distritos de Madrid?','["La Junta de Gobierno, a propuesta del área de coordinación territorial", "El Pleno, modificando el Reglamento Orgánico de los Distritos", "El alcalde, por decreto"]'::jsonb,1,'Art. 3.2 RO 6/2021','Corresponde al Pleno, mediante la modificación del reglamento orgánico, alterar el número, denominación y límites de los distritos y barrios.',null),
('aux-ayto-mad:12-ba7d21a980','aux-ayto-mad',12,'¿Qué número corresponde al distrito de Barajas en la división del municipio de Madrid?','["17", "19", "21"]'::jsonb,2,'Art. 3.1 RO 6/2021','Barajas es el distrito 21; el 17 es Villaverde y el 19, Vicálvaro.',null),
('aux-ayto-mad:12-07b7b46603','aux-ayto-mad',12,'¿Qué porcentaje mínimo del presupuesto del Ayuntamiento de Madrid deben gestionar los distritos en su conjunto?','["El 11 %", "El 8 %", "El 15 %"]'::jsonb,0,'Art. 7 RO 6/2021','Los recursos gestionados por los distritos en su conjunto no serán en ningún caso inferiores al 11 % del presupuesto del Ayuntamiento.',null),
('aux-ayto-mad:12-f3afc9e211','aux-ayto-mad',12,'¿Quién nombra y separa libremente al concejal presidente del distrito?','["El Pleno", "La Junta de Gobierno", "El alcalde"]'::jsonb,2,'Art. 5 b) RO 6/2021','Son órganos del distrito, entre otros, el concejal presidente, nombrado y separado libremente por el alcalde.',null),
('aux-ayto-mad:12-b06dd11c91','aux-ayto-mad',12,'¿Qué es la Junta Municipal del Distrito según el Reglamento Orgánico de los Distritos?','["El órgano directivo que gestiona los servicios del distrito", "El órgano colegiado de representación político-vecinal del distrito", "El órgano de participación ciudadana con capacidad de adoptar iniciativas"]'::jsonb,1,'Art. 5 a) RO 6/2021','La Junta Municipal es el órgano colegiado de representación político-vecinal, en el que junto a cargos electos participan los vocales vecinos.',null),
('aux-ayto-mad:12-b44f175ab0','aux-ayto-mad',12,'¿Quién determina el número de miembros de cada Junta Municipal de Distrito?','["El alcalde, al nombrar al concejal presidente", "El Pleno del Ayuntamiento, al inicio de cada mandato", "La propia Junta Municipal, en su sesión constitutiva"]'::jsonb,1,'Art. 8.1 RO 6/2021','El número de miembros lo determina el Pleno al inicio de cada mandato, repartiéndolos en proporción a la representación de cada grupo.',null),
('aux-ayto-mad:12-1c54e725b1','aux-ayto-mad',12,'¿Quién nombra a los vocales vecinos de las Juntas Municipales de Distrito?','["El alcalde, a propuesta de los grupos políticos", "El concejal presidente, a propuesta de las asociaciones vecinales", "El Pleno, a propuesta de la Junta de Gobierno"]'::jsonb,0,'Art. 8.2 b) RO 6/2021','Los vocales vecinos son nombrados entre vecinos por el alcalde a propuesta de los grupos políticos (también art. 69.1).',null),
('aux-ayto-mad:12-43d9f2c96b','aux-ayto-mad',12,'¿Qué órgano es el deliberante y consultivo de la Junta Municipal del Distrito?','["El consejo de proximidad", "La comisión de vocales vecinos", "La junta de portavoces"]'::jsonb,2,'Art. 8.3 RO 6/2021','La junta de portavoces es el órgano deliberante y consultivo de la junta municipal del distrito.',null),
('aux-ayto-mad:12-5a88041bc2','aux-ayto-mad',12,'¿Hasta cuántos concejales de su grupo municipal pueden asistir a cada grupo político en la Junta Municipal del Distrito?','["Uno, con voz pero sin voto", "Hasta tres, con voz y voto", "Hasta dos, con voz pero sin voto"]'::jsonb,2,'Art. 9 RO 6/2021','Cada grupo puede estar asistido hasta por dos concejales designados por su grupo municipal, que intervienen con voz pero sin voto.',null),
('aux-ayto-mad:12-e2d75165a5','aux-ayto-mad',12,'Si en la sesión constitutiva de la Junta Municipal del Distrito no concurre la mayoría absoluta de sus miembros, ¿cuándo se celebra la sesión?','["Dos días después, con cualquier número de miembros presentes", "A los cinco días, con la mayoría absoluta", "Al día siguiente, con un tercio de los miembros"]'::jsonb,0,'Art. 10.2 RO 6/2021','Si no concurre la mayoría absoluta, se celebra sesión dos días después, quedando constituida cualquiera que sea el número de presentes.',null),
('aux-ayto-mad:12-c9fed29a40','aux-ayto-mad',12,'¿Con qué periodicidad celebra la Junta Municipal del Distrito sesión plenaria ordinaria?','["Una vez al mes, excepto en agosto", "Una vez al mes, todos los meses del año", "Una vez cada dos meses"]'::jsonb,0,'Art. 14.2 RO 6/2021','La junta municipal celebra sesión plenaria ordinaria una vez al mes, a excepción del mes de agosto.',null),
('aux-ayto-mad:12-60a49fb4fb','aux-ayto-mad',12,'¿Qué proporción de los miembros de la Junta Municipal del Distrito puede solicitar una sesión extraordinaria?','["Al menos un tercio de los miembros presentes", "La mayoría absoluta del número legal de miembros", "Al menos la cuarta parte del número legal de miembros"]'::jsonb,2,'Art. 15.1 RO 6/2021','Hay sesión extraordinaria cuando lo decide el concejal presidente o lo solicita la cuarta parte, al menos, del número legal de miembros.',null),
('aux-ayto-mad:12-5b3fe9a93c','aux-ayto-mad',12,'¿Cuántas sesiones extraordinarias al año puede solicitar como máximo cada miembro de la Junta Municipal del Distrito?','["Tres", "Dos", "Cinco"]'::jsonb,0,'Art. 15.2 RO 6/2021','Ningún miembro de la junta municipal puede solicitar más de tres sesiones extraordinarias al año.',null),
('aux-ayto-mad:12-5b6f712d62','aux-ayto-mad',12,'Solicitada una sesión extraordinaria de la Junta Municipal del Distrito, ¿cuánto puede demorarse como máximo su celebración?','["Diez días hábiles", "Quince días hábiles", "Un mes"]'::jsonb,1,'Art. 15.4 RO 6/2021','La celebración no puede demorarse más de quince días hábiles desde la solicitud; si no se convoca, queda convocada automáticamente para el décimo día hábil siguiente.',null),
('aux-ayto-mad:12-9d7420819c','aux-ayto-mad',12,'En las sesiones extraordinarias urgentes de la Junta Municipal del Distrito, ¿qué ocurre si no se aprecia la urgencia?','["Se aplaza la sesión al día siguiente", "Se tratan los asuntos como sesión ordinaria", "Se levanta acto seguido la sesión"]'::jsonb,2,'Art. 16.2 RO 6/2021','El primer punto del orden del día es el pronunciamiento sobre la urgencia; si no se aprecia, se levanta acto seguido la sesión.',null),
('aux-ayto-mad:12-da3009fc19','aux-ayto-mad',12,'¿Con qué asistencia se constituye válidamente la Junta Municipal del Distrito?','["Un tercio del número legal de sus miembros, con presidente y secretario", "La mayoría absoluta de sus miembros, con presidente y secretario", "Un cuarto del número legal, sin necesidad del secretario"]'::jsonb,0,'Art. 23.2 RO 6/2021','Se constituye con un tercio del número legal de miembros y, en todo caso, con la presencia del presidente y del secretario o sus sustitutos.',null),
('aux-ayto-mad:12-61d08445e9','aux-ayto-mad',12,'¿Por qué mayoría adopta sus acuerdos la Junta Municipal del Distrito como regla general?','["Por mayoría absoluta del número legal de miembros", "Por mayoría de dos tercios de los presentes", "Por mayoría simple de los miembros presentes"]'::jsonb,2,'Art. 33.1 RO 6/2021','Como regla general, por mayoría simple de los presentes: cuando los votos afirmativos son más que los negativos.',null),
('aux-ayto-mad:12-2f188160d8','aux-ayto-mad',12,'¿Qué forma revisten las decisiones de la Junta Municipal del Distrito en el ejercicio de sus competencias?','["La de decreto", "La de resolución", "La de acuerdo"]'::jsonb,2,'Art. 12.2 RO 6/2021','Revisten la forma de acuerdo y se denominan «Acuerdo de la Junta Municipal del Distrito de…».',null),
('aux-ayto-mad:12-4b636fd930','aux-ayto-mad',12,'¿A quién corresponde resolver las recusaciones planteadas contra los miembros de la Junta Municipal del Distrito?','["Al secretario del distrito", "Al concejal presidente", "A la propia Junta Municipal del Distrito"]'::jsonb,2,'Art. 12.1 e) RO 6/2021','Entre las competencias de la junta municipal está resolver las recusaciones contra sus miembros.',null),
('aux-ayto-mad:12-d155e891b3','aux-ayto-mad',12,'¿Cuándo se celebra el debate sobre el estado del distrito?','["Cada dos años, en el primer semestre", "Anualmente, en el último trimestre del año", "Anualmente, durante el primer semestre, salvo el año de elecciones municipales"]'::jsonb,2,'Art. 54.1 RO 6/2021','Se celebra cada año en el primer semestre, en sesión extraordinaria; no hay debate el año en que se celebren elecciones municipales.',null),
('aux-ayto-mad:12-307f372b14','aux-ayto-mad',12,'¿Con qué antelación mínima debe convocarse la sesión del debate sobre el estado del distrito?','["Diez días hábiles", "Cinco días hábiles", "Quince días hábiles"]'::jsonb,0,'Art. 54.2 RO 6/2021','Esta sesión extraordinaria debe convocarse con diez días hábiles, al menos, de antelación.',null),
('aux-ayto-mad:12-97ee4acb66','aux-ayto-mad',12,'¿Qué forma revisten las resoluciones administrativas del concejal presidente del distrito?','["La de resolución", "La de decreto", "La de acuerdo"]'::jsonb,1,'Art. 58.2 RO 6/2021','Revisten la forma de decreto y se denominan decretos del concejal presidente del distrito.',null),
('aux-ayto-mad:12-b2e3db3ca3','aux-ayto-mad',12,'¿Quién nombra y cesa al coordinador del distrito?','["El alcalde, a propuesta de la Junta Municipal", "El concejal presidente, libremente", "La Junta de Gobierno, a propuesta del concejal presidente"]'::jsonb,2,'Art. 61.1 RO 6/2021','El coordinador del distrito es nombrado y cesado por la Junta de Gobierno a propuesta del concejal presidente.',null),
('aux-ayto-mad:12-5b71f45408','aux-ayto-mad',12,'¿Qué rango tiene el coordinador del distrito?','["El de subdirector general", "El de coordinador general", "El de director general"]'::jsonb,2,'Art. 61.2 RO 6/2021','El coordinador del distrito ostenta a todos los efectos el rango de director general.',null),
('aux-ayto-mad:12-3f9bffda41','aux-ayto-mad',12,'¿Qué forma revisten las decisiones administrativas de los coordinadores de distrito?','["La de decreto", "La de acuerdo", "La de resolución"]'::jsonb,2,'Art. 62.2 RO 6/2021','Las decisiones administrativas que adopten los coordinadores de distrito revisten la forma de resolución.',null),
('aux-ayto-mad:12-be93da2904','aux-ayto-mad',12,'¿Entre quiénes se nombra al secretario del distrito?','["Entre funcionarios con habilitación de carácter nacional", "Entre funcionarios de carrera del subgrupo A1", "Entre funcionarios de carrera de los subgrupos A1 o A2"]'::jsonb,1,'Art. 63.2 RO 6/2021','El secretario del distrito se nombra, a propuesta del concejal presidente, entre funcionarios de carrera del subgrupo A1.',null),
('aux-ayto-mad:12-dda5116b08','aux-ayto-mad',12,'¿De quién depende orgánica y funcionalmente el interventor delegado de cada distrito?','["De la Intervención General", "Del coordinador del distrito", "Del concejal presidente del distrito"]'::jsonb,0,'Art. 65 RO 6/2021','Cada distrito cuenta con un interventor delegado que actúa bajo la dependencia orgánica y funcional de la Intervención General y por delegación de esta.',null),
('aux-ayto-mad:12-d6d8c4205a','aux-ayto-mad',12,'¿Cuál de estas personas no puede ser vocal vecino de una Junta Municipal de Distrito de Madrid?','["Quien sea concejal de otro ayuntamiento", "Quien esté empadronado en otro distrito de Madrid", "Quien sea funcionario del Ayuntamiento de Madrid"]'::jsonb,0,'Art. 68 c) RO 6/2021','No pueden ser vocales vecinos quienes sean concejales de otro ayuntamiento, vocales de otra Junta Municipal o incurran en las causas de inelegibilidad o incompatibilidad de los concejales.',null),
('aux-ayto-mad:12-66df2e8da8','aux-ayto-mad',12,'¿Cuántas inasistencias injustificadas consecutivas a sesiones de la Junta Municipal permiten al alcalde cesar a un vocal vecino?','["Tres", "Cinco", "Dos"]'::jsonb,0,'Art. 71 b) RO 6/2021','Puede cesarse al vocal vecino por inasistencia injustificada a tres sesiones consecutivas o a cinco alternas en un año.',null),
('aux-ayto-mad:12-b4af324c9c','aux-ayto-mad',12,'¿Quién suple al concejal presidente del distrito en caso de vacante, ausencia o enfermedad?','["El coordinador del distrito", "Un concejal de los grupos municipales adscrito al distrito designado por el alcalde", "El vocal vecino portavoz del grupo mayoritario"]'::jsonb,1,'Art. 59 RO 6/2021','La concejalía presidencia es suplida por una concejalía de los grupos municipales adscrita al distrito, designada por el alcalde.',null),
('aux-ayto-mad:13-3f56beb45f','aux-ayto-mad',13,'Podrá prescindirse de los trámites de consulta, audiencia e información públicas en el caso de normas:','["Que afecten a derechos de los ciudadanos, o cuando concurran razones de urgencia", "Tributarias o sancionadoras, o cuando concurran razones graves de interés público", "Presupuestarias u organizativas, o cuando concurran razones graves de interés público"]'::jsonb,2,'Art. 133.4 Ley 39/2015','Excepción prevista para normas presupuestarias u organizativas o razones graves de interés público.',null),
('aux-ayto-mad:13-ba78b876b2','aux-ayto-mad',13,'Con carácter previo a la elaboración de un proyecto de ley o reglamento, se sustanciará una consulta pública a través del portal web sobre:','["La opinión del Consejo de Estado y del órgano proponente", "Los problemas que se pretenden solucionar, la necesidad y oportunidad, los objetivos y las posibles soluciones alternativas", "El texto articulado completo del proyecto, el informe de impacto normativo, la memoria económica y el dictamen del Consejo de Estado"]'::jsonb,1,'Art. 133.1 Ley 39/2015','Son los cuatro aspectos de la consulta pública previa.',null),
('aux-ayto-mad:13-d55f6b0eb3','aux-ayto-mad',13,'Para que entren en vigor y produzcan efectos jurídicos, las normas con rango de ley, los reglamentos y disposiciones administrativas habrán de:','["Publicarse en el diario oficial correspondiente", "Firmarse por el Rey y comunicarse a las Cortes Generales", "Comunicarse a todos los Ayuntamientos y Diputaciones afectados"]'::jsonb,0,'Art. 131 Ley 39/2015','La publicación en el diario oficial es requisito de entrada en vigor.',null),
('aux-ayto-mad:13-3cc7317355','aux-ayto-mad',13,'¿Cuáles son los principios de buena regulación del art. 129 de la Ley 39/2015?','["Necesidad, eficacia, proporcionalidad, seguridad jurídica, publicidad y jerarquía", "Igualdad, mérito, capacidad y publicidad", "Necesidad, eficacia, proporcionalidad, seguridad jurídica, transparencia y eficiencia"]'::jsonb,2,'Art. 129.1 Ley 39/2015','Son seis principios de buena regulación.',null),
('aux-ayto-mad:13-7632cf9e5d','aux-ayto-mad',13,'Los reglamentos y disposiciones administrativas NO podrán:','["Tipificar delitos, faltas o infracciones administrativas, establecer penas o sanciones, ni tributos", "Desarrollar una ley", "Regular la organización interna de la Administración ni el funcionamiento de sus órganos colegiados y unidades administrativas"]'::jsonb,0,'Art. 128.2 Ley 39/2015','Tampoco vulnerar la Constitución o las leyes ni regular materias reservadas a las Cortes o a las Asambleas autonómicas.',null),
('aux-ayto-mad:13-3918b61c7a','aux-ayto-mad',13,'Según la Ley 39/2015, el Gobierno de la Nación ejercerá la iniciativa legislativa en los términos de la Constitución mediante:','["La iniciativa legislativa popular", "La elaboración y aprobación de los anteproyectos de ley y la remisión de los proyectos de ley a las Cortes Generales", "Las proposiciones de ley del Senado"]'::jsonb,1,'Art. 127 Ley 39/2015','También podrá aprobar reales decretos-leyes y reales decretos legislativos.',null),
('aux-ayto-mad:13-291e0b9cc0','aux-ayto-mad',13,'Según el principio de eficiencia del art. 129.6, la iniciativa normativa debe:','["Evitar cargas administrativas innecesarias o accesorias y racionalizar la gestión de los recursos públicos", "Aprobarse sin consulta pública previa ni trámite de audiencia, para reducir la duración del procedimiento normativo", "Aumentar los trámites para garantizar el control"]'::jsonb,0,'Art. 129.6 Ley 39/2015','Eficiencia: evitar cargas innecesarias o accesorias.',null),
('aux-ayto-mad:13-fed88b82f6','aux-ayto-mad',13,'El Plan Anual Normativo que deben aprobar las Administraciones contiene:','["Las normas derogadas el año anterior", "Las iniciativas reglamentarias, pero no las legales, que se aprobarán en los cuatro años siguientes", "Las iniciativas legales o reglamentarias que vayan a ser elevadas para su aprobación en el año siguiente"]'::jsonb,2,'Art. 132.1 Ley 39/2015','Se aprueba anualmente y se publica en el Portal de la Transparencia.',null),
('aux-ayto-mad:13-420097bd22','aux-ayto-mad',13,'Según el art. 128.3 de la Ley 39/2015, las disposiciones administrativas:','["Se ajustarán al orden de jerarquía, salvo que la de rango inferior sea posterior en el tiempo y regule una materia más específica", "Tienen todas el mismo rango, y prevalece la posterior", "Se ajustarán al orden de jerarquía y ninguna podrá vulnerar los preceptos de otra de rango superior"]'::jsonb,2,'Art. 128.3 Ley 39/2015','Principio de jerarquía normativa.',null),
('aux-ayto-mad:13-f1412a83e1','aux-ayto-mad',13,'Según el art. 130.1, las Administraciones Públicas revisarán periódicamente su normativa vigente para:','["Adaptarla a los principios de buena regulación y comprobar en qué medida han conseguido sus objetivos", "Adaptarla a los principios de buena regulación, sin necesidad de evaluar si ha conseguido sus objetivos", "Remitirla al Tribunal Constitucional para que verifique su adecuación a la Constitución y a los Estatutos de Autonomía"]'::jsonb,0,'Art. 130.1 Ley 39/2015','El resultado de la evaluación se plasma en un informe que se hará público.',null),
('aux-ayto-mad:13-50fb6d3067','aux-ayto-mad',13,'La consulta pública previa a la elaboración de un proyecto normativo, a través del portal web de la Administración competente, es un instrumento de:','["Participación ciudadana en la elaboración de normas", "Control parlamentario del Gobierno", "Rendición de cuentas de los altos cargos ante el Congreso"]'::jsonb,0,'Art. 133.1 Ley 39/2015','Busca la opinión de los sujetos y organizaciones más representativas potencialmente afectados por la futura norma.',null),
('aux-ayto-mad:13-072e3710a4','aux-ayto-mad',13,'Según la Ley 7/1985, la aprobación de las Ordenanzas locales se ajusta al siguiente procedimiento:','["Aprobación inicial por la Junta de Gobierno, información pública y aprobación definitiva por el Alcalde", "Aprobación por el Pleno y publicación inmediata, sin información pública", "Aprobación inicial por el Pleno, información pública y audiencia, y aprobación definitiva por el Pleno"]'::jsonb,2,'Art. 49 LBRL','El art. 49 fija aprobación inicial por el Pleno, información pública y audiencia a los interesados durante al menos treinta días, y resolución de reclamaciones con aprobación definitiva por el Pleno.',null),
('aux-ayto-mad:13-172dcc8ea7','aux-ayto-mad',13,'El plazo mínimo de información pública y audiencia a los interesados en la aprobación de las ordenanzas locales del régimen común es de:','["Veinte días", "Treinta días", "Quince días"]'::jsonb,1,'Art. 49 b) LBRL','El art. 49 b) fija un plazo mínimo de treinta días para presentar reclamaciones y sugerencias.',null),
('aux-ayto-mad:13-077d194909','aux-ayto-mad',13,'Si durante la información pública de una ordenanza local no se presenta ninguna reclamación o sugerencia:','["Debe repetirse el trámite de información pública", "Se entiende definitivamente adoptado el acuerdo hasta entonces provisional", "El Pleno debe adoptar igualmente un acuerdo de aprobación definitiva"]'::jsonb,1,'Art. 49 LBRL','Según el último párrafo del art. 49, el acuerdo provisional se entiende definitivamente adoptado.',null),
('aux-ayto-mad:13-af974ebaff','aux-ayto-mad',13,'Según la Ley 7/1985, las ordenanzas de las corporaciones locales se publicarán en:','["El «Boletín Oficial» de la Provincia", "El «Boletín Oficial del Estado»", "El tablón de edictos del Ayuntamiento, exclusivamente"]'::jsonb,0,'Art. 70.2 LBRL','Las ordenanzas se publican en el «Boletín Oficial» de la Provincia (en Madrid, el Boletín Oficial de la Comunidad de Madrid) y no entran en vigor hasta su publicación completa y el transcurso del plazo del art. 65.2.',null),
('aux-ayto-mad:13-858fde8914','aux-ayto-mad',13,'Según el artículo 70.2 de la Ley 7/1985, las ordenanzas locales del régimen común entran en vigor:','["Cuando se haya publicado completamente su texto y haya transcurrido el plazo del artículo 65.2", "A los veinte días de su publicación completa en el Boletín Oficial del Estado", "Al día siguiente de su aprobación definitiva por el Pleno"]'::jsonb,0,'Art. 70.2 LBRL','No entran en vigor hasta que se publica completamente su texto y transcurre el plazo de quince días hábiles del art. 65.2 (el plazo de requerimiento del Estado o la Comunidad Autónoma).',null),
('aux-ayto-mad:13-1f8cfde60b','aux-ayto-mad',13,'La potestad reglamentaria de los municipios figura en la Ley 7/1985 como:','["Una potestad que solo tienen los municipios de gran población y las diputaciones", "Una potestad delegada por la Comunidad Autónoma", "Una potestad que les corresponde en todo caso, como administraciones públicas territoriales"]'::jsonb,2,'Art. 4.1 a) LBRL','El art. 4.1 a) atribuye en todo caso a municipios, provincias e islas las potestades reglamentaria y de autoorganización.',null),
('aux-ayto-mad:13-1b9af3d4f3','aux-ayto-mad',13,'En el régimen común de la Ley 7/1985, la aprobación del reglamento orgánico y de las ordenanzas corresponde:','["Al Alcalde", "A la Junta de Gobierno Local, por delegación del Pleno", "Al Pleno, sin posibilidad de delegación"]'::jsonb,2,'Art. 22.2 d) y 22.4 LBRL','El art. 22.2 d) atribuye al Pleno la aprobación del reglamento orgánico y de las ordenanzas, y el art. 22.4 impide delegarla.',null),
('aux-ayto-mad:13-cb195c87a6','aux-ayto-mad',13,'En los municipios de gran población, la aprobación de los proyectos de ordenanzas y reglamentos, incluidos los orgánicos (salvo las normas del Pleno y sus comisiones), corresponde a:','["El Alcalde", "La Junta de Gobierno Local", "Las comisiones del Pleno"]'::jsonb,1,'Art. 127.1 a) LBRL','La Junta de Gobierno aprueba los proyectos y el Pleno aprueba y modifica las ordenanzas y reglamentos (art. 123.1 d).',null),
('aux-ayto-mad:13-6205d1723c','aux-ayto-mad',13,'En el Ayuntamiento de Madrid, la iniciativa para aprobar las normas de competencia del Pleno corresponde a:','["La Junta de Gobierno, en exclusiva", "El Alcalde, los Grupos políticos y los Concejales Presidentes de Distrito", "La Junta de Gobierno, los Grupos políticos y los Concejales, y un número de ciudadanos igual o superior al 10 % de los vecinos"]'::jsonb,2,'Art. 48.2 Ley 22/2006','El art. 48.2 reconoce la iniciativa de la Junta de Gobierno (proyectos), de los Grupos políticos y Concejales (proposiciones) y de al menos el 10 % de los vecinos.',null),
('aux-ayto-mad:13-a9350089e6','aux-ayto-mad',13,'Según la Ley 22/2006, queda excluida en todo caso de la iniciativa ciudadana para aprobar normas del Pleno:','["La materia urbanística", "La materia tributaria local", "La regulación de los distritos"]'::jsonb,1,'Art. 48.2 Ley 22/2006','El art. 48.2 excluye en todo caso de la iniciativa ciudadana la materia tributaria local.',null),
('aux-ayto-mad:13-69cdc1e1c6','aux-ayto-mad',13,'En el procedimiento de aprobación de los proyectos de normas del Pleno del Ayuntamiento de Madrid, si el proyecto afecta a los derechos e intereses legítimos de los ciudadanos, la Junta de Gobierno lo somete a alegaciones durante un plazo:','["No inferior a veinte días hábiles", "De quince días naturales", "No inferior a treinta días naturales"]'::jsonb,2,'Art. 48.3 a) Ley 22/2006','La Junta de Gobierno aprueba el proyecto inicial y lo somete a alegaciones durante un plazo no inferior a treinta días naturales.',null),
('aux-ayto-mad:13-36007793b1','aux-ayto-mad',13,'En el Ayuntamiento de Madrid, una vez examinadas las alegaciones, el proyecto definitivo de una norma del Pleno:','["Lo aprueba directamente el Alcalde mediante decreto, sin pasar por el Pleno", "Lo aprueba la Junta de Gobierno y lo remite al Pleno con las alegaciones y la memoria de su valoración", "Se publica en el BOCM y entra en vigor sin pasar por el Pleno"]'::jsonb,1,'Art. 48.3 b) Ley 22/2006','El proyecto definitivo lo aprueba la Junta de Gobierno y lo remite al Pleno, acompañado de todas las alegaciones y de la memoria que recoja su valoración.',null),
('aux-ayto-mad:13-7caabc95e0','aux-ayto-mad',13,'En el Ayuntamiento de Madrid, tras el dictamen de la Comisión competente, el Pleno aprueba la norma:','["En acto único", "En dos votaciones, inicial y definitiva", "Previa nueva información pública de treinta días"]'::jsonb,0,'Art. 48.3 d) Ley 22/2006','Según el art. 48.3 d), el Pleno, en acto único, aprobará la norma.',null),
('aux-ayto-mad:13-805bc93de3','aux-ayto-mad',13,'Las normas aprobadas por el Pleno del Ayuntamiento de Madrid se publican íntegramente en el Boletín Oficial de la Comunidad de Madrid y entran en vigor:','["Cuando transcurren quince días hábiles desde su publicación completa", "Al día siguiente de su publicación, salvo que la propia norma disponga otra cosa", "A los veinte días de su publicación"]'::jsonb,1,'Art. 48.3 e) Ley 22/2006','Según el art. 48.3 e), entran en vigor al día siguiente de su publicación en el BOCM, salvo que la norma disponga otra cosa, sin perjuicio de su publicación en el Boletín de la Ciudad de Madrid.',null),
('aux-ayto-mad:13-6f0336b4ed','aux-ayto-mad',13,'En el Ayuntamiento de Madrid, las proposiciones normativas de los Grupos políticos y de los Concejales se remiten en primer lugar:','["Al Alcalde, para que decida si las tramita y las somete a alegaciones", "A la Comisión correspondiente, acompañadas de una memoria, para su dictamen", "A la Junta de Gobierno, para que apruebe un proyecto inicial"]'::jsonb,1,'Art. 48.4 a) Ley 22/2006','La proposición, con una memoria de su autor, se remite a la Comisión correspondiente para su dictamen; después, si afecta a derechos de los ciudadanos, se somete a alegaciones.',null),
('aux-ayto-mad:13-12aa39f0d5','aux-ayto-mad',13,'En el Ayuntamiento de Madrid, toda proposición o enmienda que suponga aumento de los créditos o disminución de los ingresos del ejercicio en curso requiere para su tramitación:','["La conformidad de la Junta de Gobierno", "La mayoría absoluta del Pleno", "El informe favorable de la Intervención General"]'::jsonb,0,'Art. 48.6 Ley 22/2006','Según el art. 48.6, requiere la conformidad de la Junta de Gobierno para su tramitación.',null),
('aux-ayto-mad:13-b52fba95a9','aux-ayto-mad',13,'La aprobación de las normas del Pleno del Ayuntamiento de Madrid, además de publicarse, se comunica a:','["La Administración General del Estado y la Administración de la Comunidad de Madrid", "El Tribunal Superior de Justicia de Madrid", "La Federación Española de Municipios y Provincias y la Federación de Municipios de Madrid"]'::jsonb,0,'Art. 48.3 f) Ley 22/2006','El art. 48.3 f) exige comunicar la aprobación a la Administración General del Estado y a la de la Comunidad de Madrid.',null),
('aux-ayto-mad:13-eb980c5262','aux-ayto-mad',13,'El procedimiento del artículo 48 de la Ley 22/2006 se aplica a la elaboración y aprobación de ordenanzas, reglamentos y estatutos de organismos autónomos y entidades públicas empresariales, con excepción de:','["Las ordenanzas fiscales", "El planeamiento urbanístico, que se rige por su normativa específica", "Los reglamentos orgánicos"]'::jsonb,1,'Art. 48.1 Ley 22/2006','Según el art. 48.1, se exceptúa el planeamiento urbanístico, que se rige por su normativa específica.',null),
('aux-ayto-mad:13-7fbb7ddb19','aux-ayto-mad',13,'En el Ayuntamiento de Madrid, la iniciativa para aprobar el Presupuesto general corresponde:','["En exclusiva a la Junta de Gobierno", "Al Alcalde y a la Comisión de Hacienda", "A la Junta de Gobierno y a los Grupos políticos"]'::jsonb,0,'Art. 49.1 Ley 22/2006','El art. 49.1 atribuye la iniciativa en exclusiva a la Junta de Gobierno.',null),
('aux-ayto-mad:13-f6baac55c0','aux-ayto-mad',13,'El Proyecto de Presupuesto del Ayuntamiento de Madrid se expone al público, previo anuncio en el BOCM, durante:','["Quince días naturales", "Veinte días hábiles", "Treinta días naturales"]'::jsonb,0,'Art. 49.3 Ley 22/2006','Se expone al público quince días naturales, durante los cuales los interesados pueden examinarlo y presentar alegaciones.',null),
('aux-ayto-mad:13-53178602be','aux-ayto-mad',13,'El Proyecto de Presupuesto del Ayuntamiento de Madrid se remitirá al Pleno antes del:','["15 de octubre", "1 de diciembre", "1 de noviembre"]'::jsonb,2,'Art. 49.5 Ley 22/2006','Según el art. 49.5, se remitirá al Pleno antes del día 1 de noviembre.',null),
('aux-ayto-mad:13-fc6fdbbe23','aux-ayto-mad',13,'Las alegaciones al Proyecto de Presupuesto del Ayuntamiento de Madrid pueden fundarse, entre otros motivos, en:','["La falta de inversiones en el distrito del alegante respecto del ejercicio anterior", "La disconformidad con las prioridades políticas del gasto", "Omitir el crédito necesario para cumplir obligaciones exigibles al municipio"]'::jsonb,2,'Art. 49.4 Ley 22/2006','Solo caben alegaciones por omitir créditos para obligaciones exigibles o por manifiesta insuficiencia de los ingresos respecto de los gastos, o de estos respecto de las necesidades.',null),
('aux-ayto-mad:13-3eda72801f','aux-ayto-mad',13,'En el Ayuntamiento de Madrid, la aprobación y modificación de los reglamentos de naturaleza orgánica requiere:','["Mayoría absoluta del número legal de miembros del Pleno", "Mayoría simple del Pleno", "Dos tercios del Pleno"]'::jsonb,0,'Art. 11.2 Ley 22/2006','El art. 11.2 exige mayoría absoluta para los acuerdos del párrafo c) del art. 11.1 (reglamentos orgánicos).',null),
('aux-ayto-mad:13-58d870a040','aux-ayto-mad',13,'En el Ayuntamiento de Madrid, la aprobación de las ordenanzas y reglamentos municipales no orgánicos se adopta por el Pleno por:','["Mayoría simple de votos", "Mayoría absoluta del número legal de miembros", "Mayoría de tres quintos"]'::jsonb,0,'Art. 11.2 Ley 22/2006','El párrafo d) del art. 11.1 no está entre los que requieren mayoría absoluta, así que se aplica la mayoría simple.',null),
('aux-ayto-mad:13-34cf2f1078','aux-ayto-mad',13,'El Alcalde de Madrid puede dictar bandos para:','["Recordar y precisar los términos del cumplimiento de normas en vigor o hacer apelaciones a la población por circunstancias especiales", "Modificar ordenanzas en caso de urgencia sin pasar por el Pleno, dando cuenta después", "Aprobar normas que obliguen a los vecinos con rango de ordenanza"]'::jsonb,0,'Art. 14.3 e) Ley 22/2006','Los bandos sirven para recordar y precisar los términos de normas en vigor o para hacer apelaciones a la población con motivo de acontecimientos o circunstancias especiales; no crean normas nuevas.',null),
('aux-ayto-mad:13-be90fffc72','aux-ayto-mad',13,'Según la Ley 22/2006, las ordenanzas municipales de Madrid pueden establecer los casos concretos en los que pueda imponerse la multa coercitiva y graduar su cuantía, sin superar en ningún caso:','["6.000 euros", "1.500 euros y sus actualizaciones anuales conforme al IPC", "3.000 euros y sus actualizaciones anuales conforme al IPC"]'::jsonb,2,'Art. 52.2 Ley 22/2006','Según el art. 52.2, la ordenanza no podrá superar en ningún caso el límite máximo de 3.000 euros, actualizable con el IPC.',null),
('aux-ayto-mad:13-e178d25df7','aux-ayto-mad',13,'Según la Ley 22/2006, la Junta de Gobierno aprueba los proyectos de los estatutos de:','["Los organismos autónomos, entidades públicas empresariales, sociedades mercantiles y fundaciones", "Los grupos políticos municipales", "Las asociaciones vecinales inscritas en el registro municipal de entidades ciudadanas"]'::jsonb,0,'Art. 17.1 a) Ley 22/2006','La Junta de Gobierno aprueba los proyectos de esos estatutos; su aprobación definitiva corresponde al Pleno (art. 11.1 l).',null),
('aux-ayto-mad:14-31fab45bcc','aux-ayto-mad',14,'La Ley 9/2017 de Contratos del Sector Público califica como contratos de obras, concesión de obras, concesión de servicios, suministro y servicios a:','["Los contratos que regula en su sección de calificación de contratos", "Los contratos patrimoniales de compraventa y arrendamiento de bienes inmuebles", "Los convenios de colaboración entre Administraciones"]'::jsonb,0,'Art. 12.1 LCSP','Son los contratos que se califican según las normas de esa sección: obras, concesión de obras, concesión de servicios, suministro y servicios.',null),
('aux-ayto-mad:14-5b9afbe804','aux-ayto-mad',14,'El contrato de obras tiene por objeto, entre otros:','["La adquisición o el arrendamiento de bienes muebles necesarios para una obra", "La gestión de un servicio público, con o sin ejecución previa de una obra por el contratista", "La ejecución de una obra, aislada o conjuntamente con la redacción del proyecto"]'::jsonb,2,'Art. 13.1 LCSP','Tiene por objeto la ejecución de una obra, aislada o conjuntamente con la redacción del proyecto, o los trabajos del Anexo I.',null),
('aux-ayto-mad:14-a8f9418302','aux-ayto-mad',14,'Los contratos de suministro tienen por objeto:','["La adquisición o el arrendamiento de bienes inmuebles, con o sin opción de compra, y de derechos sobre ellos", "La prestación de una actividad o de un resultado distinto de una obra, a cambio de un precio cierto", "La adquisición, el arrendamiento financiero o el arrendamiento de productos o bienes muebles"]'::jsonb,2,'Art. 16.1 LCSP','Tienen por objeto la adquisición, el arrendamiento financiero o el arrendamiento, con o sin opción de compra, de productos o bienes muebles.',null),
('aux-ayto-mad:14-6a28ee4cad','aux-ayto-mad',14,'Los contratos de servicios son aquellos cuyo objeto son:','["La adquisición, el arrendamiento financiero o el arrendamiento, con o sin opción de compra, de productos o bienes muebles", "Prestaciones de hacer consistentes en una actividad o dirigidas a un resultado distinto de una obra o suministro", "La adquisición o el arrendamiento de bienes inmuebles, valores negociables o derechos de propiedad incorporal sobre ellos"]'::jsonb,1,'Art. 17 LCSP','Son prestaciones de hacer consistentes en el desarrollo de una actividad o dirigidas a un resultado distinto de una obra o un suministro.',null),
('aux-ayto-mad:14-e5ca30945a','aux-ayto-mad',14,'Los contratos de suministros y servicios de prestación sucesiva tienen un plazo máximo de duración de:','["Cuatro años, más dos de posibles prórrogas anuales", "Diez años, incluidas las posibles prórrogas", "Cinco años, incluidas las posibles prórrogas"]'::jsonb,2,'Art. 29.4 LCSP','Cinco años, incluyendo las posibles prórrogas.',null),
('aux-ayto-mad:14-c1b7acaeef','aux-ayto-mad',14,'Los contratos menores:','["No pueden durar más de un año ni ser objeto de prórroga", "No pueden durar más de un año, pero pueden prorrogarse una vez", "Pueden durar hasta dos años, sin posibilidad de prórroga"]'::jsonb,0,'Art. 29.8 LCSP','No pueden tener una duración superior a un año ni ser objeto de prórroga.',null),
('aux-ayto-mad:14-bcc383b770','aux-ayto-mad',14,'El recurso especial en materia de contratación tiene carácter:','["Obligatorio", "Previo al recurso de alzada", "Potestativo"]'::jsonb,2,'Art. 44.7 LCSP','Tiene carácter potestativo y es gratuito para los recurrentes.',null),
('aux-ayto-mad:14-9aeab4399c','aux-ayto-mad',14,'El plazo para interponer el recurso especial en materia de contratación es de:','["Dos meses", "Quince días hábiles", "Diez días naturales"]'::jsonb,1,'Art. 50.1 LCSP','El plazo es de quince días hábiles.',null),
('aux-ayto-mad:14-072e9c7f51','aux-ayto-mad',14,'El perfil de contratante se difunde:','["Exclusivamente a través de Internet", "En la prensa nacional", "En el BOE"]'::jsonb,0,'Art. 63 LCSP','Los órganos de contratación difunden exclusivamente a través de Internet su perfil de contratante.',null),
('aux-ayto-mad:14-f499ddb02d','aux-ayto-mad',14,'Pueden contratar con el sector público las personas naturales o jurídicas que:','["Tengan plena capacidad de obrar, no estén incursas en prohibición de contratar y acrediten su solvencia", "Tengan plena capacidad de obrar y estén inscritas en el registro mercantil desde hace al menos cinco años", "Tengan domicilio social en España y plena capacidad de obrar, estén inscritas en el Registro Mercantil y acrediten su solvencia"]'::jsonb,0,'Art. 65.1 LCSP','Se exige plena capacidad de obrar, no estar incursas en prohibición de contratar y acreditar la solvencia (o clasificación cuando se exija).',null),
('aux-ayto-mad:14-28de4fe050','aux-ayto-mad',14,'La garantía provisional, cuando se exige, no puede ser superior al:','["2 % del valor estimado del contrato, IVA excluido", "10 % del presupuesto base de licitación, IVA incluido", "3 % del presupuesto base de licitación, IVA excluido"]'::jsonb,2,'Art. 106.2 LCSP','No puede superar el 3 % del presupuesto base de licitación, excluido el IVA.',null),
('aux-ayto-mad:14-548096cdfd','aux-ayto-mad',14,'La garantía definitiva es, con carácter general, del:','["2 % del valor estimado", "5 % del precio final ofertado, IVA excluido", "10 % del precio con IVA"]'::jsonb,1,'Art. 107.1 LCSP','Es del 5 % del precio final ofertado, excluido el IVA.',null),
('aux-ayto-mad:14-0f6073ce81','aux-ayto-mad',14,'Son contratos menores de obras los de valor estimado inferior a:','["40.000 euros", "15.000 euros", "100.000 euros"]'::jsonb,0,'Art. 118.1 LCSP','Obras: valor estimado inferior a 40.000 €. Suministro o servicios: inferior a 15.000 €.',null),
('aux-ayto-mad:14-baaecdf797','aux-ayto-mad',14,'Son contratos menores de suministro o de servicios los de valor estimado inferior a:','["6.000 euros", "15.000 euros", "30.000 euros"]'::jsonb,1,'Art. 118.1 LCSP','Suministro o servicios: inferior a 15.000 €. Obras: inferior a 40.000 €.',null),
('aux-ayto-mad:14-cadd0d5611','aux-ayto-mad',14,'Con carácter ordinario, la adjudicación se realiza por:','["El diálogo competitivo, utilizando como único criterio el precio más bajo ofertado", "El procedimiento negociado con publicidad, con pluralidad de criterios basados en la mejor relación calidad-precio", "El procedimiento abierto o el restringido, con pluralidad de criterios basados en la mejor relación calidad-precio"]'::jsonb,2,'Art. 131.2 LCSP','Ordinariamente por procedimiento abierto o restringido, con pluralidad de criterios basados en la mejor relación calidad-precio.',null),
('aux-ayto-mad:14-bffd5c4ecb','aux-ayto-mad',14,'Los contratos se adjudican utilizando una pluralidad de criterios en base a:','["La menor huella de carbono", "La mayor experiencia acreditada de la empresa", "La mejor relación calidad-precio"]'::jsonb,2,'Art. 145.1 LCSP','Se adjudican con pluralidad de criterios en base a la mejor relación calidad-precio.',null),
('aux-ayto-mad:14-32b4e59f03','aux-ayto-mad',14,'Si el contrato no es susceptible de recurso especial, la formalización debe hacerse:','["No más tarde de los quince días naturales siguientes a la publicación de la adjudicación", "No más tarde de un mes desde la notificación de la adjudicación a todos los licitadores participantes", "No más tarde de los quince días hábiles siguientes a la notificación de la adjudicación"]'::jsonb,2,'Art. 153.3 LCSP','No más tarde de los quince días hábiles siguientes a la notificación de la adjudicación.',null),
('aux-ayto-mad:14-e05f4f0291','aux-ayto-mad',14,'En el procedimiento abierto:','["Solo pueden presentar proposición las empresas inscritas en el Registro Oficial de Licitadores", "Solo pueden presentar proposición las empresas invitadas por el órgano de contratación", "Todo empresario interesado puede presentar una proposición, excluida toda negociación"]'::jsonb,2,'Art. 156.1 LCSP','Todo empresario interesado puede presentar una proposición, quedando excluida toda negociación.',null),
('aux-ayto-mad:14-4cd80b5eda','aux-ayto-mad',14,'En el procedimiento restringido pueden presentar proposiciones:','["Solo los empresarios que, a su solicitud y en atención a su solvencia, sean seleccionados", "Solo los empresarios inscritos en el Registro Oficial de Licitadores y Empresas Clasificadas", "Todos los empresarios interesados, excluida toda negociación de los términos del contrato"]'::jsonb,0,'Art. 160.2 LCSP','Cualquier empresa puede solicitar participar, pero solo presentan proposiciones las seleccionadas.',null),
('aux-ayto-mad:14-3e469cf2bd','aux-ayto-mad',14,'En el procedimiento restringido, el número mínimo de empresarios invitados no puede ser inferior a:','["Diez", "Cinco", "Dos"]'::jsonb,1,'Art. 162.2 LCSP','No puede ser inferior a cinco.',null),
('aux-ayto-mad:14-305c6f66a2','aux-ayto-mad',14,'En los procedimientos con negociación, la adjudicación recae en el licitador elegido:','["Por sorteo público entre los candidatos que hayan acreditado la solvencia exigida en los pliegos", "Atendiendo únicamente al precio más bajo, sin negociación", "Tras negociar las condiciones del contrato con uno o varios candidatos"]'::jsonb,2,'Art. 166.1 LCSP','Recae en el licitador justificadamente elegido tras negociar las condiciones con uno o varios candidatos.',null),
('aux-ayto-mad:14-46eda3f172','aux-ayto-mad',14,'En la tramitación urgente del expediente, el plazo de inicio de la ejecución del contrato no podrá exceder de:','["Un mes, contado desde la formalización", "Una semana, contada desde la formalización", "Tres meses, contados desde la adjudicación"]'::jsonb,0,'Art. 119.2 c) LCSP','La urgencia reduce además a la mitad los plazos de licitación, adjudicación y formalización.',null),
('aux-ayto-mad:14-372e0851e8','aux-ayto-mad',14,'El orden jurisdiccional contencioso-administrativo es competente para resolver las cuestiones relativas a:','["Los despidos del personal del contratista y las reclamaciones de los subcontratistas por los pagos pendientes", "La preparación, adjudicación, efectos, modificación y extinción de los contratos administrativos", "Los efectos y extinción de los contratos privados de los poderes adjudicadores que no sean Administraciones"]'::jsonb,1,'Art. 27.1 a) LCSP','El orden civil conoce de los efectos y extinción de los contratos privados.',null),
('aux-ayto-mad:14-2b87ba324b','aux-ayto-mad',14,'Es causa de resolución del contrato la demora en el cumplimiento de los plazos que suponga un retraso injustificado superior a:','["Un mes, en todo caso", "Un quinto del plazo de duración inicial del contrato, sin incluir las prórrogas", "Un tercio del plazo de duración inicial del contrato, incluidas las prórrogas"]'::jsonb,2,'Art. 211.1 d) LCSP','Es una de las causas de resolución del art. 211.',null),
('aux-ayto-mad:14-f7ac8aa247','aux-ayto-mad',14,'Un encargo a un medio propio personificado que cumpla los requisitos legales:','["Es un contrato menor, si no supera los 15.000 euros", "Es un contrato de servicios no armonizado", "No tendrá la consideración de contrato"]'::jsonb,2,'Art. 32.1 LCSP','Requiere, entre otros, que más del 80 % de la actividad del ente se realice para el poder adjudicador que lo controla.',null),
('aux-ayto-mad:14-9f3e132265','aux-ayto-mad',14,'En el procedimiento de licitación con negociación, cuando se limite el número de candidatos, el mínimo será de:','["Cinco", "Tres", "Diez"]'::jsonb,1,'Art. 169.2 LCSP','El número mínimo de invitados es tres.',null),
('aux-ayto-mad:14-1766f47735','aux-ayto-mad',14,'La garantía definitiva puede constituirse, entre otras formas:','["Mediante pagaré personal del contratista o mediante prenda sobre maquinaria, sin necesidad de aval", "En efectivo o valores, mediante aval o mediante contrato de seguro de caución", "Mediante hipoteca sobre bienes inmuebles del contratista o de un tercero, o mediante prenda sobre sus bienes muebles"]'::jsonb,1,'Art. 108.1 LCSP','Son las formas de constitución de la garantía.',null),
('aux-ayto-mad:14-c57d7b375f','aux-ayto-mad',14,'En el ámbito de la AGE, el conocimiento y resolución de los recursos especiales en materia de contratación corresponde a:','["El Tribunal Administrativo Central de Recursos Contractuales", "La Audiencia Nacional", "El Tribunal de Cuentas"]'::jsonb,0,'Art. 45.1 LCSP','Las CCAA pueden crear órganos propios o atribuir la competencia al Tribunal estatal por convenio.',null),
('aux-ayto-mad:14-2fac797dd9','aux-ayto-mad',14,'En la AGE, el anuncio de licitación se publica en el perfil de contratante y, además:','["En el BOE", "En un periódico de tirada nacional", "En el tablón de anuncios del Ministerio exclusivamente"]'::jsonb,0,'Art. 135.1 LCSP','Si el contrato está sujeto a regulación armonizada, también en el DOUE.',null),
('aux-ayto-mad:14-385bc25383','aux-ayto-mad',14,'La información publicada en el perfil de contratante debe mantenerse durante un periodo de tiempo de, al menos:','["10 años", "5 años", "6 meses"]'::jsonb,1,'Art. 63.1 LCSP','El acceso al perfil es libre y se difunde exclusivamente a través de Internet.',null),
('aux-ayto-mad:14-8a1e24739d','aux-ayto-mad',14,'Con carácter general, la duración de la prohibición de contratar no podrá exceder de:','["Diez años", "Cinco años", "Tres años"]'::jsonb,2,'Art. 72.6 LCSP','Salvo que la sentencia o resolución firme establezca otro plazo.',null),
('aux-ayto-mad:14-89d8a44e84','aux-ayto-mad',14,'Según el art. 2.1 LCSP, un contrato es oneroso cuando:','["Se paga siempre en metálico", "Supera los 15.000 euros de valor estimado, en el caso de los contratos de servicios y suministros", "El contratista obtiene algún tipo de beneficio económico, directo o indirecto"]'::jsonb,2,'Art. 2.1 LCSP','La ley se aplica a los contratos onerosos celebrados por las entidades del sector público.',null),
('aux-ayto-mad:14-e072d61a69','aux-ayto-mad',14,'El valor estimado de los contratos de obras, suministros y servicios se calcula:','["Sin incluir las posibles prórrogas", "Por el importe total pagadero, sin incluir el IVA", "Por el importe total pagadero, incluido el IVA"]'::jsonb,1,'Art. 101.1 a) LCSP','Se tienen en cuenta las eventuales prórrogas y modificaciones previstas.',null),
('aux-ayto-mad:14-6e9770b157','aux-ayto-mad',14,'La publicación de la información de los contratos menores en el perfil de contratante se realizará:','["Diariamente", "Solo si superan 15.000 euros", "Al menos trimestralmente"]'::jsonb,2,'Art. 63.4 LCSP','Quedan exceptuados los de valor inferior a 5.000 euros pagados mediante anticipo de caja fija o similar.',null),
('aux-ayto-mad:14-627839f0fd','aux-ayto-mad',14,'Los contratos podrán modificarse durante su vigencia, cuando así se haya advertido expresamente en el pliego, hasta un máximo del:','["100 % del precio inicial", "20 % del precio inicial", "50 % del precio inicial"]'::jsonb,1,'Art. 204.1 LCSP','Para las modificaciones no previstas en el pliego rige el art. 205.',null),
('aux-ayto-mad:14-3fcc1fb635','aux-ayto-mad',14,'En la tramitación de emergencia:','["No puede contratarse", "Hay que tramitar siempre un procedimiento abierto con plazos reducidos a la mitad, como en la tramitación urgente", "El órgano de contratación puede ordenar la ejecución sin obligación de tramitar expediente de contratación"]'::jsonb,2,'Art. 120.1 a) LCSP','El inicio de la ejecución no puede exceder de un mes desde el acuerdo.',null),
('aux-ayto-mad:14-9304c162a9','aux-ayto-mad',14,'Cuando haya varios criterios de adjudicación, el plazo máximo para adjudicar será de:','["Un mes desde la apertura de las proposiciones, salvo que el pliego indique otro", "Quince días desde la apertura de las proposiciones, sin que el pliego pueda fijar otro", "Dos meses desde la apertura de las proposiciones, salvo que el pliego indique otro"]'::jsonb,2,'Art. 158.2 LCSP','Con un único criterio (el precio), el plazo es de quince días.',null),
('aux-ayto-mad:14-94c013d7e4','aux-ayto-mad',14,'Los contratos de suministro de la AGE y sus organismos están sujetos a regulación armonizada cuando su valor estimado sea igual o superior a:','["750.000 euros", "5.404.000 euros", "140.000 euros"]'::jsonb,2,'Art. 21.1 LCSP','Para otras entidades el umbral es de 216.000 euros.',null),
('aux-ayto-mad:14-9e71b92917','aux-ayto-mad',14,'Las concesiones de obras y de servicios que comprendan la ejecución de obras tendrán un plazo de duración máximo de:','["40 años", "10 años", "25 años"]'::jsonb,0,'Art. 29.6 a) LCSP','Las concesiones de servicios sin obras no sanitarios, 25 años; los sanitarios del art. 29.6 c), 10 años.',null),
('aux-ayto-mad:14-d42b76d1f0','aux-ayto-mad',14,'Para que el contratista pueda ceder sus derechos y obligaciones a un tercero, es requisito que el cedente tenga ejecutado al menos:','["La totalidad de la prestación", "Un 20 % del importe del contrato", "Un 50 % del importe del contrato o de su duración"]'::jsonb,1,'Art. 214.2 b) LCSP','Además, se necesita autorización previa del órgano de contratación.',null),
('aux-ayto-mad:14-d669e1529e','aux-ayto-mad',14,'La duración de un acuerdo marco no podrá exceder, salvo casos excepcionales justificados, de:','["Dos años", "Diez años", "Cuatro años"]'::jsonb,2,'Art. 219.2 LCSP','Es la duración máxima ordinaria de los acuerdos marco.',null),
('aux-ayto-mad:14-2f9837ae70','aux-ayto-mad',14,'La prórroga de un contrato será obligatoria para el empresario siempre que su preaviso se produzca, al menos, con una antelación de:','["Dos meses respecto de la finalización del plazo de duración del contrato", "Seis meses respecto de la finalización del plazo de duración del contrato", "Quince días respecto de la finalización del plazo de duración del contrato"]'::jsonb,0,'Art. 29.2 LCSP','La prórroga no puede producirse por consentimiento tácito de las partes.',null),
('aux-ayto-mad:14-c2a3020292','aux-ayto-mad',14,'Los contratos de servicios sociales y otros del anexo IV están sujetos a regulación armonizada cuando su valor estimado sea igual o superior a:','["750.000 euros", "216.000 euros", "5.404.000 euros"]'::jsonb,0,'Art. 22.1 LCSP','Es un umbral específico para los servicios del anexo IV.',null),
('aux-ayto-mad:14-97fd9f080c','aux-ayto-mad',14,'Tanto en la concesión de obras como en la de servicios es necesaria la transferencia al concesionario de:','["El riesgo operacional", "La potestad sancionadora", "La titularidad del servicio público"]'::jsonb,0,'Arts. 14.4 y 15.2 LCSP','El concesionario asume el riesgo operacional en la explotación.',null),
('aux-ayto-mad:14-8849160d80','aux-ayto-mad',14,'La inscripción en el Registro Oficial de Licitadores y Empresas Clasificadas del Sector Público acredita, salvo prueba en contrario:','["Las condiciones de aptitud del empresario frente a todos los órganos de contratación del sector público", "Las condiciones de aptitud del empresario solo frente a los órganos de contratación de la Administración General del Estado", "Las condiciones de aptitud del empresario, pero solo frente a los órganos de contratación de la Administración General del Estado"]'::jsonb,0,'Art. 96.1 LCSP','Acredita personalidad, capacidad, representación, solvencia y ausencia de prohibiciones.',null),
('aux-ayto-mad:14-f5dd1c5b82','aux-ayto-mad',14,'Las entidades del sector público no podrán celebrar otros contratos que:','["Aquellos que sean necesarios para el cumplimiento y realización de sus fines institucionales", "Los que demanden los ciudadanos a través de los procesos de participación ciudadana y presupuestos participativos", "Los que superen 40.000 euros y estén previstos en el plan anual de contratación aprobado por el órgano"]'::jsonb,0,'Art. 28.1 LCSP','Principio de necesidad e idoneidad del contrato.',null),
('aux-ayto-mad:14-eaeae431fa','aux-ayto-mad',14,'Según el art. 197 LCSP, la ejecución del contrato se realizará:','["A riesgo compartido al 50 %", "A riesgo del responsable del contrato", "A riesgo y ventura del contratista"]'::jsonb,2,'Art. 197 LCSP','Sin perjuicio de lo previsto para el contrato de obras en el art. 239.',null),
('aux-ayto-mad:14-f650fc70da','aux-ayto-mad',14,'Están sujetos a regulación armonizada los contratos de obras y concesiones de valor estimado igual o superior a:','["5.404.000 euros", "1.000.000 euros", "216.000 euros"]'::jsonb,0,'Art. 20.1 LCSP','Umbral vigente según el texto consolidado del BOE (los umbrales se revisan periódicamente).',null),
('aux-ayto-mad:14-414b778078','aux-ayto-mad',14,'Para que un ente sea medio propio personificado, más del ___ de sus actividades deben llevarse a cabo en el ejercicio de los cometidos que le confíe el poder adjudicador:','["50 %", "100 %", "80 %"]'::jsonb,2,'Art. 32.2 b) LCSP','Más del 80 % de su actividad debe dirigirse al poder adjudicador que lo controla.',null),
('aux-ayto-mad:14-21f285ca09','aux-ayto-mad',14,'En la concesión de obras, la contraprestación a favor del concesionario consiste en:','["Un precio fijo pagado por adelantado por la Administración, sin derecho a explotar la obra", "Una subvención anual a cargo de la Administración concedente, sin derecho a explotar la obra", "El derecho a explotar la obra, o dicho derecho acompañado del de percibir un precio"]'::jsonb,2,'Art. 14.1 LCSP','La concesión implica la transferencia del riesgo operacional al concesionario.',null),
('aux-ayto-mad:14-a76caa297f','aux-ayto-mad',14,'Si transcurren dos meses desde la interposición del recurso especial sin que se notifique su resolución:','["Se entiende estimado por silencio administrativo y la adjudicación queda sin efecto, debiendo el órgano de contratación adjudicar al siguiente licitador", "El contrato se anula", "El interesado podrá considerarlo desestimado a efectos de interponer recurso contencioso-administrativo"]'::jsonb,2,'Art. 57.5 LCSP','El silencio en el recurso especial es desestimatorio.',null),
('aux-ayto-mad:14-e404a20dad','aux-ayto-mad',14,'Si el licitador propuesto no cumplimenta adecuadamente el requerimiento de documentación en plazo, se le exigirá una penalidad del:','["5 % del presupuesto base de licitación, IVA incluido", "3 % del presupuesto base de licitación, IVA excluido", "10 % del precio de adjudicación"]'::jsonb,1,'Art. 150.2 LCSP','Se entiende que ha retirado su oferta.',null),
('aux-ayto-mad:14-57db65a88f','aux-ayto-mad',14,'Los expedientes de resolución contractual deberán ser instruidos y resueltos en el plazo máximo de:','["Seis meses", "Ocho meses", "Tres meses"]'::jsonb,1,'Art. 212.8 LCSP','Plazo máximo de ocho meses.',null)
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('aux-ayto-mad:14-0bbad2fa21','aux-ayto-mad',14,'Los órganos de contratación designarán un responsable del contrato al que corresponderá:','["Adjudicar el contrato, fijar el precio de licitación y resolver el recurso especial en materia de contratación que interpongan los licitadores excluidos", "Fijar el precio del contrato y resolver las reclamaciones de los licitadores sobre la adjudicación, previo informe de la mesa de contratación y de los servicios jurídicos", "Supervisar su ejecución y adoptar las decisiones y dictar las instrucciones necesarias para asegurar la correcta realización de la prestación"]'::jsonb,2,'Art. 62.1 LCSP','Su designación es obligatoria.',null),
('aux-ayto-mad:14-65252753c2','aux-ayto-mad',14,'Las penalidades por demora en la ejecución, salvo que el pliego disponga otras, serán diarias en la proporción de:','["1 euro por cada 100 euros", "0,60 euros por cada 1.000 euros del precio del contrato, IVA excluido", "0,10 euros por cada 1.000 euros"]'::jsonb,1,'Art. 193.3 LCSP','Cada vez que las penalidades alcancen un múltiplo del 5 % del precio se puede resolver el contrato.',null),
('aux-ayto-mad:14-1fc451353b','aux-ayto-mad',14,'Si se interpone recurso especial contra la adjudicación, como regla general:','["La adjudicación se anula automáticamente y se retrotrae el procedimiento", "Quedará en suspenso la tramitación del procedimiento", "El contrato se formaliza igualmente"]'::jsonb,1,'Art. 53 LCSP','Salvo en contratos basados en acuerdos marco o sistemas dinámicos de adquisición.',null),
('aux-ayto-mad:14-6f9c1291a0','aux-ayto-mad',14,'El procedimiento abierto simplificado puede utilizarse en contratos de obras de valor estimado igual o inferior a:','["2.000.000 de euros", "500.000 euros, IVA excluido", "100.000 euros, IVA excluido"]'::jsonb,0,'Art. 159.1 LCSP','Para suministros y servicios hay un umbral inferior.',null),
('aux-ayto-mad:14-8bfef88ea2','aux-ayto-mad',14,'Contra la resolución del recurso especial en materia de contratación:','["Cabe recurso potestativo de reposición ante el mismo tribunal administrativo, y después recurso contencioso-administrativo", "No cabe ningún recurso", "Solo procederá la interposición de recurso contencioso-administrativo"]'::jsonb,2,'Art. 59.1 LCSP','La resolución es directamente ejecutiva.',null),
('aux-ayto-mad:14-3284c95a2e','aux-ayto-mad',14,'En los contratos de servicios del anexo IV y en los que tengan por objeto prestaciones de carácter intelectual, los criterios relacionados con la calidad deben representar, al menos:','["El 30 % de la puntuación asignable", "El 75 % de la puntuación asignable", "El 51 % de la puntuación asignable"]'::jsonb,2,'Art. 145.4 LCSP','Garantiza que la calidad pese más que el precio en esos contratos.',null),
('aux-ayto-mad:14-a9c85eb9fc','aux-ayto-mad',14,'NO procede el recurso especial en materia de contratación respecto de los procedimientos de adjudicación que se sigan:','["Por el trámite de emergencia", "Mediante procedimiento restringido", "Mediante procedimiento abierto"]'::jsonb,0,'Art. 44.4 LCSP','No cabe recurso especial en la tramitación de emergencia.',null),
('aux-ayto-mad:14-05a9b8d7ef','aux-ayto-mad',14,'Si la demora en el pago por la Administración fuese superior a seis meses, el contratista tendrá derecho a:','["Resolver el contrato y al resarcimiento de los perjuicios", "Una prórroga del contrato por un plazo igual al de la demora", "Ceder el contrato a un tercero sin necesidad de autorización del órgano de contratación"]'::jsonb,0,'Art. 198.6 LCSP','Si la demora supera cuatro meses puede suspender el cumplimiento del contrato.',null),
('aux-ayto-mad:14-234f1759d2','aux-ayto-mad',14,'La garantía complementaria que puede exigirse en casos especiales puede ser de hasta un 5 %, de modo que la garantía total pueda alcanzar:','["Un 10 % del precio del contrato", "Un 15 % del precio del contrato", "Un 8 % del precio del contrato, IVA incluido"]'::jsonb,0,'Art. 107.2 LCSP','La garantía definitiva ordinaria es del 5 % y la complementaria hasta otro 5 %.',null),
('aux-ayto-mad:14-0aa1c2c176','aux-ayto-mad',14,'La Administración tiene la obligación de abonar el precio dentro de los ___ siguientes a la fecha de aprobación de las certificaciones o documentos de conformidad:','["Quince días", "Treinta días", "Sesenta días"]'::jsonb,1,'Art. 198.4 LCSP','Si se retrasa, debe abonar intereses de demora y la indemnización por costes de cobro.',null),
('aux-ayto-mad:14-0285a01186','aux-ayto-mad',14,'Contra las actuaciones susceptibles de recurso especial en materia de contratación:','["Cabe recurso extraordinario de revisión previo, en los supuestos del art. 125 de la Ley 39/2015", "Cabe además recurso de alzada ante el titular del departamento ministerial", "No procederá la interposición de recursos administrativos ordinarios"]'::jsonb,2,'Art. 44.5 LCSP','El recurso especial sustituye a los recursos ordinarios.',null),
('aux-ayto-mad:14-0449399d8b','aux-ayto-mad',14,'¿Puede prorrogarse un contrato por consentimiento tácito de las partes?','["Sí, si es un contrato menor", "No, en ningún caso", "Sí, si lo autoriza el responsable del contrato"]'::jsonb,1,'Art. 29.2 LCSP','La prórroga la acuerda el órgano de contratación y nunca es tácita.',null),
('aux-ayto-mad:14-8e9640cb18','aux-ayto-mad',14,'Es una prohibición de contratar del art. 71.1:','["Haber sido adjudicatario de otro contrato con la misma Administración en los últimos tres años", "Haber sido condenado mediante sentencia firme por determinados delitos, como cohecho o prevaricación", "Tener menos de diez trabajadores"]'::jsonb,1,'Art. 71.1 a) LCSP','Otras: sanciones firmes, concurso, incumplimiento de obligaciones tributarias o de Seguridad Social…',null),
('aux-ayto-mad:14-4020ebec9f','aux-ayto-mad',14,'Cada una de las penalidades no podrá ser superior al ___ del precio del contrato, ni el total superar el 50 %:','["20 %", "30 %", "10 %"]'::jsonb,2,'Art. 192.1 LCSP','Límites de las penalidades contractuales.',null),
('aux-ayto-mad:14-01e1506297','aux-ayto-mad',14,'En los contratos de las Administraciones Públicas, el pago aplazado del precio:','["Es obligatorio en los contratos de obras de valor estimado superior a 5.000.000 de euros", "Está prohibido, salvo excepciones como el arrendamiento financiero", "Solo se permite en contratos menores y en los de suministro de bienes"]'::jsonb,1,'Art. 102.8 LCSP','Se prohíbe salvo los supuestos legalmente previstos.',null),
('aux-ayto-mad:15-bb6024bb72','aux-ayto-mad',15,'Según el art. 8.2 del TREBEP, los empleados públicos se clasifican en:','["Funcionarios de carrera, personal laboral, personal eventual y personal directivo", "Funcionarios de carrera, funcionarios interinos, personal laboral, personal eventual y personal directivo profesional", "Funcionarios de carrera, funcionarios interinos, personal laboral y personal eventual"]'::jsonb,2,'Art. 8.2 TREBEP','Se clasifican en funcionarios de carrera, funcionarios interinos, personal laboral (fijo, por tiempo indefinido o temporal) y personal eventual.',null),
('aux-ayto-mad:15-ac26f09f0d','aux-ayto-mad',15,'Las funciones que implican participación directa o indirecta en el ejercicio de potestades públicas corresponden:','["Exclusivamente a los funcionarios de carrera, nunca a los interinos", "Al personal laboral fijo y a los funcionarios de carrera, en los términos que establezca la ley de cada Administración", "Exclusivamente a los funcionarios públicos"]'::jsonb,2,'Art. 9.2 TREBEP','Corresponden exclusivamente a los funcionarios públicos, en los términos que establezca la ley de desarrollo de cada Administración.',null),
('aux-ayto-mad:15-cefce8a58c','aux-ayto-mad',15,'Un funcionario interino nombrado para cubrir una plaza vacante puede ocuparla como máximo:','["Cinco años", "Un año", "Tres años"]'::jsonb,2,'Art. 10.1 a) TREBEP','Las plazas vacantes pueden cubrirse por interinos cuando no sea posible su cobertura por funcionarios de carrera, por un máximo de tres años.',null),
('aux-ayto-mad:15-7d6528ecd2','aux-ayto-mad',15,'El nombramiento de interinos por exceso o acumulación de tareas tiene un plazo máximo de:','["Seis meses dentro de un periodo de doce", "Nueve meses dentro de un periodo de dieciocho", "Doce meses dentro de un periodo de veinticuatro"]'::jsonb,1,'Art. 10.1 d) TREBEP','El plazo máximo es de nueve meses dentro de un periodo de dieciocho meses.',null),
('aux-ayto-mad:15-ff4f6cbc03','aux-ayto-mad',15,'El nombramiento de interinos para ejecutar programas de carácter temporal no puede superar:','["Dos años, ampliable hasta seis meses más por las leyes de Función Pública que se dicten en desarrollo del Estatuto", "Cuatro años, ampliable hasta doce meses más por las leyes de Función Pública", "Tres años, ampliable hasta doce meses más por las leyes de Función Pública"]'::jsonb,2,'Art. 10.1 c) TREBEP','No puede ser superior a tres años, ampliable hasta doce meses más por las leyes de Función Pública de cada Administración.',null),
('aux-ayto-mad:15-bca3e78100','aux-ayto-mad',15,'El personal eventual realiza funciones:','["De carácter técnico permanente, previstas en la relación de puestos de trabajo de cada Administración", "De confianza, pero que implican el ejercicio de potestades públicas", "Expresamente calificadas como de confianza o asesoramiento especial"]'::jsonb,2,'Art. 12.1 TREBEP','El personal eventual solo realiza funciones expresamente calificadas como de confianza o asesoramiento especial.',null),
('aux-ayto-mad:15-3d268ef525','aux-ayto-mad',15,'Haber sido personal eventual, ¿puede constituir mérito para el acceso a la función pública?','["Solo en la promoción interna", "Sí, si se prestaron servicios más de un año", "No"]'::jsonb,2,'Art. 12.4 TREBEP','La condición de personal eventual no puede constituir mérito para el acceso a la Función Pública o para la promoción interna.',null),
('aux-ayto-mad:15-9283b2f482','aux-ayto-mad',15,'¿Cuál de estos es un derecho individual que se ejerce de forma colectiva?','["La inamovilidad en la condición de funcionario", "El ejercicio de la huelga", "Las vacaciones"]'::jsonb,1,'Art. 15 TREBEP','Son derechos individuales ejercidos colectivamente la libertad sindical, la negociación colectiva y participación, la huelga, el planteamiento de conflictos colectivos y la reunión.',null),
('aux-ayto-mad:15-9bf00b3be2','aux-ayto-mad',15,'¿Cuántos días de permiso por asuntos particulares tienen los funcionarios al año?','["Ocho días", "Cuatro días", "Seis días"]'::jsonb,2,'Art. 48 k) TREBEP','Por asuntos particulares, seis días al año.',null),
('aux-ayto-mad:15-fe71ef6380','aux-ayto-mad',15,'¿Cuántos días de permiso corresponden por matrimonio o registro de pareja de hecho?','["Quince días", "Diez días", "Veinte días"]'::jsonb,0,'Art. 48 l) TREBEP','Quince días por matrimonio o registro o constitución formalizada por documento público de pareja de hecho.',null),
('aux-ayto-mad:15-d95723d22e','aux-ayto-mad',15,'¿Qué duración tiene el permiso por nacimiento para la madre biológica según el TREBEP vigente?','["Diecinueve semanas", "Dieciséis semanas", "Veinticuatro semanas"]'::jsonb,0,'Art. 49 a) TREBEP','Tras la última reforma son diecinueve semanas (treinta y dos en caso de familia monoparental). Muchos tests antiguos siguen diciendo dieciséis.',null),
('aux-ayto-mad:15-eee5d38d49','aux-ayto-mad',15,'¿Cuántos días de vacaciones retribuidas tienen los funcionarios por año completo de servicio?','["Veinticinco días hábiles", "Veintidós días hábiles", "Treinta días naturales"]'::jsonb,1,'Art. 50.1 TREBEP','Veintidós días hábiles, o los que correspondan proporcionalmente si el tiempo de servicio fue menor.',null),
('aux-ayto-mad:15-45aa1a79e8','aux-ayto-mad',15,'¿Qué edad mínima se exige para participar en los procesos selectivos?','["Diecisiete años", "Veintiún años", "Dieciséis años"]'::jsonb,2,'Art. 56.1 c) TREBEP','Tener cumplidos dieciséis años y no exceder, en su caso, la edad máxima de jubilación forzosa.',null),
('aux-ayto-mad:15-086abd1839','aux-ayto-mad',15,'¿Cuáles son los sistemas selectivos de los funcionarios de carrera?','["Oposición, concurso y entrevista personal, que pueden utilizarse indistintamente según lo que decida cada convocatoria", "Oposición y concurso-oposición; el concurso, con carácter ordinario y sin necesidad de previsión en una ley", "Oposición y concurso-oposición; el concurso, solo con carácter excepcional y en virtud de ley"]'::jsonb,2,'Art. 61.6 TREBEP','Son la oposición y el concurso-oposición. El concurso de valoración de méritos solo cabe excepcionalmente y en virtud de ley.',null),
('aux-ayto-mad:15-33379aea05','aux-ayto-mad',15,'¿Cuál de los siguientes NO es un requisito para adquirir la condición de funcionario de carrera?','["Superar el proceso selectivo", "Haber prestado servicios previos como interino", "Tomar posesión dentro del plazo establecido"]'::jsonb,1,'Art. 62.1 TREBEP','Se requiere superar el proceso selectivo, el nombramiento publicado en el diario oficial, el acatamiento de la Constitución (y Estatuto de Autonomía y resto del ordenamiento) y la toma de posesión.',null),
('aux-ayto-mad:15-4b7f46f799','aux-ayto-mad',15,'¿Cuál de las siguientes NO es causa de pérdida de la condición de funcionario de carrera?','["La pérdida de la nacionalidad", "La excedencia voluntaria", "La renuncia"]'::jsonb,1,'Art. 63 TREBEP','Son causas la renuncia, la pérdida de la nacionalidad, la jubilación total, la pena de inhabilitación firme y la sanción firme de separación del servicio. La excedencia es una situación administrativa.',null),
('aux-ayto-mad:15-361abf06f0','aux-ayto-mad',15,'La jubilación forzosa de los funcionarios se declara al cumplir:','["60 años, pudiendo solicitar la prolongación hasta los 65", "65 años, pudiendo solicitar la prolongación hasta los 70", "67 años, sin posibilidad de solicitar la prolongación de la permanencia en el servicio activo"]'::jsonb,1,'Art. 67.3 TREBEP','Se declara a los sesenta y cinco años, aunque el funcionario puede solicitar la prolongación de la permanencia hasta los setenta.',null),
('aux-ayto-mad:15-d54b55cbe0','aux-ayto-mad',15,'¿Qué titulación se exige para acceder a un cuerpo del subgrupo C2?','["Certificado de escolaridad o de estudios primarios", "Técnico Superior o equivalente a efectos profesionales", "Graduado en Educación Secundaria Obligatoria"]'::jsonb,2,'Art. 76 TREBEP','Para el subgrupo C2 se exige el título de Graduado en ESO; para el C1, Bachiller o Técnico.',null),
('aux-ayto-mad:15-fd438c7195','aux-ayto-mad',15,'¿Cuál de estas NO es una situación administrativa de los funcionarios de carrera?','["Comisión de servicios", "Suspensión de funciones", "Excedencia"]'::jsonb,0,'Art. 85.1 TREBEP','Las situaciones son servicio activo, servicios especiales, servicio en otras Administraciones Públicas, excedencia y suspensión de funciones. La comisión de servicios es una forma de provisión de puestos.',null),
('aux-ayto-mad:15-0ab8580cd0','aux-ayto-mad',15,'Para obtener la excedencia voluntaria por interés particular hay que haber prestado servicios efectivos durante un mínimo de:','["Tres años, consecutivos o no, en cualquier Administración", "Un año inmediatamente anterior a la solicitud", "Cinco años inmediatamente anteriores"]'::jsonb,2,'Art. 89.2 TREBEP','Se exige haber prestado servicios efectivos en cualquier Administración durante un mínimo de cinco años inmediatamente anteriores.',null),
('aux-ayto-mad:15-c663c11dbf','aux-ayto-mad',15,'La excedencia por cuidado de cada hijo tiene una duración:','["No superior a cinco años", "No superior a tres años", "Sin límite"]'::jsonb,1,'Art. 89.4 TREBEP','El periodo de excedencia por cuidado de cada hijo no puede ser superior a tres años.',null),
('aux-ayto-mad:15-48379ad687','aux-ayto-mad',15,'La suspensión firme de funciones por sanción disciplinaria no puede exceder de:','["Seis años", "Tres años", "Dos años"]'::jsonb,0,'Art. 90.2 TREBEP','No puede exceder de seis años. Si supera seis meses, el funcionario pierde su puesto de trabajo (art. 90.1).',null),
('aux-ayto-mad:15-4205450b94','aux-ayto-mad',15,'Según el TREBEP, las faltas disciplinarias se clasifican en:','["Muy graves, graves y leves", "Muy graves y graves", "Graves y leves"]'::jsonb,0,'Art. 95.1 TREBEP','Las faltas disciplinarias pueden ser muy graves, graves y leves.',null),
('aux-ayto-mad:15-55519f2cb6','aux-ayto-mad',15,'¿Cuál de las siguientes sanciones NO aparece expresamente en la lista del art. 96.1 del TREBEP?','["Demérito", "Traslado forzoso", "Multa económica"]'::jsonb,2,'Art. 96.1 TREBEP','Recoge la separación del servicio, el despido disciplinario, la suspensión firme de funciones, el traslado forzoso, el demérito, el apercibimiento y cualquier otra que establezca una ley.',null),
('aux-ayto-mad:15-9344575c90','aux-ayto-mad',15,'¿Cuándo prescriben las faltas leves?','["A los dos años", "A los seis meses", "A los tres meses"]'::jsonb,1,'Art. 97 TREBEP','Las faltas muy graves prescriben a los tres años, las graves a los dos años y las leves a los seis meses.',null),
('aux-ayto-mad:15-07871ffd80','aux-ayto-mad',15,'¿Cuándo prescriben las sanciones impuestas por faltas leves?','["Al año", "A los seis meses", "A los dos años"]'::jsonb,0,'Art. 97 TREBEP','Las sanciones por faltas muy graves prescriben a los tres años, las graves a los dos años y las leves al año.',null),
('aux-ayto-mad:15-e46bff7036','aux-ayto-mad',15,'La suspensión provisional como medida cautelar en un expediente disciplinario no puede exceder de:','["Seis meses, salvo paralización del procedimiento imputable al interesado", "Un año, salvo paralización del procedimiento imputable a la Administración que lo tramita", "Tres meses, salvo paralización del procedimiento imputable al interesado"]'::jsonb,0,'Art. 98.3 TREBEP','No puede exceder de seis meses, salvo en caso de paralización del procedimiento imputable al interesado.',null),
('aux-ayto-mad:15-fc7b5e67f1','aux-ayto-mad',15,'Las retribuciones básicas están integradas por:','["El sueldo asignado a cada subgrupo, los trienios y el complemento de destino del puesto que se ocupe", "El sueldo asignado a cada subgrupo o grupo y los trienios", "La productividad y las gratificaciones por servicios extraordinarios"]'::jsonb,1,'Art. 23 TREBEP','Los trienios consisten en una cantidad por cada tres años de servicio.',null),
('aux-ayto-mad:15-02a3c3b85c','aux-ayto-mad',15,'Los Delegados de Personal representan a los funcionarios en unidades electorales que cuenten con:','["Más de 50 funcionarios", "Entre 6 y 49 funcionarios", "Menos de 6 funcionarios"]'::jsonb,1,'Art. 39.2 TREBEP','A partir de 50 funcionarios hay Juntas de Personal.',null),
('aux-ayto-mad:15-960a806a8e','aux-ayto-mad',15,'El plazo de prescripción de las sanciones comenzará a contarse:','["Desde la comisión de la falta", "Desde la incoación del expediente", "Desde la firmeza de la resolución sancionadora"]'::jsonb,2,'Art. 97 TREBEP','El de las faltas, desde que se hubieran cometido, o desde el cese de su comisión si son continuadas.',null),
('aux-ayto-mad:15-88f93074d6','aux-ayto-mad',15,'El personal eventual:','["Solo realiza funciones expresamente calificadas como de confianza o asesoramiento especial, y su nombramiento y cese son libres", "Accede mediante concurso de méritos", "Tiene derecho a la inamovilidad tras dos años de servicio, y su nombramiento corresponde al órgano de selección tras un concurso de méritos con convocatoria pública"]'::jsonb,0,'Art. 12.1 y 12.3 TREBEP','El cese tiene lugar, en todo caso, cuando se produzca el de la autoridad a la que preste su función de confianza.',null),
('aux-ayto-mad:15-b0302ec5b6','aux-ayto-mad',15,'Según el art. 54.11, los empleados públicos garantizarán la atención al ciudadano en:','["La lengua que lo solicite siempre que sea oficial en el territorio", "La lengua oficial que solicite y, si lo pide, también en inglés", "Castellano exclusivamente"]'::jsonb,0,'Art. 54.11 TREBEP','Es otro principio de conducta.',null),
('aux-ayto-mad:15-91a4aafabb','aux-ayto-mad',15,'En las ofertas de empleo público se reservará un cupo para personas con discapacidad no inferior al:','["10 % de las vacantes", "7 % de las vacantes", "2 % de las vacantes"]'::jsonb,1,'Art. 59.1 TREBEP','De ese cupo, al menos el 2 % de las plazas para personas con discapacidad intelectual.',null),
('aux-ayto-mad:15-f1ab8c08f7','aux-ayto-mad',15,'Por traslado de domicilio sin cambio de residencia, el funcionario tiene un permiso de:','["Un día", "Dos días", "Tres días"]'::jsonb,0,'Art. 48 b) TREBEP','Permiso de un día por traslado de domicilio.',null),
('aux-ayto-mad:15-097b0f2070','aux-ayto-mad',15,'La funcionaria víctima de violencia de género que reduzca su jornada en un tercio o menos:','["Pierde las retribuciones básicas", "Mantendrá sus retribuciones íntegras", "Solo cobra el 50 %"]'::jsonb,1,'Art. 49 d) TREBEP','Si la reducción es mayor, la disminución de retribuciones es proporcional.',null),
('aux-ayto-mad:15-8be7ba2752','aux-ayto-mad',15,'Las faltas leves se sancionarán:','["Por el procedimiento previsto para las faltas graves y muy graves", "Solo por un juez", "Por un procedimiento sumario con audiencia al interesado"]'::jsonb,2,'Art. 98.1 TREBEP','Las faltas muy graves y graves exigen el procedimiento previamente establecido.',null),
('aux-ayto-mad:15-c9dab1c2ad','aux-ayto-mad',15,'El permiso parental para el cuidado de hijo o menor acogido por tiempo superior a un año, hasta que cumpla ocho años, tiene una duración máxima de:','["Cuatro semanas retribuidas", "Un año", "Ocho semanas, y no es retribuido"]'::jsonb,2,'Art. 49 g) TREBEP','Se requiere un preaviso de quince días.',null),
('aux-ayto-mad:15-af3f06cc16','aux-ayto-mad',15,'El teletrabajo de los empleados públicos:','["Tendrá carácter voluntario y reversible, salvo en supuestos excepcionales debidamente justificados", "Es irreversible una vez concedido y solo puede revocarse como sanción disciplinaria tras el expediente correspondiente", "Es obligatorio para los puestos cuyas funciones permitan prestarse a distancia, salvo renuncia justificada del empleado"]'::jsonb,0,'Art. 47 bis.2 TREBEP','Se realizará en los términos de las normas que se dicten en desarrollo del Estatuto.',null),
('aux-ayto-mad:15-cd7b922db1','aux-ayto-mad',15,'Por accidente o enfermedad grave de un familiar de primer grado de consanguinidad o afinidad, el funcionario tiene un permiso de:','["Tres días naturales", "Cinco días hábiles", "Dos días hábiles"]'::jsonb,1,'Art. 48 a) TREBEP','Para familiares de segundo grado, cuatro días hábiles.',null),
('aux-ayto-mad:15-b536ef17e0','aux-ayto-mad',15,'La oferta de empleo público deberá desarrollarse dentro del plazo improrrogable de:','["Tres años", "Dos años", "Cinco años"]'::jsonb,0,'Art. 70.1 TREBEP','La oferta puede contener hasta un 10 % adicional de plazas.',null),
('aux-ayto-mad:15-d39a3eeed7','aux-ayto-mad',15,'Los funcionarios pueden solicitar la prolongación de la permanencia en el servicio activo, una vez cumplida la edad de jubilación forzosa, como máximo hasta:','["Los sesenta y siete años", "Los sesenta y ocho años", "Los setenta años"]'::jsonb,2,'Art. 67.3 TREBEP','La jubilación forzosa se declara al cumplir 65 años.',null),
('aux-ayto-mad:15-952be9d078','aux-ayto-mad',15,'Quedan excluidas de la obligatoriedad de la negociación:','["La evaluación del desempeño", "Las decisiones que afecten a las potestades de organización de las Administraciones Públicas", "Los criterios generales de acceso, carrera, provisión, sistemas de clasificación de puestos y planes de recursos humanos"]'::jsonb,1,'Art. 37.2 a) TREBEP','Las demás opciones son materias objeto de negociación (art. 37.1).',null),
('aux-ayto-mad:15-cee46235a9','aux-ayto-mad',15,'Los procedimientos de provisión de puestos de trabajo de los funcionarios de carrera son, con carácter general:','["El concurso y la libre designación con convocatoria pública", "La oposición y el concurso-oposición", "El concurso y la libre designación sin convocatoria pública"]'::jsonb,0,'Art. 78.2 TREBEP','El concurso es el procedimiento normal de provisión.',null),
('aux-ayto-mad:15-085c0000b1','aux-ayto-mad',15,'La suspensión de funciones determinará la pérdida del puesto de trabajo cuando exceda de:','["Seis meses", "Un año", "Un mes"]'::jsonb,0,'Art. 90.1 TREBEP','El funcionario suspenso queda privado del ejercicio de sus funciones.',null),
('aux-ayto-mad:15-ba9e5e3ac5','aux-ayto-mad',15,'La libre designación con convocatoria pública consiste en:','["La apreciación discrecional por el órgano competente de la idoneidad de los candidatos en relación con los requisitos del puesto", "Una prueba de conocimientos eliminatoria sobre las funciones del puesto, seguida de la valoración de méritos por una comisión técnica independiente", "La antigüedad del candidato"]'::jsonb,0,'Art. 80.1 TREBEP','Se aplica a los puestos que determinen las leyes por su especial responsabilidad.',null),
('aux-ayto-mad:15-e6e3bdea13','aux-ayto-mad',15,'Según el art. 54.6 TREBEP, los empleados públicos:','["Pueden aceptar regalos de cualquier valor siempre que los declaren a su superior jerárquico en el plazo de diez días desde su recepción y los inscriban en el registro", "Rechazarán cualquier regalo, favor o servicio en condiciones ventajosas que vaya más allá de los usos habituales, sociales y de cortesía", "Solo pueden aceptar regalos de otros empleados públicos o de los ciudadanos, siempre que no superen el valor que fije cada Administración en su código ético"]'::jsonb,1,'Art. 54.6 TREBEP','Es un principio de conducta.',null),
('aux-ayto-mad:15-1e347a5376','aux-ayto-mad',15,'Durante la suspensión provisional como medida cautelar, el funcionario:','["Percibirá las retribuciones complementarias, pero no las básicas", "No percibe ninguna retribución", "Percibirá las retribuciones básicas y, en su caso, las prestaciones familiares por hijo a cargo"]'::jsonb,2,'Art. 98.3 TREBEP','Si la suspensión se eleva a definitiva, deberá devolver lo percibido.',null),
('aux-ayto-mad:15-54f98acec8','aux-ayto-mad',15,'NO pueden formar parte de los órganos de selección:','["El personal de elección o designación política, los funcionarios interinos y el personal eventual", "Los funcionarios del mismo cuerpo o escala al que se aspira a ingresar y el personal laboral fijo de la misma Administración", "El personal laboral fijo y los funcionarios de carrera que hayan preparado a aspirantes en los cinco años anteriores"]'::jsonb,0,'Art. 60.2 TREBEP','Los órganos de selección son colegiados y tienden a la paridad.',null),
('aux-ayto-mad:15-f3659885a0','aux-ayto-mad',15,'Los nacionales de los Estados miembros de la Unión Europea pueden acceder como funcionarios en igualdad de condiciones que los españoles, salvo a los empleos que impliquen:','["Funciones administrativas, de gestión o de auxilio, aunque no impliquen ejercicio de potestades públicas", "Participación en el ejercicio del poder público o en las funciones de salvaguardia de los intereses del Estado", "Trabajos en entidades locales"]'::jsonb,1,'Art. 57.1 TREBEP','Los extranjeros con residencia legal pueden acceder como personal laboral (art. 57.4).',null),
('aux-ayto-mad:15-99433524b5','aux-ayto-mad',15,'Las pagas extraordinarias de los funcionarios serán:','["Dos al año, cada una por el importe de una mensualidad de retribuciones básicas y de la totalidad de las complementarias, salvo excepciones", "Tres al año, cada una por el importe de una mensualidad de retribuciones básicas y de la mitad de las complementarias, que se abonan en marzo, junio y diciembre", "Cuatro al año"]'::jsonb,0,'Art. 22.4 TREBEP','Son dos pagas al año.',null),
('aux-ayto-mad:15-42dc192330','aux-ayto-mad',15,'La renuncia voluntaria a la condición de funcionario:','["No está permitida mientras el funcionario no haya cumplido la edad de jubilación, salvo que lo autorice expresamente el Consejo de Gobierno por razones excepcionales de interés público", "No necesita aceptación expresa y surte efectos desde su presentación, aunque el funcionario esté sujeto a expediente disciplinario o haya sido procesado por un delito", "Habrá de ser manifestada por escrito y será aceptada expresamente por la Administración, salvo que el funcionario esté sujeto a expediente disciplinario o procesado"]'::jsonb,2,'Art. 64 TREBEP','La renuncia no inhabilita para volver a ingresar por el procedimiento de selección.',null),
('aux-ayto-mad:15-a9cbc043d4','aux-ayto-mad',15,'Transcurridos tres años desde el nombramiento de un interino en plaza vacante, esta:','["Solo podrá ser ocupada por personal funcionario de carrera, salvo que el proceso selectivo quede desierto", "Se convierte automáticamente en plaza en propiedad del interino que la ocupa, sin necesidad de proceso selectivo", "Se amortiza automáticamente y el interino cesa sin derecho a indemnización, aunque el proceso selectivo no se haya convocado"]'::jsonb,0,'Art. 10.4 TREBEP','Se produce el fin de la relación de interinidad.',null),
('aux-ayto-mad:15-04aff95351','aux-ayto-mad',15,'Es un derecho individual de los empleados públicos del art. 14 TREBEP:','["La negociación colectiva y la participación en la determinación de las condiciones de trabajo", "La formación continua y la actualización permanente de sus conocimientos", "La huelga y el planteamiento de conflictos colectivos de trabajo en su unidad"]'::jsonb,1,'Art. 14 g) TREBEP','Los demás citados son derechos individuales ejercidos colectivamente (art. 15).',null),
('aux-ayto-mad:15-7996759a41','aux-ayto-mad',15,'Durante los dos primeros años de excedencia por cuidado de hijos o familiares, el funcionario tiene derecho a:','["Seguir percibiendo las retribuciones básicas y la reserva de un puesto en la misma localidad", "La reserva del puesto de trabajo que desempeñaba", "Ascender automáticamente de grado"]'::jsonb,1,'Art. 89.4 TREBEP','Transcurrido ese periodo, la reserva lo es a un puesto en la misma localidad y de igual retribución.',null),
('aux-ayto-mad:15-0cab6766a5','aux-ayto-mad',15,'Las sanciones impuestas por faltas graves prescriben a los:','["Dos años", "Seis meses", "Tres años"]'::jsonb,0,'Art. 97 TREBEP','Las muy graves a los tres años y las leves al año.',null),
('aux-ayto-mad:15-1348f33a4b','aux-ayto-mad',15,'Las faltas muy graves prescriben a los:','["Tres años", "Cinco años", "Seis meses"]'::jsonb,0,'Art. 97 TREBEP','Las graves a los dos años y las leves a los seis meses.',null),
('aux-ayto-mad:15-31415142da','aux-ayto-mad',15,'A efectos de vacaciones de los funcionarios, los sábados:','["Se consideran siempre días hábiles, cualquiera que sea el horario del funcionario", "Se consideran hábiles solo en agosto", "No se consideran días hábiles, salvo en los horarios especiales"]'::jsonb,2,'Art. 50.1 TREBEP','Las vacaciones son de 22 días hábiles.',null),
('aux-ayto-mad:15-0dadd37586','aux-ayto-mad',15,'La parte de jornada no realizada sin justificación dará lugar a:','["La deducción proporcional de haberes, que no tendrá carácter sancionador", "Una sanción disciplinaria grave, previa tramitación del expediente correspondiente", "Ninguna consecuencia económica, aunque deberá recuperarse en otro momento de la semana"]'::jsonb,0,'Art. 30.1 TREBEP','La deducción no es una sanción.',null),
('aux-ayto-mad:15-f3449817c7','aux-ayto-mad',15,'Para participar en la promoción interna, los funcionarios deben poseer una antigüedad de, al menos:','["Cinco años de servicio activo en cualquier cuerpo o escala de la misma Administración pública", "Dos años de servicio activo en el inferior subgrupo o grupo de clasificación profesional", "Tres años de servicio activo en el mismo cuerpo o escala, de los cuales al menos uno en la misma Administración"]'::jsonb,1,'Art. 18.2 TREBEP','Además de la titulación y demás requisitos exigidos.',null),
('aux-ayto-mad:15-0cfea8600c','aux-ayto-mad',15,'Durante los dos primeros meses de excedencia por razón de violencia de género, la funcionaria tendrá derecho a:','["Percibir las retribuciones íntegras y, en su caso, las prestaciones familiares por hijo a cargo", "Percibir solo las retribuciones básicas, pero no las complementarias ni las prestaciones familiares por hijo a cargo", "No percibir retribución alguna, aunque se le reserva el puesto de trabajo y se computa el tiempo a efectos de antigüedad"]'::jsonb,0,'Art. 89.5 TREBEP','Durante los seis primeros meses tiene reserva del puesto, prorrogable por periodos de tres meses hasta dieciocho.',null),
('aux-ayto-mad:15-392a2bf190','aux-ayto-mad',15,'La designación del personal directivo profesional atenderá a principios de:','["Antigüedad en el cuerpo, y en caso de empate, mérito y capacidad mediante procedimientos que garanticen la publicidad y la concurrencia", "Mérito y capacidad y criterios de idoneidad, mediante procedimientos que garanticen la publicidad y concurrencia", "Sorteo entre funcionarios del subgrupo A1"]'::jsonb,1,'Art. 13.2 TREBEP','Así lo establece el art. 13.2.',null),
('aux-ayto-mad:15-a9747b89ac','aux-ayto-mad',15,'Los trienios consisten en una cantidad, igual para cada subgrupo o grupo, por cada:','["Cinco años de servicio", "Tres años de servicio", "Dos años de servicio"]'::jsonb,1,'Art. 23 b) TREBEP','Retribución básica por antigüedad.',null),
('aux-ayto-mad:15-992424ed02','aux-ayto-mad',15,'Las retribuciones de los funcionarios de carrera se clasifican en:','["Directas e indirectas", "Ordinarias y extraordinarias", "Básicas y complementarias"]'::jsonb,2,'Art. 22.1 TREBEP','Las pagas extraordinarias son dos al año.',null),
('aux-ayto-mad:15-a43fd1080a','aux-ayto-mad',15,'Los Pactos y Acuerdos, salvo que se establezca otra cosa:','["Caducan al año de su firma, salvo que se renueven expresamente", "Se prorrogarán de año en año si no media denuncia expresa de una de las partes", "Se prorrogarán por periodos de cuatro años, salvo que una de las partes los denuncie con seis meses de antelación"]'::jsonb,1,'Art. 38.11 TREBEP','Prórroga anual salvo denuncia.',null),
('aux-ayto-mad:15-942928c5c0','aux-ayto-mad',15,'Por fallecimiento de un familiar de primer grado en la misma localidad, el permiso es de:','["Cinco días hábiles", "Dos días hábiles", "Tres días hábiles"]'::jsonb,2,'Art. 48 a) TREBEP','Si es en distinta localidad, cinco días hábiles.',null),
('aux-ayto-mad:15-a0b0afd2e9','aux-ayto-mad',15,'Las Mesas de Negociación quedarán válidamente constituidas cuando las organizaciones sindicales presentes representen, como mínimo:','["Un tercio de los miembros de los órganos unitarios de representación en el ámbito de que se trate", "La mayoría absoluta de los miembros de los órganos unitarios de representación en el ámbito de que se trate", "El 10 % de los miembros de los órganos unitarios de representación"]'::jsonb,1,'Art. 35.1 TREBEP','Ninguna de las partes puede superar quince miembros (art. 35.4).',null),
('aux-ayto-mad:15-6556a3c45e','aux-ayto-mad',15,'Los órganos de selección no podrán proponer el acceso a la condición de funcionario de un número superior de aprobados al de plazas convocadas:','["En ningún caso, y cualquier propuesta que lo contravenga será nula de pleno derecho", "Salvo que la convocatoria prevea otra cosa", "Salvo en la Administración Local, cuando lo acuerde el Pleno"]'::jsonb,1,'Art. 61.8 TREBEP','Regla general con la excepción prevista.',null),
('aux-ayto-mad:15-fc353aa00a','aux-ayto-mad',15,'La excedencia por cuidado de un familiar hasta el segundo grado que no pueda valerse por sí mismo tiene una duración no superior a:','["Tres años", "Un año", "Cinco años"]'::jsonb,0,'Art. 89.4 TREBEP','Igual que la excedencia por cuidado de cada hijo.',null),
('aux-ayto-mad:15-707254eec0','aux-ayto-mad',15,'Si la incapacidad temporal impide disfrutar las vacaciones en el año natural, podrán disfrutarse una vez finalizada, siempre que no hayan transcurrido más de:','["Tres años", "Dieciocho meses a partir del final del año en que se hayan originado", "Seis meses a partir del final del año en que se hayan originado"]'::jsonb,1,'Art. 50.2 TREBEP','Las vacaciones no pueden sustituirse por una cuantía económica, salvo cese no voluntario.',null),
('aux-ayto-mad:15-021e42ac8d','aux-ayto-mad',15,'En el permiso por nacimiento, ¿cuántas semanas inmediatas posteriores al parto son de descanso obligatorio?','["Seis semanas", "Dos semanas", "Cuatro semanas"]'::jsonb,0,'Art. 49 a) TREBEP','Las seis semanas posteriores al parto son obligatorias e ininterrumpidas.',null),
('aux-ayto-mad:15-e18c16db79','aux-ayto-mad',15,'Es una falta muy grave según el art. 95.2 TREBEP:','["El descuido leve en el trabajo", "La falta de puntualidad ocasional", "El abandono del servicio"]'::jsonb,2,'Art. 95.2 c) TREBEP','Otras faltas muy graves: desobediencia abierta, acoso laboral, etc.',null),
('aux-ayto-mad:15-5fc8072e19','aux-ayto-mad',15,'La sanción de separación del servicio de los funcionarios solo podrá imponerse por:','["Faltas graves cometidas de forma reiterada", "Faltas graves reiteradas en el plazo de un año", "La comisión de faltas muy graves"]'::jsonb,2,'Art. 96.1 a) TREBEP','En los interinos implica la revocación del nombramiento.',null),
('aux-ayto-mad:15-393a240cdc','aux-ayto-mad',15,'La duración del mandato de los Delegados de Personal y de las Juntas de Personal es de:','["Tres años", "Cinco años", "Cuatro años"]'::jsonb,2,'Art. 42 TREBEP','Pueden ser reelegidos en sucesivos procesos electorales.',null),
('aux-ayto-mad:15-4b3706ea2b','aux-ayto-mad',15,'Según el TREBEP, ¿cuál es el procedimiento normal de provisión de puestos de trabajo de los funcionarios de carrera?','["La adscripción provisional", "La comisión de servicios", "El concurso"]'::jsonb,2,'Art. 78 TREBEP','La libre designación con convocatoria pública es el otro procedimiento ordinario, reservado a puestos determinados por su especial responsabilidad o confianza.',null),
('aux-ayto-mad:15-1131bfa3d0','aux-ayto-mad',15,'¿Cuál de las siguientes NO es una situación administrativa de los funcionarios de carrera según el artículo 85 del TREBEP?','["Servicios especiales", "Servicio en otras Administraciones Públicas", "Expectativa de destino indefinida"]'::jsonb,2,'Art. 85.1 TREBEP','Las situaciones son servicio activo, servicios especiales, servicio en otras Administraciones Públicas, excedencia y suspensión de funciones.',null),
('aux-ayto-mad:15-13313cd6fa','aux-ayto-mad',15,'Los funcionarios que acceden a la condición de diputado o senador de las Cortes Generales pasan a la situación de:','["Servicios especiales", "Servicio activo con dispensa de funciones", "Excedencia voluntaria por interés particular"]'::jsonb,0,'Art. 87.1 TREBEP','Tienen derecho a reingresar al servicio activo en la misma localidad y en las mismas condiciones y con las retribuciones correspondientes a su categoría.',null),
('aux-ayto-mad:15-eee82e17d4','aux-ayto-mad',15,'Según el TREBEP, los funcionarios en situación de servicios especiales:','["Pierden la condición de funcionario mientras dure la situación", "Solo tienen derecho al cómputo de trienios, pero no a la reserva de puesto", "Tienen derecho a que se les compute el tiempo en esa situación a efectos de ascensos, reconocimiento de trienios y derechos en el régimen de Seguridad Social"]'::jsonb,2,'Art. 87.2 TREBEP','No se les aplica, sin embargo, el régimen de derechos pasivos si les corresponde otro.',null),
('aux-ayto-mad:15-b04388f6bc','aux-ayto-mad',15,'Según el TREBEP, en las ofertas de empleo público se reserva para personas con discapacidad intelectual, dentro del cupo general, al menos:','["El 1 % de las plazas ofertadas", "El 5 % de las plazas ofertadas", "El 2 % de las plazas ofertadas"]'::jsonb,2,'Art. 59.1 TREBEP','El cupo total para personas con discapacidad no es inferior al 7 %, y de él al menos el 2 % es para personas con discapacidad intelectual.',null),
('aux-ayto-mad:16-0bfeec995d','aux-ayto-mad',16,'La Ley Orgánica 3/2007 tiene por objeto:','["Establecer medidas de protección integral contra la violencia de género y de igualdad de oportunidades en el empleo", "Hacer efectivo el derecho de igualdad de trato entre mujeres y hombres, pero solo en el ámbito del empleo público y de la negociación colectiva", "Hacer efectivo el derecho de igualdad de trato y de oportunidades entre mujeres y hombres"]'::jsonb,2,'Art. 1.1 LO 3/2007','Su objeto es hacer efectivo el derecho de igualdad de trato y de oportunidades entre mujeres y hombres.',null),
('aux-ayto-mad:16-08a6459c59','aux-ayto-mad',16,'El principio de igualdad de trato entre mujeres y hombres supone:','["La paridad obligatoria en todos los órganos públicos y privados, con independencia de su composición", "La ausencia de discriminación directa por razón de sexo, pero no de la indirecta, que se rige por la normativa laboral", "La ausencia de toda discriminación, directa o indirecta, por razón de sexo"]'::jsonb,2,'Art. 3 LO 3/2007','Supone la ausencia de toda discriminación, directa o indirecta, por razón de sexo, especialmente por maternidad, obligaciones familiares y estado civil.',null),
('aux-ayto-mad:16-b55a16a603','aux-ayto-mad',16,'Se considera discriminación directa por razón de sexo la situación en que una persona:','["Sufre una desventaja particular respecto de personas del otro sexo por una disposición, criterio o práctica aparentemente neutros", "Es tratada igual que otra persona en una situación distinta", "Es, ha sido o pudiera ser tratada, en atención a su sexo, de manera menos favorable que otra en situación comparable"]'::jsonb,2,'Art. 6.1 LO 3/2007','Es la situación de quien es, ha sido o pudiera ser tratada, en atención a su sexo, de manera menos favorable que otra en situación comparable. El trato por disposición aparentemente neutra es la discriminación indirecta.',null),
('aux-ayto-mad:16-66da1b1986','aux-ayto-mad',16,'El acoso sexual es cualquier comportamiento, verbal o físico, de naturaleza sexual que:','["Se repita al menos tres veces y lo denuncie la persona afectada o un tercero", "Tenga el propósito o produzca el efecto de atentar contra la dignidad de una persona", "Produzca una lesión física acreditada"]'::jsonb,1,'Art. 7.1 LO 3/2007','Tiene el propósito o produce el efecto de atentar contra la dignidad de una persona, en particular cuando crea un entorno intimidatorio, degradante u ofensivo.',null),
('aux-ayto-mad:16-211f85a22f','aux-ayto-mad',16,'Todo trato desfavorable a las mujeres relacionado con el embarazo o la maternidad constituye:','["Discriminación directa por razón de sexo", "Discriminación indirecta por razón de sexo, salvo que la empresa acredite una justificación objetiva", "Acoso por razón de sexo"]'::jsonb,0,'Art. 8 LO 3/2007','Constituye discriminación directa por razón de sexo.',null),
('aux-ayto-mad:16-4dda33c712','aux-ayto-mad',16,'Según la LO 3/2007, el principio de igualdad de trato y oportunidades informará la actuación de todos los Poderes Públicos con carácter:','["Voluntario", "Transversal", "Subsidiario"]'::jsonb,1,'Art. 15 LO 3/2007','Informará, con carácter transversal, la actuación de todos los Poderes Públicos.',null),
('aux-ayto-mad:16-803a389f2a','aux-ayto-mad',16,'¿Qué empresas deben elaborar y aplicar un plan de igualdad?','["Solo las empresas públicas y las que contraten con la Administración, cualquiera que sea su plantilla", "Todas, cualquiera que sea su plantilla", "Las de cincuenta o más trabajadores"]'::jsonb,2,'Art. 45.2 LO 3/2007','Las empresas de cincuenta o más trabajadores.',null),
('aux-ayto-mad:16-125157f3d2','aux-ayto-mad',16,'Según la LO 3/2007, hay composición equilibrada cuando las personas de cada sexo:','["No superan el 60 % ni son menos del 40 %", "No superan el 55 % ni son menos del 45 %", "No superan el 70 % ni son menos del 30 %"]'::jsonb,0,'Disp. adicional 1.ª LO 3/2007','Las personas de cada sexo no superan el sesenta por ciento ni son menos del cuarenta por ciento.',null),
('aux-ayto-mad:16-7baf769388','aux-ayto-mad',16,'El Plan para la Igualdad entre mujeres y hombres en la Administración General del Estado se aprueba por el Gobierno:','["Cada año", "Solo cuando lo pide el Congreso", "Al inicio de cada legislatura"]'::jsonb,2,'Art. 64 LO 3/2007','Su cumplimiento se evalúa anualmente por el Consejo de Ministros.',null),
('aux-ayto-mad:16-75c8b68769','aux-ayto-mad',16,'En los litigios sobre acoso sexual y acoso por razón de sexo, está legitimada:','["El sindicato mayoritario en todo caso", "Únicamente la persona acosada", "El Ministerio Fiscal en exclusiva"]'::jsonb,1,'Art. 12.3 LO 3/2007','La persona acosada es la única legitimada.',null),
('aux-ayto-mad:16-3e62739a8e','aux-ayto-mad',16,'Según el art. 6.3 de la LO 3/2007, toda orden de discriminar, directa o indirectamente, por razón de sexo:','["Se considerará en todo caso discriminatoria", "Es válida si procede de un superior", "No tiene relevancia jurídica si no llega a ejecutarse"]'::jsonb,0,'Art. 6.3 LO 3/2007','La orden de discriminar es en sí misma discriminación.',null),
('aux-ayto-mad:16-c8b9c9420b','aux-ayto-mad',16,'Las acciones positivas para hacer efectivo el derecho a la igualdad pueden adoptarlas:','["Solo las empresas de más de 250 trabajadores, dentro de su plan de igualdad negociado con la representación legal de los trabajadores", "Solo el Gobierno y las Administraciones públicas", "Los poderes públicos y también las personas físicas y jurídicas privadas"]'::jsonb,2,'Art. 11 LO 3/2007','Deben ser razonables y proporcionadas.',null),
('aux-ayto-mad:16-1f27994825','aux-ayto-mad',16,'Los proyectos de disposiciones de carácter general y los planes de especial relevancia que se sometan a la aprobación del Consejo de Ministros deberán incorporar:','["Un informe económico de la UE", "Un informe sobre su impacto por razón de género", "La firma de todas las Comunidades Autónomas"]'::jsonb,1,'Art. 19 LO 3/2007','Es el informe de impacto de género.',null),
('aux-ayto-mad:16-1d706db2b5','aux-ayto-mad',16,'Según la LO 3/2007, se considera discriminación por razón de sexo cualquier trato adverso o efecto negativo producido como consecuencia de:','["Su cambio de domicilio", "Su ascenso profesional o la obtención de un puesto de libre designación tras un procedimiento de provisión con convocatoria pública", "La presentación por una persona de una queja, reclamación, denuncia o demanda destinada a impedir su discriminación"]'::jsonb,2,'Art. 9 LO 3/2007','Es la garantía de indemnidad frente a represalias.',null),
('aux-ayto-mad:16-97b590ca70','aux-ayto-mad',16,'Entre los criterios de actuación de las Administraciones en el empleo público, la LO 3/2007 incluye:','["Reservar los puestos directivos a la persona más antigua", "Establecer cuotas obligatorias del 60 % de mujeres en todos los órganos de selección y valoración", "Promover la presencia equilibrada de mujeres y hombres en los órganos de selección y valoración"]'::jsonb,2,'Art. 51 d) LO 3/2007','También establecer medidas efectivas para eliminar cualquier discriminación retributiva.',null),
('aux-ayto-mad:16-db38db45ff','aux-ayto-mad',16,'En los procedimientos (no penales) en que se aleguen actuaciones discriminatorias por razón de sexo, corresponde probar la ausencia de discriminación a:','["La persona demandante", "El juez", "La persona demandada"]'::jsonb,2,'Art. 13.1 LO 3/2007','Es la inversión de la carga de la prueba; no se aplica a los procesos penales.',null),
('aux-ayto-mad:17-3f355155c4','aux-ayto-mad',17,'Según la Ley 31/1995, su objeto es:','["Establecer las sanciones por accidentes laborales", "Promover la seguridad y la salud de los trabajadores mediante la aplicación de medidas y actividades para prevenir los riesgos derivados del trabajo", "Regular las prestaciones de la Seguridad Social por accidente de trabajo y enfermedad profesional"]'::jsonb,1,'Art. 2.1 Ley 31/1995','El art. 2.1 fija como objeto promover la seguridad y la salud de los trabajadores mediante la aplicación de medidas y el desarrollo de las actividades necesarias para la prevención de riesgos derivados del trabajo.',null),
('aux-ayto-mad:17-77a735b99e','aux-ayto-mad',17,'Las disposiciones de carácter laboral de la Ley 31/1995 y de sus normas reglamentarias tienen el carácter de:','["Normas orientativas sin fuerza obligatoria", "Derecho necesario mínimo indisponible, mejorable en los convenios colectivos", "Derecho dispositivo, que puede excluirse por convenio colectivo"]'::jsonb,1,'Art. 2.2 Ley 31/1995','Según el art. 2.2, tienen en todo caso el carácter de Derecho necesario mínimo indisponible, y pueden ser mejoradas y desarrolladas en los convenios colectivos.',null),
('aux-ayto-mad:17-7d8636ae0e','aux-ayto-mad',17,'Según la Ley 31/1995, se entiende por «prevención»:','["El conjunto de actividades o medidas adoptadas o previstas en todas las fases de actividad de la empresa para evitar o disminuir los riesgos derivados del trabajo", "La posibilidad de que un trabajador sufra un determinado daño derivado del trabajo", "Cualquier equipo destinado a ser llevado o sujetado por el trabajador para que le proteja de uno o varios riesgos"]'::jsonb,0,'Art. 4.1.º Ley 31/1995','Así lo define el art. 4.1.º. La posibilidad de sufrir un daño es el «riesgo laboral» (art. 4.2.º) y el equipo que protege al trabajador es el «equipo de protección individual» (art. 4.8.º).',null),
('aux-ayto-mad:17-eed923c132','aux-ayto-mad',17,'Según la Ley 31/1995, para calificar un riesgo laboral desde el punto de vista de su gravedad se valorarán conjuntamente:','["El coste de las medidas preventivas y el tamaño de la empresa", "La probabilidad de que se produzca el daño y su severidad", "La duración de la exposición y el número de trabajadores afectados"]'::jsonb,1,'Art. 4.2.º Ley 31/1995','Según el art. 4.2.º, se valoran conjuntamente la probabilidad de que se produzca el daño y la severidad del mismo.',null),
('aux-ayto-mad:17-22820eb618','aux-ayto-mad',17,'Según la Ley 31/1995, son «daños derivados del trabajo»:','["Solo los accidentes de trabajo que causen baja médica", "Las pérdidas económicas de la empresa por accidentes y por bajas laborales", "Las enfermedades, patologías o lesiones sufridas con motivo u ocasión del trabajo"]'::jsonb,2,'Art. 4.3.º Ley 31/1995','Así lo define el art. 4.3.º.',null),
('aux-ayto-mad:17-f09fdf51a2','aux-ayto-mad',17,'Según la Ley 31/1995, el «riesgo laboral grave e inminente» es aquel que:','["Ya se ha materializado en un accidente grave", "Afecta a más de la mitad de la plantilla y exige la intervención de la Inspección de Trabajo", "Resulte probable racionalmente que se materialice en un futuro inmediato y pueda suponer un daño grave para la salud"]'::jsonb,2,'Art. 4.4.º Ley 31/1995','Así lo define el art. 4.4.º.',null),
('aux-ayto-mad:17-1c91eebf53','aux-ayto-mad',17,'Según la Ley 31/1995, un «equipo de trabajo» es:','["El conjunto de trabajadores que desarrollan una misma tarea", "Cualquier equipo destinado a ser llevado por el trabajador para protegerse", "Cualquier máquina, aparato, instrumento o instalación utilizada en el trabajo"]'::jsonb,2,'Art. 4.6.º Ley 31/1995','Así lo define el art. 4.6.º. El equipo llevado por el trabajador para protegerse es el equipo de protección individual (art. 4.8.º).',null),
('aux-ayto-mad:17-88b99f860e','aux-ayto-mad',17,'Según la Ley 31/1995, el deber de protección de los trabajadores frente a los riesgos laborales es también un deber:','["De los sindicatos más representativos", "Exclusivo de los servicios de prevención ajenos con los que se concierte", "De las Administraciones públicas respecto del personal a su servicio"]'::jsonb,2,'Art. 14.1 Ley 31/1995','Según el art. 14.1, este deber de protección constituye, igualmente, un deber de las Administraciones públicas respecto del personal a su servicio.',null),
('aux-ayto-mad:17-45848acbb5','aux-ayto-mad',17,'Según la Ley 31/1995, el coste de las medidas relativas a la seguridad y la salud en el trabajo:','["Recae sobre los trabajadores cuando se trate de equipos de protección individual", "No deberá recaer en modo alguno sobre los trabajadores", "Se reparte entre empresario y trabajadores a partes iguales"]'::jsonb,1,'Art. 14.5 Ley 31/1995','El art. 14.5 dice que no deberá recaer en modo alguno sobre los trabajadores.',null),
('aux-ayto-mad:17-d06231bbdb','aux-ayto-mad',17,'¿Cuál de los siguientes es un principio de la acción preventiva del artículo 15 de la Ley 31/1995?','["Adoptar medidas que antepongan la protección colectiva a la individual", "Evaluar todos los riesgos antes de intentar evitarlos", "Anteponer la protección individual a la colectiva"]'::jsonb,0,'Art. 15.1 h) Ley 31/1995','Entre los principios están evitar los riesgos, evaluar los que no se puedan evitar, combatirlos en su origen, adaptar el trabajo a la persona y anteponer la protección colectiva a la individual.',null),
('aux-ayto-mad:17-c654c768f6','aux-ayto-mad',17,'Según los principios de la acción preventiva, el empresario debe:','["Sustituir lo peligroso por lo que entrañe poco o ningún peligro", "Asegurar los riesgos en lugar de evitarlos", "Trasladar los riesgos a los servicios de prevención ajenos"]'::jsonb,0,'Art. 15.1 f) Ley 31/1995','Es uno de los principios generales del art. 15.1.',null),
('aux-ayto-mad:17-3e8a2e6f4b','aux-ayto-mad',17,'Según la Ley 31/1995, la efectividad de las medidas preventivas deberá prever:','["Solo las conductas dolosas del trabajador", "Las distracciones o imprudencias no temerarias que pudiera cometer el trabajador", "Únicamente los riesgos que ya se hayan materializado en la empresa en los últimos años"]'::jsonb,1,'Art. 15.4 Ley 31/1995','Así lo establece el art. 15.4.',null),
('aux-ayto-mad:17-043425d2e9','aux-ayto-mad',17,'Según la Ley 31/1995, los equipos de protección individual deberán utilizarse:','["Cuando los riesgos no se puedan evitar o limitar suficientemente por medios técnicos de protección colectiva o por la organización del trabajo", "Solo cuando lo pida el trabajador", "Siempre, como primera medida preventiva, antes que la protección colectiva"]'::jsonb,0,'Art. 17.2 Ley 31/1995','Según el art. 17.2, los EPI se usan cuando los riesgos no pueden evitarse o limitarse suficientemente por medios de protección colectiva o medidas de organización.',null),
('aux-ayto-mad:17-5d66f05531','aux-ayto-mad',17,'En las empresas que cuenten con representantes de los trabajadores, la información sobre los riesgos se facilitará a través de dichos representantes, pero deberá informarse directamente a cada trabajador de:','["Las sanciones impuestas a la empresa por la Inspección de Trabajo", "Los riesgos específicos que afecten a su puesto de trabajo o función y de las medidas aplicables", "La evaluación de riesgos de toda la empresa"]'::jsonb,1,'Art. 18.1 Ley 31/1995','Así lo establece el último párrafo del art. 18.1.',null),
('aux-ayto-mad:17-b97752ece3','aux-ayto-mad',17,'La formación en materia preventiva que el empresario debe garantizar a cada trabajador se impartirá:','["Solo en el momento de la contratación, dentro del período de prueba", "Fuera de la jornada de trabajo y sin compensación", "Siempre que sea posible, dentro de la jornada de trabajo o, en su defecto, en otras horas descontando el tiempo invertido"]'::jsonb,2,'Art. 19.2 Ley 31/1995','Según el art. 19.2, se imparte dentro de la jornada o, en su defecto, en otras horas con descuento del tiempo invertido, y su coste no recae en ningún caso sobre los trabajadores.',null),
('aux-ayto-mad:17-0545e65698','aux-ayto-mad',17,'El empresario debe garantizar la formación preventiva de cada trabajador:','["Una sola vez, al inicio de la relación laboral", "En el momento de su contratación, cualquiera que sea la modalidad o duración, y cuando cambien sus funciones o se introduzcan nuevas tecnologías", "Solo a los trabajadores con contrato indefinido, al finalizar el período de prueba"]'::jsonb,1,'Art. 19.1 Ley 31/1995','Así lo establece el art. 19.1, que añade que se repetirá periódicamente si fuera necesario.',null),
('aux-ayto-mad:17-268e759ad0','aux-ayto-mad',17,'Según la Ley 31/1995, el trabajador tiene derecho a interrumpir su actividad y abandonar el lugar de trabajo cuando considere que su actividad entraña:','["Un riesgo grave e inminente para su vida o su salud", "Un riesgo para los bienes de la empresa", "Cualquier riesgo laboral, aunque sea leve"]'::jsonb,0,'Art. 21.2 Ley 31/1995','El art. 21.2 reconoce ese derecho en caso de riesgo grave e inminente para su vida o su salud.',null),
('aux-ayto-mad:17-0c1ae84cd7','aux-ayto-mad',17,'Si los representantes de los trabajadores acuerdan la paralización de la actividad por riesgo grave e inminente, la autoridad laboral anulará o ratificará la paralización en el plazo de:','["Tres días hábiles", "Cuarenta y ocho horas", "Veinticuatro horas"]'::jsonb,2,'Art. 21.3 Ley 31/1995','El acuerdo se comunica de inmediato a la empresa y a la autoridad laboral, que en veinticuatro horas lo anula o ratifica.',null),
('aux-ayto-mad:17-d569e44e0c','aux-ayto-mad',17,'Cuando no sea posible reunir con urgencia al órgano de representación del personal, el acuerdo de paralización por riesgo grave e inminente podrá adoptarse por:','["Decisión mayoritaria de los Delegados de Prevención", "El servicio de prevención ajeno", "El trabajador de mayor antigüedad"]'::jsonb,0,'Art. 21.3 Ley 31/1995','Así lo prevé el segundo párrafo del art. 21.3.',null),
('aux-ayto-mad:17-0dbbb02858','aux-ayto-mad',17,'El incumplimiento por los funcionarios públicos de sus obligaciones en materia de prevención de riesgos tendrá la consideración de:','["Simple incumplimiento sin consecuencias disciplinarias", "Falta, conforme a la normativa sobre régimen disciplinario de los funcionarios", "Delito contra la seguridad de los trabajadores en todo caso"]'::jsonb,1,'Art. 29.3 Ley 31/1995','Para los trabajadores es incumplimiento laboral (art. 58.1 ET); para los funcionarios, falta según su régimen disciplinario.',null),
('aux-ayto-mad:17-c8e3413aae','aux-ayto-mad',17,'Entre las obligaciones de los trabajadores en materia de prevención figura:','["No poner fuera de funcionamiento y utilizar correctamente los dispositivos de seguridad existentes", "Pagar los equipos de protección individual que se le entreguen para su uso personal", "Elaborar la evaluación de riesgos de su puesto"]'::jsonb,0,'Art. 29.2.3.º Ley 31/1995','Es una de las obligaciones del art. 29.2.',null),
('aux-ayto-mad:17-4349f44b7e','aux-ayto-mad',17,'Ante una situación que, a su juicio, entrañe un riesgo para la seguridad y la salud, el trabajador debe informar de inmediato a:','["El Comité de Empresa, exclusivamente", "Su superior jerárquico directo y a los trabajadores designados para actividades de prevención o, en su caso, al servicio de prevención", "La Inspección de Trabajo y Seguridad Social, antes que a nadie"]'::jsonb,1,'Art. 29.2.4.º Ley 31/1995','Así lo establece el art. 29.2.4.º.',null),
('aux-ayto-mad:17-11c9f64b6c','aux-ayto-mad',17,'En las empresas o centros de trabajo con seis o más trabajadores, la participación de estos en la prevención se canaliza:','["A través de sus representantes y de la representación especializada de la Ley 31/1995", "A través del servicio de prevención ajeno", "Directamente, mediante asambleas de todos los trabajadores del centro"]'::jsonb,0,'Art. 34.1 Ley 31/1995','Así lo establece el art. 34.1.',null),
('aux-ayto-mad:17-abcb818ed5','aux-ayto-mad',17,'Según la Ley 31/1995, los Delegados de Prevención son:','["Técnicos de prevención designados por el empresario entre su personal", "Inspectores de Trabajo especializados en prevención", "Los representantes de los trabajadores con funciones específicas en materia de prevención de riesgos en el trabajo"]'::jsonb,2,'Art. 35.1 Ley 31/1995','Así los define el art. 35.1.',null),
('aux-ayto-mad:17-237f12eb5a','aux-ayto-mad',17,'Los Delegados de Prevención son designados:','["Por la Inspección de Trabajo", "Por el empresario entre los trabajadores con formación preventiva", "Por y entre los representantes del personal"]'::jsonb,2,'Art. 35.2 Ley 31/1995','Según el art. 35.2, son designados por y entre los representantes del personal, salvo otros sistemas fijados en convenio (art. 35.4).',null),
('aux-ayto-mad:17-cf4eeabc12','aux-ayto-mad',17,'En una empresa de 101 a 500 trabajadores, el número de Delegados de Prevención es:','["4", "3", "2"]'::jsonb,1,'Art. 35.2 Ley 31/1995','La escala es: 50 a 100, 2; 101 a 500, 3; 501 a 1.000, 4; 1.001 a 2.000, 5; 2.001 a 3.000, 6; 3.001 a 4.000, 7; más de 4.000, 8.',null),
('aux-ayto-mad:17-141d161d25','aux-ayto-mad',17,'En las empresas de más de 4.000 trabajadores, el número de Delegados de Prevención es:','["10", "7", "8"]'::jsonb,2,'Art. 35.2 Ley 31/1995','Según la escala del art. 35.2, de 4.001 en adelante corresponden 8 Delegados de Prevención.',null),
('aux-ayto-mad:17-28b26bc0f7','aux-ayto-mad',17,'En las empresas de hasta treinta trabajadores, el Delegado de Prevención será:','["El Delegado de Personal", "Designado por el empresario", "Elegido directamente por los trabajadores"]'::jsonb,0,'Art. 35.2 Ley 31/1995','En las de hasta 30 trabajadores lo es el Delegado de Personal; en las de 31 a 49 habrá un Delegado de Prevención elegido por y entre los Delegados de Personal.',null),
('aux-ayto-mad:17-7b279b8699','aux-ayto-mad',17,'Para calcular el número de Delegados de Prevención, los trabajadores con contrato de duración determinada superior a un año se computan:','["Según los días trabajados en el último año", "Como medio trabajador", "Como trabajadores fijos de plantilla"]'::jsonb,2,'Art. 35.3 a) Ley 31/1995','Los de contrato superior a un año se computan como fijos; los de hasta un año, según los días trabajados (cada 200 días o fracción, un trabajador más).',null),
('aux-ayto-mad:17-d63397604b','aux-ayto-mad',17,'Para el cómputo de Delegados de Prevención, los contratados por término de hasta un año se computan:','["Un trabajador más por cada cien días trabajados", "Un trabajador más por cada doscientos días trabajados o fracción en el año anterior", "Como trabajadores fijos de plantilla"]'::jsonb,1,'Art. 35.3 b) Ley 31/1995','Así lo establece el art. 35.3 b).',null),
('aux-ayto-mad:17-827aef1ee7','aux-ayto-mad',17,'Los informes que deben emitir los Delegados de Prevención sobre las decisiones del artículo 33 deberán elaborarse en un plazo de:','["Quince días, o en el tiempo imprescindible si se trata de prevenir riesgos inminentes", "Un mes", "Diez días, o cinco si se trata de prevenir riesgos inminentes"]'::jsonb,0,'Art. 36.3 Ley 31/1995','Transcurrido el plazo sin informe, el empresario puede poner en práctica su decisión.',null),
('aux-ayto-mad:17-d376a57271','aux-ayto-mad',17,'La decisión negativa del empresario a adoptar las medidas propuestas por el Delegado de Prevención:','["Deberá ser motivada", "No necesita motivación", "Debe ser autorizada por la Inspección de Trabajo"]'::jsonb,0,'Art. 36.4 Ley 31/1995','Según el art. 36.4, deberá ser motivada.',null),
('aux-ayto-mad:17-54248f6a5e','aux-ayto-mad',17,'El tiempo que dedican los Delegados de Prevención a las reuniones del Comité de Seguridad y Salud se considera:','["Tiempo no retribuido", "Tiempo de trabajo efectivo, sin imputación al crédito horario", "Tiempo imputable al crédito de horas sindicales"]'::jsonb,1,'Art. 37.1 Ley 31/1995','También lo es el tiempo de otras reuniones convocadas por el empresario sobre prevención y el de determinadas visitas.',null),
('aux-ayto-mad:17-59183f4ab9','aux-ayto-mad',17,'El tiempo dedicado por los Delegados de Prevención a su formación preventiva:','["Se imputa a su crédito horario", "Es tiempo libre no retribuido, aunque su coste lo asume el empresario", "Se considera tiempo de trabajo a todos los efectos y su coste no puede recaer sobre ellos"]'::jsonb,2,'Art. 37.2 Ley 31/1995','Así lo establece el art. 37.2.',null),
('aux-ayto-mad:17-ec69002207','aux-ayto-mad',17,'El Comité de Seguridad y Salud es, según la Ley 31/1995:','["Un órgano unipersonal de la empresa encargado de la prevención", "El órgano paritario y colegiado de participación destinado a la consulta regular y periódica de las actuaciones de la empresa en prevención", "El órgano de la Administración laboral que sanciona los incumplimientos de la normativa de prevención"]'::jsonb,1,'Art. 38.1 Ley 31/1995','Así lo define el art. 38.1.',null),
('aux-ayto-mad:17-1ac4227be6','aux-ayto-mad',17,'El Comité de Seguridad y Salud se constituirá en todas las empresas o centros de trabajo que cuenten con:','["30 o más trabajadores", "100 o más trabajadores", "50 o más trabajadores"]'::jsonb,2,'Art. 38.2 Ley 31/1995','Según el art. 38.2, se constituye en las empresas o centros con 50 o más trabajadores.',null),
('aux-ayto-mad:17-aa8889c907','aux-ayto-mad',17,'El Comité de Seguridad y Salud está formado por:','["Los Delegados de Prevención y los Delegados Sindicales", "Los Delegados de Prevención y el empresario o sus representantes en igual número", "El empresario y los técnicos del servicio de prevención"]'::jsonb,1,'Art. 38.2 Ley 31/1995','Es un órgano paritario. Los Delegados Sindicales y los responsables técnicos de la prevención participan con voz pero sin voto.',null),
('aux-ayto-mad:17-e841067730','aux-ayto-mad',17,'En las reuniones del Comité de Seguridad y Salud, los Delegados Sindicales participan:','["Solo como observadores, sin voz", "Con voz pero sin voto", "Con voz y voto"]'::jsonb,1,'Art. 38.2 Ley 31/1995','Así lo establece el art. 38.2.',null)
